function today(){ return new Date().toISOString().split("T")[0]; }
function tomorrow(){ const d=new Date(); d.setDate(d.getDate()+1); return d.toISOString().split("T")[0]; }
function genId(){ return "PK-"+Math.floor(100000+Math.random()*900000); }
// genId() is a random 6-digit id with no uniqueness guarantee — on a rare
// collision (Postgres unique-violation 23505), regenerate and retry instead
// of failing the save outright.
async function insertOrderWithRetry(payload,attempts=5){
  let current=payload;
  for(let i=0;i<attempts;i++){
    const{error}=await supabase.from("orders").insert([current]);
    if(!error)return{error:null,payload:current};
    if(error.code!=="23505")return{error,payload:current};
    current={...current,id:genId()};
  }
  return{error:{message:"Could not generate a unique order ID — please try saving again."},payload:current};
}

// Fire-and-forget audit trail. Never awaited and never throws — if the
// activity_log table hasn't been created yet (see the SQL migration), the
// insert just fails silently and the real action it's logging still succeeds.
function logActivity(user,action,details){
  supabase.from("activity_log").insert([{
    actor_name:user?.name||"",actor_email:user?.email||"",action,details:details||"",
  }]);
}
function fmtMoney(n){ return "₹"+(n||0).toLocaleString("en-IN"); }

// A full-resolution phone photo used as a logo (several MB) gets stored as
// base64 and re-fetched on every page load for every user — downscale to a
// sane display size before it ever reaches the database.
function resizeImageToDataURL(file,maxDim=400,quality=0.85){
  return new Promise((resolve,reject)=>{
    const reader=new FileReader();
    reader.onload=()=>{
      const img=new Image();
      img.onload=()=>{
        let w=img.width,h=img.height;
        if(w>maxDim||h>maxDim){
          const scale=maxDim/Math.max(w,h);
          w=Math.round(w*scale);h=Math.round(h*scale);
        }
        const canvas=document.createElement("canvas");
        canvas.width=w;canvas.height=h;
        canvas.getContext("2d").drawImage(img,0,0,w,h);
        resolve(canvas.toDataURL("image/jpeg",quality));
      };
      img.onerror=reject;
      img.src=reader.result;
    };
    reader.onerror=reject;
    reader.readAsDataURL(file);
  });
}

// Bell Pepper Mix display helper — when both Peppers Red and Peppers Yellow
// appear together, merge them into a single "Bell Pepper Mix" display line
// with "(3+3)" quantity notation. ONLY affects display, not the underlying data.
// The merged item stores _redItem and _yellowItem so calcAmount can sum them correctly
// instead of looking up a non-existent "Bell Pepper Mix" rate in inventory.
// Handles two cases:
// 1. "Bell Pepper Mix" / "Zucchini Mix" ordered directly → pass through, bill calculates on its own rate
// 2. Both individual colours ordered separately → merge for display only (legacy/explicit orders)
function mergeItemsForDisplay(items){
  let processed=[...items];

  // Only merge if BOTH individual colours are present AND no direct Mix item already exists
  const hasBPMix=processed.some(it=>it.name==="Bell Pepper Mix");
  if(!hasBPMix){
    const bpRed=processed.find(it=>it.name==="Bell Pepper Red");
    const bpYellow=processed.find(it=>it.name==="Bell Pepper Yellow");
    if(bpRed&&bpYellow){
      const rQty=bpRed.actual_qty??bpRed.qty;
      const yQty=bpYellow.actual_qty??bpYellow.qty;
      processed=processed.filter(it=>it.name!=="Bell Pepper Red"&&it.name!=="Bell Pepper Yellow");
      processed.push({...bpRed,name:"Bell Pepper Mix",qty:parseFloat(rQty)+parseFloat(yQty),
        display_qty:`(${fmtQty(rQty)}+${fmtQty(yQty)})`,_mixed:true,_redItem:bpRed,_yellowItem:bpYellow});
    }
  }

  const hasZMix=processed.some(it=>it.name==="Zucchini Mix");
  if(!hasZMix){
    const zcGreen=processed.find(it=>it.name==="Green Zucchini");
    const zcYellow=processed.find(it=>it.name==="Yellow Zucchini");
    if(zcGreen&&zcYellow){
      const gQty=zcGreen.actual_qty??zcGreen.qty;
      const yQty=zcYellow.actual_qty??zcYellow.qty;
      processed=processed.filter(it=>it.name!=="Green Zucchini"&&it.name!=="Yellow Zucchini");
      processed.push({...zcGreen,name:"Zucchini Mix",qty:parseFloat(gQty)+parseFloat(yQty),
        display_qty:`(${fmtQty(gQty)}+${fmtQty(yQty)})`,_mixed:true,_redItem:zcGreen,_yellowItem:zcYellow});
    }
  }
  return processed;
}

// Override calcAmount to handle Bell Pepper Mix: sum red and yellow separately
function calcAmountDisplay(item,inventory,customerName){
  if(item._mixed&&item._redItem&&item._yellowItem){
    return calcAmount(item._redItem,inventory,customerName)+calcAmount(item._yellowItem,inventory,customerName);
  }
  return calcAmount(item,inventory,customerName);
}
// Cleans up floating-point arithmetic artifacts (e.g. 100.19999999999999 → 100.2)
// and trims unnecessary trailing zeros for display.
function fmtQty(n){
  const rounded=Math.round((parseFloat(n)||0)*100)/100;
  return rounded.toString();
}

// Code-level safety net: the AI is asked to only use real catalog item names,
// but models can still hallucinate (e.g. defaulting to a generic vegetable name).
// This checks every returned item against the actual inventory list and flags
// anything that doesn't match — independent of what the AI itself claims.
function validateItemsAgainstCatalog(items,inventory){
  const catalog=Object.keys(inventory).length?Object.keys(inventory):DEFAULT_ITEMS;
  const catalogLower=catalog.map(n=>n.toLowerCase());
  return (items||[]).map(it=>{
    const idx=catalogLower.indexOf((it.name||"").toLowerCase().trim());
    if(idx===-1){
      return {...it,_unmatched:true};
    }
    return {...it,name:catalog[idx],_unmatched:false};
  });
}

// Rate is always stored per the item's base unit (usually kg). Convert qty to that
// base unit before multiplying, so grams don't get billed as if they were kg.
function getRate(itemName,inventory,customerName){
  const inv=inventory[itemName];
  if(customerName&&inv?.customerRates?.[customerName]!=null) return inv.customerRates[customerName];
  return inv?.rate ?? DEFAULT_RATES[itemName] ?? 0;
}
// Like getRate, but checks for a one-off rate edited at billing time on the item itself first.
function getEffectiveRate(item,inventory,customerName){
  if(item.override_rate!=null&&item.override_rate!=="") return parseFloat(item.override_rate)||0;
  return getRate(item.name,inventory,customerName);
}
function toBaseQty(qty,unit,baseUnit){
  qty=parseFloat(qty)||0;
  if(unit===baseUnit) return qty;
  if(unit==="grams"&&baseUnit==="kg") return qty/1000;
  if(unit==="kg"&&baseUnit==="grams") return qty*1000;
  return qty; // pcs/bunches/boxes/crates: no conversion possible, use as-is
}
function calcAmount(item,inventory,customerName){
  const baseUnit=inventory[item.name]?.unit||"kg";
  const qty=item.actual_qty??item.qty;
  const baseQty=toBaseQty(qty,item.unit,baseUnit);
  const rate=getEffectiveRate(item,inventory,customerName);
  return baseQty*rate;
}
export function orderTotal(order,inventory){
  // Use mergeItemsForDisplay so Bell Pepper Mix is calculated correctly,
  // and calcAmountDisplay so _mixed items sum Red+Yellow separately.
  const raw=mergeItemsForDisplay(order.items||[]).reduce((s,it)=>s+calcAmountDisplay(it,inventory,order.customer),0);
  return Math.round(raw); // round off to nearest rupee — no paise in cash billing
}

