// ─── AI PARSING ───────────────────────────────────────────────────────────────
// Actual OpenAI call + prompts live server-side in api/parse-order.js —
// the key must never ship in the client bundle (REACT_APP_* vars do).
async function callParseOrder(body){
  const {data:sessionData}=await supabase.auth.getSession();
  const token=sessionData?.session?.access_token||"";
  const r=await fetch("/api/parse-order",{
    method:"POST",
    headers:{"Content-Type":"application/json",Authorization:`Bearer ${token}`},
    body:JSON.stringify(body),
  });
  const d=await r.json();
  if(!r.ok||d.error){console.error("Order parsing error:",d.error);throw new Error(d.error||"AI parsing failed");}
  return d.data;
}
async function parseText(message){
  return callParseOrder({mode:"text",message});
}
async function parseImage(base64){
  return callParseOrder({mode:"image",imageBase64:base64});
}

