function printBill(order,inventory,ledgerEntries=[],showNetDue=false){
  const items=mergeItemsForDisplay(order.items||[]);
  const total=orderTotal(order,inventory);
  const billNo=order.id;
  const billDate=order.delivery_date||order.order_date||today();

  // Only include entries dated BEFORE this order's date so printing old bills
  // doesn't pull in future entries into "Previous balance"
  const custEntries=ledgerEntries.filter(e=>
    e.party_name===order.customer&&
    e.linked_order_id!==order.id&&
    (e.date||"") <= (billDate)
  );
  const pendingBalance=custEntries.reduce((s,e)=>s+(e.entry_type==="gave"?e.amount:-e.amount),0);
  const grandDue=pendingBalance+total; // previous pending + this bill
  const isCash=order.is_cash;

  const w=window.open("","_blank");
  w.document.write(`<html><head><meta charset="UTF-8"><title>Bill ${billNo} — Exotic Greens</title>
  <style>${PRINT_STYLES}</style></head><body>
    <div class="sheet">
      <div class="letterhead">
        <div>
          <img class="logo" src="${COMPANY.logo}"/>
          <div class="company-name">Exotic Greens</div>
          <div class="company-sub">Fresh Exotic Vegetables</div>
          <div class="company-sub">${COMPANY.phone1} · ${COMPANY.phone2}</div>
          <div style="display:flex;align-items:center;gap:5px;margin-top:5px;">
            <img src="${FSSAI_LOGO}" style="height:16px;opacity:0.85;"/>
            <span style="font-size:9px;color:#6B6F62;font-family:'IBM Plex Mono',monospace;letter-spacing:.04em;"> : 21526042001041</span>
          </div>
        </div>
        <div class="doc-meta">
          <div class="doc-title">Bill</div>
          <div class="label">Bill No.</div>
          <div class="val">${billNo}</div>
          <div class="label">Date</div>
          <div class="val">${billDate}</div>
        </div>
      </div>

      <div class="billto">
        <div class="label">Billed to</div>
        <div class="name">${order.customer||"–"}</div>
        ${order.business?`<div class="sub">${order.business}</div>`:""}
        ${order.delivery_location?`<div class="sub">${order.delivery_location}</div>`:""}
      </div>

      <table>
        <thead><tr>
          <th>Particular</th>
          <th class="num">Weight</th>
          <th class="num">Rate</th>
          <th class="num">Amount</th>
        </tr></thead>
        <tbody>
          ${items.map((it,idx)=>{
            const qty=it.actual_qty??it.qty;
            const baseUnit=inventory[it.name]?.unit||"kg";
            const amt=calcAmountDisplay(it,inventory,order.customer);
            const qtyDisplay=it.display_qty?`${it.display_qty} ${it.unit}`:`${fmtQty(qty)} ${it.unit}`;
            // For mixed peppers, show combined rate breakdown instead of ₹0
            let rateDisplay;
            if(it._mixed&&it._redItem&&it._yellowItem){
              const rr=getEffectiveRate(it._redItem,inventory,order.customer);
              const ry=getEffectiveRate(it._yellowItem,inventory,order.customer);
              rateDisplay=rr===ry?`${fmtMoney(rr)}/kg`:`R:${fmtMoney(rr)} Y:${fmtMoney(ry)}`;
            } else {
              const rate=getEffectiveRate(it,inventory,order.customer);
              rateDisplay=`${fmtMoney(rate)}/${baseUnit}`;
            }
            return `<tr>
              <td><span style="color:#999;font-size:10px;margin-right:6px;">${idx+1}.</span>${it.name}</td>
              <td class="num">${qtyDisplay}</td>
              <td class="num">${rateDisplay}</td>
              <td class="num">${fmtMoney(amt)}</td>
            </tr>`;
          }).join("")}
        </tbody>
      </table>

      <div class="totals">
        <div class="totals-box">
          <div class="grand"><span class="gl">This bill</span><span class="gv">${fmtMoney(total)}</span></div>
        </div>
      </div>

      ${showNetDue&&pendingBalance!==0?`
      <div style="margin-top:-10px;margin-bottom:14px;display:flex;justify-content:space-between;align-items:flex-start;gap:14px;">
        <!-- Left column: sig only — QR always in footer below -->
        <div style="text-align:center;width:110px;">
          <img src="${SIGNATURE_IMG}" alt="Signature" style="width:58px;height:34px;object-fit:contain;display:block;margin:0 auto;"/>
          <div style="font-size:10px;font-weight:700;color:#23261F;font-family:'Inter',sans-serif;margin-bottom:2px;">Pranav Takale</div>
          <div style="font-size:8px;text-transform:uppercase;letter-spacing:.06em;color:#6B6F62;font-family:'IBM Plex Mono',monospace;border-top:1px solid #23261F;padding-top:3px;font-weight:600;">Authorised Signatory</div>
        </div>
        <!-- Right column: balance box -->
        <div style="width:200px;border:1.5px solid #23261F;border-radius:3px;padding:8px 10px;flex-shrink:0;">
          <div style="display:flex;justify-content:space-between;font-size:11px;color:#6B6F62;margin-bottom:5px;">
            <span>Previous balance</span><span style="font-family:'IBM Plex Mono',monospace;">${pendingBalance>0?"+":"−"}${fmtMoney(Math.abs(pendingBalance))}</span>
          </div>
          <div style="display:flex;justify-content:space-between;font-size:11px;color:#6B6F62;margin-bottom:7px;">
            <span>This bill</span><span style="font-family:'IBM Plex Mono',monospace;">${fmtMoney(total)}</span>
          </div>
          <div style="display:flex;justify-content:space-between;border-top:1.5px solid #23261F;padding-top:7px;">
            <span style="font-family:'Fraunces',serif;font-weight:700;font-size:13px;">${grandDue>0?"Net due":"Net credit"}</span>
            <span style="font-family:'IBM Plex Mono',monospace;font-weight:700;font-size:16px;color:${grandDue>0?"#2D4A3A":"#8A3A2D"};">${fmtMoney(Math.abs(grandDue))}</span>
          </div>
        </div>
      </div>`
      :`<div class="sig-block">
        <div class="sig-line">
          <img class="sig-img" src="${SIGNATURE_IMG}" alt="Signature" style=""/>
          <div class="sig-name">Pranav Takale</div>
          <div class="sig-label">Authorised Signatory</div>
        </div>
      </div>`}

      ${isCash?`<div style="text-align:right;font-size:10px;font-family:'IBM Plex Mono',monospace;color:#2D4A3A;margin-bottom:12px;font-weight:700;">✓ CASH PAYMENT — PAID IN FULL</div>`:""}

      ${order.notes?`<div class="notes">${order.notes}</div>`:""}

      <div class="footer">
        <div>
          <div class="thanks">Thank you for your business.</div>
          <div class="thanks-sub">Exotic Greens — Fresh Exotic Vegetables</div>
        </div>
        <div class="qr-block">
          <img src="${COMPANY.paymentQR}" alt="Payment QR code"/>
          <div class="qr-label">Scan to pay</div>
        </div>
      </div>
    </div>
    <div class="printbar"><button onclick="window.print()">Print bill</button></div>
  </body></html>`);
  w.document.close();
  setTimeout(()=>w.print(),500);
}

// ─── PACKING WEIGHT MODAL ─────────────────────────────────────────────────────
function PackingWeightModal({order,inventory,onClose,ledgerEntries}){
  const [items,setItems]=useState((order.items||[]).map(it=>({
    ...it,
    actual_qty:it.actual_qty??it.qty,
    // Preserve the frozen rate from previous prints — only blank if never frozen
    override_rate:it.override_rate!=null&&it.override_rate!==""?String(it.override_rate):"",
    bill_unit:it.unit,
  })));
  const [showNetDue,setShowNetDue]=useState(false);

  function updateQty(i,val){const next=[...items];next[i]={...next[i],actual_qty:parseFloat(val)||0};setItems(next);}
  function updateRate(i,val){const next=[...items];next[i]={...next[i],override_rate:val};setItems(next);}
  function updateUnit(i,val){const next=[...items];next[i]={...next[i],bill_unit:val};setItems(next);}

  const billingItems=items.map(it=>({...it,unit:it.bill_unit||it.unit}));

  async function handlePrint(){
    // Freeze the rates shown on this bill back to the order so future prints are identical
    const frozenItems=billingItems.map(it=>({
      ...it,
      override_rate:it.override_rate!=null&&it.override_rate!==""
        ?parseFloat(it.override_rate)
        :getEffectiveRate(it,inventory,order.customer),
    }));
    await supabase.from("orders").update({items:frozenItems}).eq("id",order.id);
    printBill({...order,items:frozenItems},inventory,ledgerEntries||[],showNetDue);
    onClose();
  }

  const UNITS=["kg","grams","pcs","pkt","bunches","boxes","crates"];

  return <Modal onClose={onClose} width={600}>
    <ModalHeader title="Confirm weights & rates" sub="Set actual weight & billing unit — especially for items ordered in pcs but billed by weight" onClose={onClose}/>
    <div style={{padding:22}}>
      <div style={{border:`1px solid ${T.line}`,borderRadius:3,marginBottom:14,overflowX:"auto"}}>
        <div style={{minWidth:460}}>
        <div style={{display:"grid",gridTemplateColumns:"2fr 80px 100px 90px 70px",gap:6,padding:"7px 14px",background:T.paper,borderBottom:`1px solid ${T.line}`,fontSize:10,color:T.inkMuted,fontFamily:FM,textTransform:"uppercase",letterSpacing:"0.04em",fontWeight:600}}>
          <span>Item</span><span>Actual qty</span><span>Bill unit</span><span>Rate (₹)</span><span style={{textAlign:"right"}}>Amount</span>
        </div>
        {items.map((it,i)=>{
          const billingIt={...it,unit:it.bill_unit||it.unit};
          const defaultRate=getRate(it.name,inventory,order.customer);
          const isOverridden=it.override_rate!==""&&it.override_rate!=null;
          const unitChanged=it.bill_unit!==it.unit;
          const amt=calcAmountDisplay(billingIt,inventory,order.customer);
          return <div key={i} style={{display:"grid",gridTemplateColumns:"2fr 80px 100px 90px 70px",gap:6,alignItems:"center",padding:"10px 14px",borderBottom:i<items.length-1?`1px solid ${T.line}`:"none"}}>
            <div>
              <div style={{fontSize:13,fontWeight:600,color:T.ink}}>{it.name}</div>
              <div style={{fontSize:10,color:T.inkMuted,fontFamily:FM}}>ordered: {fmtQty(it.qty)} {it.unit}</div>
            </div>
            <input type="number" value={it.actual_qty} onChange={e=>updateQty(i,e.target.value)}
              style={{padding:"6px 8px",borderRadius:3,border:`1px solid ${T.line}`,fontSize:13,fontFamily:FM,width:"100%"}}/>
            <select value={it.bill_unit||it.unit} onChange={e=>updateUnit(i,e.target.value)}
              style={{padding:"6px 8px",borderRadius:3,border:`1px solid ${unitChanged?T.gold:T.line}`,fontSize:12,background:unitChanged?"#FBF6E9":T.paperWhite,fontFamily:FB,width:"100%"}}>
              {UNITS.map(u=><option key={u}>{u}</option>)}
            </select>
            <input type="number" value={it.override_rate} onChange={e=>updateRate(i,e.target.value)} placeholder={fmtQty(defaultRate)}
              style={{padding:"6px 8px",borderRadius:3,border:`1px solid ${isOverridden?T.gold:T.line}`,fontSize:13,fontFamily:FM,background:isOverridden?"#FBF6E9":T.paperWhite,width:"100%"}}/>
            <span style={{fontSize:12,color:T.moss,fontFamily:FM,textAlign:"right",fontWeight:700}}>{fmtMoney(amt)}</span>
          </div>;
        })}
        </div>
      </div>
      <div style={{fontSize:11,color:T.inkMuted,marginBottom:4}}>💡 If an item was ordered in <b>pcs</b> but you weigh it before billing, change the billing unit to <b>grams</b> or <b>kg</b> and enter the actual weight. The bill will calculate correctly.</div>
      <div style={{fontSize:11,color:T.inkMuted,marginBottom:14}}>Rate field blank = uses customer's saved/catalog rate. Gold highlight = overridden for this bill only.</div>
      <div style={{textAlign:"right",fontFamily:FM,fontSize:16,fontWeight:700,color:T.moss,marginBottom:18}}>
        Total: {fmtMoney(orderTotal({...order,items:billingItems},inventory))}
      </div>
      <div style={{display:"flex",alignItems:"center",gap:10,marginBottom:14,padding:"10px 12px",background:T.paper,borderRadius:3,border:`1px solid ${T.line}`}}>
        <label style={{display:"flex",alignItems:"center",gap:8,cursor:"pointer",fontSize:13,color:T.ink,fontWeight:500}}>
          <input type="checkbox" checked={showNetDue} onChange={e=>setShowNetDue(e.target.checked)} style={{width:16,height:16}}/>
          Show previous balance &amp; net due on bill
        </label>
        <span style={{fontSize:11,color:T.inkMuted,fontFamily:FM}}>(off by default)</span>
      </div>
      <div style={{display:"flex",gap:10}}>
        <button onClick={onClose} style={{...BTN(),border:`1px solid ${T.line}`,background:"transparent",color:T.ink}}>Cancel</button>
        <button onClick={handlePrint} style={{...BTN(),flex:1,background:T.moss,color:T.paperWhite}}>Print bill</button>
      </div>
    </div>
  </Modal>;
}

// ─── ORDER FORM (create/edit) ─────────────────────────────────────────────────
// ─── SEARCHABLE SELECT ────────────────────────────────────────────────────────
function SearchSelect({options,value,onChange,placeholder="Search…",style={}}){
  const [open,setOpen]=useState(false);
  const [q,setQ]=useState("");
  const ref=useRef();
  const filtered=options.filter(o=>(typeof o==="string"?o:o.label).toLowerCase().includes(q.toLowerCase()));
  const display=options.find(o=>(typeof o==="string"?o:o.value)===value);
  const displayLabel=display?(typeof display==="string"?display:display.label):value||"";

  useEffect(()=>{
    function handler(e){if(ref.current&&!ref.current.contains(e.target))setOpen(false);}
    document.addEventListener("mousedown",handler);
    document.addEventListener("touchstart",handler);
    return()=>{document.removeEventListener("mousedown",handler);document.removeEventListener("touchstart",handler);};
  },[]);

  return <div ref={ref} style={{position:"relative",...style}}>
    <div onClick={()=>{setOpen(v=>!v);setQ("");}} style={{...II,cursor:"pointer",display:"flex",justifyContent:"space-between",alignItems:"center",userSelect:"none"}}>
      <span style={{color:displayLabel?T.ink:T.inkMuted}}>{displayLabel||placeholder}</span>
      <span style={{color:T.inkMuted,fontSize:10}}>▾</span>
    </div>
    {open&&<div style={{position:"absolute",top:"100%",left:0,right:0,zIndex:999,background:T.paperWhite,border:`1px solid ${T.line}`,borderRadius:3,boxShadow:"0 4px 12px rgba(0,0,0,0.1)",maxHeight:240,display:"flex",flexDirection:"column"}}>
      <input autoFocus value={q} onChange={e=>setQ(e.target.value)} placeholder="Type to search…"
        style={{padding:"8px 10px",border:"none",borderBottom:`1px solid ${T.line}`,fontSize:13,fontFamily:FB,outline:"none",background:T.paper}}/>
      <div style={{overflowY:"auto",flex:1}}>
        {filtered.length===0
          ?<div style={{padding:"10px",fontSize:12,color:T.inkMuted,fontStyle:"italic"}}>No match</div>
          :filtered.map((o,i)=>{
            const val=typeof o==="string"?o:o.value;
            const label=typeof o==="string"?o:o.label;
            return <div key={i} onClick={()=>{onChange(val);setOpen(false);setQ("");}}
              style={{padding:"9px 12px",fontSize:13,cursor:"pointer",background:val===value?T.paper:"transparent",fontWeight:val===value?600:400,color:T.ink}}
              onMouseEnter={e=>e.currentTarget.style.background=T.paper}
              onMouseLeave={e=>e.currentTarget.style.background=val===value?T.paper:"transparent"}>
              {label}
            </div>;
          })
        }
      </div>
    </div>}
  </div>;
}

function OrderForm({initial,inventory,onSave,onClose,savedCustomers,onSaveCustomer}){
  const isEdit=!!initial?.id;
  const blankItem={name:DEFAULT_ITEMS[0],qty:"",unit:DEFAULT_UNITS[DEFAULT_ITEMS[0]]||"kg",actual_qty:""};

  // Pre-fill override_rate from inventory customerRates for a given customer + item name
  function customerRate(customer,itemName){
    const r=inventory[itemName]?.customerRates?.[customer];
    return r!=null?String(r):"";
  }

  function applyCustomerRates(items,customer){
    if(!customer)return items;
    return items.map(it=>({...it,override_rate:customerRate(customer,it.name)||it.override_rate||""}));
  }

  const [form,setForm]=useState(()=>{
    if(initial){
      // When editing, pre-fill any missing override_rates from inventory customerRates
      return {...initial,items:applyCustomerRates(initial.items||[{...blankItem}],initial.customer)};
    }
    return{id:genId(),customer:"",business:"",phone:"",order_date:today(),
      delivery_date:"",delivery_location:"",notes:"",status:"Pending",
      items:[{...blankItem}],raw_message:""};
  });
  const [saving,setSaving]=useState(false);
  const [err,setErr]=useState("");
  const [saveCustomer,setSaveCustomer]=useState(false);

  function setField(k,v){setForm(f=>({...f,[k]:v}));}
  function setItem(i,k,v){
    const items=[...form.items];
    items[i]={...items[i],[k]:v};
    // If item name changed, auto-fill unit from inventory/defaults and customer rate
    if(k==="name"){
      const defaultUnit=inventory[v]?.unit||DEFAULT_UNITS[v]||"kg";
      items[i].unit=defaultUnit;
      const cr=customerRate(form.customer,v);
      if(cr)items[i].override_rate=cr;
    }
    setField("items",items);
  }
  function addItem(){
    const newItem={...blankItem};
    // Pre-fill customer's known rate for the default item
    const cr=customerRate(form.customer,newItem.name);
    if(cr)newItem.override_rate=cr;
    setField("items",[...form.items,newItem]);
  }
  function removeItem(i){setField("items",form.items.filter((_,j)=>j!==i));}

  function pickSavedCustomer(name){
    const c=(savedCustomers||[]).find(c=>c.name===name);
    if(!c)return;
    // Apply that customer's known rates AND clear any override_rates from previous customer
    setForm(f=>({
      ...f,
      customer:c.name,business:c.business||"",
      phone:c.phone||"",delivery_location:c.delivery_location||f.delivery_location,
      items:applyCustomerRates(f.items.map(it=>({...it,override_rate:""})),c.name),
    }));
  }

  function handleCustomerTyped(val){
    const clean=val.replace(/^#+/,"");
    // Clear override_rates when typing a new customer name
    const items=applyCustomerRates(form.items.map(it=>({...it,override_rate:""})),clean);
    setForm(f=>({...f,customer:clean,items}));
  }

  async function handleSave(){
    if(!form.customer.trim()){setErr("Customer name is required.");return;}
    if(!form.items.length){setErr("Add at least one item.");return;}
    setSaving(true);setErr("");
    const payload={...form,items:form.items.map(it=>({
      ...it,
      qty:parseFloat(it.qty)||0,
      actual_qty:it.actual_qty?parseFloat(it.actual_qty):null,
      override_rate:it.override_rate!=null&&it.override_rate!==""?parseFloat(it.override_rate):null,
    }))};
    let error;
    let savedPayload=payload;
    if(isEdit){
      ({error}=await supabase.from("orders").update(payload).eq("id",form.id));
    } else {
      const r=await insertOrderWithRetry(payload);
      error=r.error;savedPayload=r.payload;
    }
    if(error){setErr("Save failed: "+error.message);setSaving(false);return;}
    if(saveCustomer&&onSaveCustomer){
      onSaveCustomer({name:form.customer,business:form.business,phone:form.phone,delivery_location:form.delivery_location});
    }
    onSave(savedPayload);
    setSaving(false);
  }

  const allItems=Object.keys(inventory).length?Object.keys(inventory):DEFAULT_ITEMS;

  return <Modal onClose={onClose} width={600}>
    <ModalHeader title={isEdit?"Edit order":"Create new order"} sub={isEdit?form.id:"New packing ticket"} onClose={onClose}/>
    <div style={{padding:22}}>
      {err&&<div style={{background:"#F3E3DC",color:T.clay,padding:"10px 14px",borderRadius:2,marginBottom:14,fontSize:13,borderLeft:`3px solid ${T.clay}`}}>{err}</div>}
      {savedCustomers?.length>0&&<div style={{marginBottom:14}}>
        <label style={IL}>Quick-select regular customer</label>
        <SearchSelect
          options={savedCustomers.map(c=>({value:c.name,label:c.name}))}
          value={form.customer}
          onChange={v=>pickSavedCustomer(v)}
          placeholder="— search saved customers —"
        />
      </div>}
      <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(200px,1fr))",gap:12,marginBottom:10}}>
        {[["Customer *","customer"],["Phone","phone"],["Delivery Date","delivery_date"],["Location","delivery_location"],["Notes","notes"]].map(([label,key])=>(
          <div key={key} style={key==="notes"||key==="delivery_location"?{gridColumn:"1/-1"}:{}}>
            <label style={IL}>{label}</label>
            <input value={form[key]||""}
              onChange={e=>key==="customer"?handleCustomerTyped(e.target.value):setField(key,e.target.value)}
              type={key==="delivery_date"?"date":"text"} style={II}/>
          </div>
        ))}
        <div>
          <label style={IL}>Status</label>
          <select value={form.status} onChange={e=>setField("status",e.target.value)} style={II}>
            {STATUS_FLOW.map(s=><option key={s}>{s}</option>)}
          </select>
        </div>
      </div>

      {!isEdit&&<label style={{display:"flex",alignItems:"center",gap:7,fontSize:12,color:T.inkMuted,cursor:"pointer",marginBottom:16}}>
        <input type="checkbox" checked={saveCustomer} onChange={e=>setSaveCustomer(e.target.checked)}/>
        Save "{form.customer||"this customer"}" as a regular customer for quick selection next time
      </label>}

      <label style={{display:"flex",alignItems:"center",gap:8,fontSize:13,cursor:"pointer",marginBottom:16,padding:"10px 14px",borderRadius:3,border:`1px solid ${form.is_cash?T.gold:T.line}`,background:form.is_cash?"#FBF6E9":T.paperWhite,color:form.is_cash?T.moss:T.inkMuted,fontWeight:form.is_cash?700:400}}>
        <input type="checkbox" checked={!!form.is_cash} onChange={e=>setField("is_cash",e.target.checked)}/>
        💵 Cash payment / walk-in (auto-clears balance)
        {isEdit&&form.is_cash!==initial?.is_cash&&<span style={{marginLeft:8,fontSize:11,color:T.clay,fontWeight:400}}>⚠ changing this will update accounts</span>}
      </label>

      <div style={{fontFamily:FD,fontWeight:600,fontSize:14,marginBottom:10,color:T.ink}}>Items</div>
      <div style={{border:`1px solid ${T.line}`,borderRadius:3,marginBottom:12}}>
        <div style={{display:"flex",gap:8,padding:"8px 12px",background:T.paper,borderBottom:`1px solid ${T.line}`,fontSize:10,color:T.inkMuted,fontFamily:FM,textTransform:"uppercase",letterSpacing:"0.04em",flexWrap:"wrap"}}>
          <span style={{flex:"2 0 130px"}}>Item</span>
          <span style={{flex:"1 0 80px"}}>Unit</span>
          <span style={{flex:"1 0 70px"}}>Ordered</span>
          <span style={{flex:"1 0 70px"}}>Actual</span>
          <span style={{flex:"1 0 80px"}}>Rate (₹)</span>
          <span style={{flex:"1 0 70px",textAlign:"right"}}>Total</span>
          <span style={{width:20}}/>
        </div>
        {form.items.map((it,i)=>{
          const defaultRate=getRate(it.name,inventory,form.customer);
          const isOverridden=it.override_rate!=null&&it.override_rate!=="";
          const effectiveRate=isOverridden?parseFloat(it.override_rate)||0:defaultRate;
          const baseUnit=inventory[it.name]?.unit||"kg";
          const qty=(it.actual_qty!=null&&it.actual_qty!=="")?it.actual_qty:(it.qty||0);
          const lineTotal=toBaseQty(qty,it.unit,baseUnit)*effectiveRate;
          return <div key={i} style={{display:"flex",gap:8,padding:"8px 12px",borderBottom:i<form.items.length-1?`1px solid ${T.line}`:"none",alignItems:"center",flexWrap:"wrap"}}>
            <SearchSelect options={allItems} value={it.name} onChange={v=>setItem(i,"name",v)} style={{flex:"2 0 130px"}}/>
            <select value={it.unit} onChange={e=>setItem(i,"unit",e.target.value)} style={{...II,flex:"1 0 80px",padding:"6px 8px"}}>
              {["kg","grams","pcs","pkt","bunches","boxes","crates"].map(u=><option key={u}>{u}</option>)}
            </select>
            <input type="number" value={it.qty} onChange={e=>setItem(i,"qty",e.target.value)} placeholder="ordered" style={{...II,flex:"1 0 70px",padding:"6px 8px",fontFamily:FM}}/>
            <input type="number" value={it.actual_qty||""} onChange={e=>setItem(i,"actual_qty",e.target.value)} placeholder="actual" style={{...II,flex:"1 0 70px",padding:"6px 8px",fontFamily:FM}}/>
            <input type="number" value={it.override_rate??""} onChange={e=>setItem(i,"override_rate",e.target.value)} placeholder={fmtQty(defaultRate)}
              style={{...II,flex:"1 0 80px",padding:"6px 8px",fontFamily:FM,borderColor:isOverridden?T.gold:T.line,background:isOverridden?"#FBF6E9":T.paperWhite}}/>
            <span style={{flex:"1 0 70px",textAlign:"right",fontFamily:FM,fontSize:12,color:T.moss,fontWeight:600}}>{fmtMoney(lineTotal)}</span>
            <button onClick={()=>removeItem(i)} style={{background:"none",border:"none",cursor:"pointer",color:T.clay,fontSize:16,lineHeight:1,padding:8}}>✕</button>
          </div>;
        })}
        <button onClick={addItem} style={{width:"100%",padding:"10px",background:"none",border:"none",borderTop:`1px solid ${T.line}`,cursor:"pointer",fontSize:13,color:T.moss,fontFamily:FB,fontWeight:500}}>
          + Add item
        </button>
      </div>
      <div style={{textAlign:"right",fontFamily:FM,fontSize:13,fontWeight:700,color:T.moss,marginBottom:14}}>
        Total: {fmtMoney(form.items.reduce((s,it)=>{
          const baseUnit=inventory[it.name]?.unit||"kg";
          const qty=(it.actual_qty!=null&&it.actual_qty!=="")?it.actual_qty:(it.qty||0);
          const defaultRate=getRate(it.name,inventory,form.customer);
          const rate=it.override_rate!=null&&it.override_rate!==""?parseFloat(it.override_rate)||0:defaultRate;
          return s+toBaseQty(qty,it.unit,baseUnit)*rate;
        },0))}
      </div>

      <div style={{display:"flex",gap:10,justifyContent:"flex-end"}}>
        <button onClick={onClose} style={{...BTN(),border:`1px solid ${T.line}`,background:"transparent",color:T.ink}}>Cancel</button>
        <button onClick={handleSave} disabled={saving} style={{...BTN(),background:T.moss,color:T.paperWhite}}>
          {saving?"Saving…":isEdit?"Save changes":"Create ticket"}
        </button>
      </div>
    </div>
  </Modal>;
}

// ─── ORDER CARD ───────────────────────────────────────────────────────────────
function OrderCard({order,inventory,onView,onEdit,onDelete,onUpdateStatus,onPrint,userRole,onMarkPaid}){
  const isDelivered=order.status==="Delivered";
  const total=orderTotal(order,inventory);
  const isCash=order.is_cash;
  const isPaid=order.is_paid;
  const [showPayModal,setShowPayModal]=useState(false);

  return <div style={{background:T.paperWhite,border:`1px solid ${T.line}`,borderLeft:`3px solid ${isCash?(isPaid?"#5C8A3D":T.gold):STATUS_CFG[order.status]?.dot||T.sage}`,borderRadius:3,padding:"14px 16px",fontFamily:FB}}>
    <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start",marginBottom:10,gap:10,flexWrap:"wrap"}}>
      <div style={{minWidth:0}}>
        <div style={{display:"flex",alignItems:"center",gap:8,marginBottom:4,flexWrap:"wrap"}}>
          <span style={{fontWeight:600,fontSize:12,fontFamily:FM,color:T.gold}}>{order.id}</span>
          <Badge status={order.status}/>
          {isCash&&<span style={{fontSize:10,fontFamily:FM,fontWeight:700,color:isPaid?"#5C8A3D":T.clay,background:isPaid?"#E1EAD6":"#FCF2EC",padding:"2px 8px",borderRadius:2,textTransform:"uppercase",letterSpacing:"0.04em"}}>
            {isPaid?"PAID":"UNPAID"}
          </span>}
        </div>
        <div style={{fontFamily:FD,fontSize:18,fontWeight:700,color:T.ink,wordBreak:"break-word"}}>{order.customer||"–"}</div>
        {order.business&&<div style={{fontSize:12,color:T.inkMuted,fontStyle:"italic"}}>{order.business}</div>}
      </div>
      <div style={{textAlign:"right",flexShrink:0}}>
        <div style={{fontSize:17,fontWeight:700,color:T.moss,fontFamily:FM}}>{fmtMoney(total)}</div>
        <div style={{fontSize:10,color:T.inkMuted,textTransform:"uppercase",letterSpacing:"0.04em"}}>est. value</div>
      </div>
    </div>
    <div style={{display:"flex",gap:14,fontSize:11,color:T.inkMuted,marginBottom:10,fontFamily:FM,flexWrap:"wrap"}}>
      <span>Deliver {order.delivery_date}</span>
      <span>{(order.items||[]).length} items</span>
      {order.phone&&<span>{order.phone}</span>}
    </div>
    <div style={{display:"flex",flexWrap:"wrap",gap:5,marginBottom:12}}>
      {mergeItemsForDisplay(order.items||[]).map((it,i)=>(
        <span key={i} style={{background:T.paper,fontSize:12,padding:"4px 9px",borderRadius:2,color:T.ink,border:`1px solid ${T.line}`,fontWeight:500}}>
          {it.name} · {it.display_qty||fmtQty(it.actual_qty??it.qty)} {it.unit}
        </span>
      ))}
    </div>
    <div style={{display:"flex",gap:6,flexWrap:"wrap",borderTop:`1px solid ${T.line}`,paddingTop:11}}>
      <label style={{display:"flex",alignItems:"center",gap:6,fontSize:12,color:T.ink,cursor:"pointer",padding:"7px 10px",border:`1px solid ${T.line}`,borderRadius:3,background:isDelivered?"#E1EAD6":"transparent"}}>
        <input type="checkbox" checked={isDelivered} onChange={()=>onUpdateStatus(order.id,isDelivered?"Pending":"Delivered")} style={{margin:0}}/>
        Delivered
      </label>
      {isCash&&!isPaid&&<button onClick={()=>setShowPayModal(true)} style={{...BTN(),padding:"7px 12px",background:T.gold,color:T.paperWhite,fontSize:12,fontWeight:700}}>Mark Paid</button>}
      <button onClick={()=>onView(order)} style={{...BTN(),flex:"1 0 70px",padding:"7px 0",background:"transparent",border:`1px solid ${T.line}`,color:T.ink,fontSize:12}}>View</button>
      <button onClick={()=>onEdit(order)} style={{...BTN(),flex:"1 0 70px",padding:"7px 0",background:"transparent",border:`1px solid ${T.line}`,color:T.ink,fontSize:12}}>Edit</button>
      {userRole==="admin"&&<button onClick={()=>onPrint(order)} style={{...BTN(),flex:"1 0 70px",padding:"7px 0",background:"transparent",border:`1px solid ${T.line}`,color:T.inkMuted,fontSize:12}}>Print</button>}
      {userRole==="admin"&&<button onClick={()=>onDelete(order.id)} style={{...BTN(),flex:"1 0 70px",padding:"7px 0",background:"transparent",border:`1px solid ${T.clay}`,color:T.clay,fontSize:12}}>Delete</button>}
    </div>

    {showPayModal&&<div onClick={()=>setShowPayModal(false)} style={{position:"fixed",inset:0,background:"rgba(28,30,23,0.6)",display:"flex",alignItems:"center",justifyContent:"center",zIndex:1000}}>
      <div onClick={e=>e.stopPropagation()} style={{background:T.paperWhite,borderRadius:4,padding:28,width:320,border:`1px solid ${T.line}`,boxShadow:"0 20px 60px rgba(0,0,0,0.3)"}}>
        <div style={{fontFamily:FD,fontWeight:700,fontSize:18,marginBottom:6}}>Payment received</div>
        <div style={{fontSize:13,color:T.inkMuted,marginBottom:20}}>How did {order.customer} pay {fmtMoney(total)}?</div>
        <div style={{display:"grid",gap:10}}>
          <button onClick={()=>{onMarkPaid&&onMarkPaid(order.id,"cash");setShowPayModal(false);}} style={{...BTN(),padding:"13px 0",background:T.moss,color:T.paperWhite,fontSize:14,fontWeight:700}}>💵 Cash</button>
          <button onClick={()=>{onMarkPaid&&onMarkPaid(order.id,"paytm");setShowPayModal(false);}} style={{...BTN(),padding:"13px 0",background:"#0a4a9a",color:T.paperWhite,fontSize:14,fontWeight:700}}>📱 Paytm</button>
        </div>
        <button onClick={()=>setShowPayModal(false)} style={{width:"100%",marginTop:12,padding:"10px",background:"none",border:`1px solid ${T.line}`,borderRadius:3,cursor:"pointer",fontSize:12,color:T.inkMuted,fontFamily:FB}}>Cancel</button>
      </div>
    </div>}
  </div>;
}

// ─── VEGETABLE PACKING LIST VIEW ─────────────────────────────────────────────
// ─── CUSTOMER PACKING VIEW — supply-sheet format (by customer, 2-col grid) ──
function CustomerPackingView({orders,onlyDate,inventory,onUpdateActualQty}){
  const relevant=onlyDate
    ?orders.filter(o=>o.delivery_date===onlyDate&&o.status!=="Delivered")
    :orders.filter(o=>o.status!=="Delivered");

  const sorted=[...relevant].sort((a,b)=>(a.customer||"").localeCompare(b.customer||""));

  const [actualWeights,setActualWeights]=useState({});
  const [rateEdits,setRateEdits]=useState({});
  const [saving,setSaving]=useState({});

  function ak(o,i){return `a-${o.id}-${i}`;}
  function rk(o,i){return `r-${o.id}-${i}`;}

  function getActual(o,it,i){
    const k=ak(o,i);
    return actualWeights[k]!==undefined?actualWeights[k]:(it.actual_qty!=null?String(it.actual_qty):"");
  }
  function getRate(o,it,i,name){
    const k=rk(o,i);
    if(rateEdits[k]!==undefined)return rateEdits[k];
    if(it.override_rate!=null)return String(it.override_rate);
    const cr=inventory?.[name]?.customerRates?.[o.customer];
    if(cr!=null)return String(cr);
    return "";
  }
  function defRate(name){return inventory?.[name]?.rate||DEFAULT_RATES[name]||0;}

  async function saveActual(o,it,i){
    const k=ak(o,i);
    const val=parseFloat(actualWeights[k]);
    if(!val&&val!==0)return;
    setSaving(p=>({...p,[k]:true}));
    const updatedItems=o.items.map((x,j)=>j===i?{...x,actual_qty:val}:x);
    await supabase.from("orders").update({items:updatedItems}).eq("id",o.id);
    onUpdateActualQty&&onUpdateActualQty(o.id,updatedItems);
    setSaving(p=>({...p,[k]:false}));
  }

  async function saveRate(o,it,i,name){
    const k=rk(o,i);
    const val=parseFloat(rateEdits[k]);
    if(!val&&val!==0)return;
    setSaving(p=>({...p,[k]:true}));
    const updatedItems=o.items.map((x,j)=>j===i?{...x,override_rate:val}:x);
    await supabase.from("orders").update({items:updatedItems}).eq("id",o.id);
    onUpdateActualQty&&onUpdateActualQty(o.id,updatedItems);
    if(inventory?.[name]){
      const current=inventory[name];
      const updatedRates={...(current.customerRates||{}),[o.customer]:val};
      await supabase.from("inventory").upsert([{name,qty:current.qty,unit:current.unit,rate:current.rate,customer_rates:updatedRates}]);
    }
    setSaving(p=>({...p,[k]:false}));
  }

  function orderBill(o){
    return mergeItemsForDisplay(o.items||[]).reduce((s,it)=>s+calcAmountDisplay(it,inventory,o.customer),0);
  }

  function printCustomerPacking(){
    const date=onlyDate||today();
    const boxes=sorted.map(o=>{
      const displayItems=mergeItemsForDisplay(o.items||[]);
      const bill=orderBill(o);
      return `
      <div class="box">
        <div class="box-header">Supply <strong>${o.customer||"Unknown"}</strong></div>
        <table>
          <thead><tr>
            <th class="col-actual">Actual wt.</th>
            <th class="col-item">Item</th>
            <th class="col-qty">Ordered</th>
            <th class="col-rate">Rate</th>
          </tr></thead>
          <tbody>
          ${displayItems.map(it=>{
            const qty=it.actual_qty??it.qty;
            return `<tr>
              <td class="col-actual"></td>
              <td class="col-item"><strong>${it.name}</strong></td>
              <td class="col-qty">${it.display_qty||fmtQty(qty)}${it.unit}</td>
              <td class="col-rate"></td>
            </tr>`;
          }).join("")}
          </tbody>
        </table>
        <div class="box-footer">
          <span>Amt</span><span style="border-bottom:1.5px solid #000;min-width:60px;display:inline-block;">&nbsp;</span>
        </div>
      </div>`;
    }).join("");

    const w=window.open("","_blank");
    w.document.write(`<html><head><meta charset="UTF-8"><title>Supply Sheet ${date}</title>
    <style>
      body{font-family:Arial,sans-serif;padding:10px 12px;background:#fff;font-size:13px;}
      h2{text-align:center;margin-bottom:2px;font-size:17px;}
      .date{text-align:center;font-size:12px;color:#555;margin-bottom:10px;}
      /* Use CSS columns instead of grid so boxes flow naturally without gaps */
      .grid{columns:2;column-gap:10px;}
      .box{border:2px solid #222;break-inside:avoid;-webkit-column-break-inside:avoid;margin-bottom:10px;display:inline-table;width:100%;}
      .box-header{background:#e8e8e8;font-size:13px;padding:5px 8px;border-bottom:2px solid #222;}
      table{width:100%;border-collapse:collapse;}
      thead th{font-size:9px;text-transform:uppercase;letter-spacing:.04em;color:#666;padding:3px 6px;border-bottom:1.5px solid #222;text-align:left;}
      tr{border-bottom:1px solid #ccc;}
      td{padding:4px 6px;font-size:12px;vertical-align:middle;}
      .col-actual{width:18%;border-right:1px dashed #aaa;}
      .col-item{width:40%;}
      .col-qty{width:22%;font-weight:700;}
      .col-rate{width:20%;border-left:1px dashed #aaa;}
      .box-footer{display:flex;justify-content:space-between;padding:5px 8px;border-top:2px solid #222;font-weight:700;background:#f0f0f0;font-size:14px;}
      @media print{
        button{display:none;}
        body{padding:6px 8px;}
        @page{margin:8mm;}
      }
    </style></head><body>
    <h2>।। Exotic Greens ।। Supply Sheet</h2>
    <div class="date">${date}</div>
    <div class="grid">${boxes}</div>
    <br/><button onclick="window.print()" style="display:block;margin:0 auto;padding:8px 24px;background:#2D4A3A;color:#fff;border:none;border-radius:3px;cursor:pointer;font-size:13px;">Print</button>
    </body></html>`);
    w.document.close();
    setTimeout(()=>w.print(),400);
  }

  return <div>
    <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:16,flexWrap:"wrap",gap:10}}>
      <div style={{fontSize:12,color:T.inkMuted,fontFamily:FM}}>{sorted.length} customers — supply sheet format</div>
      <button onClick={printCustomerPacking} style={{...BTN(),background:T.moss,color:T.paperWhite}}>Print supply sheet</button>
    </div>

    {sorted.length===0
      ?<div style={{textAlign:"center",padding:50,color:T.inkMuted,fontFamily:FD,fontStyle:"italic",fontSize:15}}>No pending orders.</div>
      :<div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(300px,1fr))",gap:"0 20px"}}>
        {sorted.map(o=>{
          const displayItems=mergeItemsForDisplay(o.items||[]);
          const bill=orderBill(o);
          return <div key={o.id} style={{borderBottom:`2px solid ${T.ink}`,marginBottom:14,paddingBottom:8}}>
            <div style={{background:T.paper,padding:"6px 0",borderTop:`2px solid ${T.ink}`,borderBottom:`1px solid ${T.ink}`,marginBottom:4}}>
              <span style={{fontSize:16,fontWeight:700,color:T.ink}}>Supply </span>
              <span style={{fontSize:16,fontWeight:700,color:T.moss}}>{o.customer||"Unknown"}</span>
            </div>
            {/* Column headers */}
            <div style={{display:"grid",gridTemplateColumns:"1fr 70px 70px",gap:"0 4px",padding:"2px 0",borderBottom:`1px solid ${T.line}`,marginBottom:2}}>
              <span style={{fontSize:10,color:T.inkMuted,fontFamily:FM,textTransform:"uppercase",letterSpacing:"0.04em",fontWeight:600}}>Item</span>
              <span style={{fontSize:10,color:T.inkMuted,fontFamily:FM,textTransform:"uppercase",letterSpacing:"0.04em",fontWeight:600,textAlign:"center"}}>Actual wt.</span>
              <span style={{fontSize:10,color:T.inkMuted,fontFamily:FM,textTransform:"uppercase",letterSpacing:"0.04em",fontWeight:600,textAlign:"center"}}>Rate ₹</span>
            </div>
            {o.items.map((it,i)=>{
              const a=getActual(o,it,i);
              const r=getRate(o,it,i,it.name);
              const dr=defRate(it.name);
              const aSaved=it.actual_qty!=null&&a===String(it.actual_qty);
              const rSaved=it.override_rate!=null&&r===String(it.override_rate);
              const hasCustomRate=inventory?.[it.name]?.customerRates?.[o.customer]!=null;
              return <div key={i} style={{display:"grid",gridTemplateColumns:"1fr 70px 70px",gap:"0 4px",padding:"4px 0",borderBottom:`1px solid ${T.line}`,alignItems:"center"}}>
                <span style={{fontSize:14,color:T.ink,fontWeight:600}}>{it.name}
                  <span style={{fontSize:11,color:T.inkMuted,fontFamily:FM,marginLeft:5}}>{fmtQty(it.qty)}{it.unit}</span>
                </span>
                <div style={{display:"flex",gap:2}}>
                  <input type="number" value={a} onChange={e=>setActualWeights(p=>({...p,[ak(o,i)]:e.target.value}))}
                    onKeyDown={e=>e.key==="Enter"&&saveActual(o,it,i)}
                    placeholder={fmtQty(it.qty)}
                    style={{width:"100%",padding:"3px 5px",borderRadius:3,border:`1px solid ${a&&!aSaved?T.gold:T.line}`,fontSize:12,fontFamily:FM,background:aSaved?"#E8F0E3":"transparent"}}/>
                  <button onClick={()=>saveActual(o,it,i)} disabled={!a||saving[ak(o,i)]}
                    style={{width:22,height:26,borderRadius:2,border:"none",background:aSaved?"#5C8A3D":T.moss,color:T.paperWhite,cursor:"pointer",fontSize:12,flexShrink:0}}>
                    {saving[ak(o,i)]?"…":"✓"}
                  </button>
                </div>
                <div style={{display:"flex",gap:2}}>
                  <input type="number" value={r} onChange={e=>setRateEdits(p=>({...p,[rk(o,i)]:e.target.value}))}
                    onKeyDown={e=>e.key==="Enter"&&saveRate(o,it,i,it.name)}
                    placeholder={String(dr)}
                    style={{width:"100%",padding:"3px 5px",borderRadius:3,border:`1px solid ${r&&r!==String(dr)?T.gold:T.line}`,fontSize:12,fontFamily:FM,background:hasCustomRate?"#FBF6E9":"transparent"}}/>
                  <button onClick={()=>saveRate(o,it,i,it.name)} disabled={!r||saving[rk(o,i)]}
                    style={{width:22,height:26,borderRadius:2,border:"none",background:T.gold,color:T.paperWhite,cursor:"pointer",fontSize:12,flexShrink:0}}>
                    {saving[rk(o,i)]?"…":"✓"}
                  </button>
                </div>
              </div>;
            })}
            <div style={{display:"flex",justifyContent:"space-between",paddingTop:5}}>
              <span style={{fontSize:13,color:T.inkMuted,fontFamily:FM,fontWeight:600}}>Bill</span>
              <span style={{fontSize:16,fontFamily:FM,fontWeight:700,color:T.moss}}>{fmtMoney(bill)}</span>
            </div>
          </div>;
        })}
      </div>
    }
  </div>;
}

function PackingListView({orders,onlyDate,onUpdateActualQty,inventory}){
  const relevant=onlyDate?orders.filter(o=>o.delivery_date===onlyDate&&o.status!=="Delivered"):orders.filter(o=>o.status!=="Delivered");

  const byItem={};
  relevant.forEach(o=>{
    (o.items||[]).forEach((it,idx)=>{
      if(!byItem[it.name])byItem[it.name]=[];
      byItem[it.name].push({customer:o.customer||"–",qty:it.qty,actual_qty:it.actual_qty,unit:it.unit,orderId:o.id,order:o,itemIdx:idx,override_rate:it.override_rate});
    });
  });
  const itemNames=Object.keys(byItem).sort();

  const [selectedItems,setSelectedItems]=useState([]); // empty = show all
  const [showItemFilter,setShowItemFilter]=useState(false);
  const [actualWeights,setActualWeights]=useState({});
  const [rateEdits,setRateEdits]=useState({});
  const [saving,setSaving]=useState({});

  const visibleItems=selectedItems.length>0?itemNames.filter(n=>selectedItems.includes(n)):itemNames;

  function toggleItem(name){
    setSelectedItems(prev=>prev.includes(name)?prev.filter(n=>n!==name):[...prev,name]);
  }

  // ── helpers ──
  function getActual(r){ const k=`a-${r.orderId}-${r.itemIdx}`; return actualWeights[k]!==undefined?actualWeights[k]:(r.actual_qty!=null?String(r.actual_qty):""); }
  function setActual(r,v){ setActualWeights(p=>({...p,[`a-${r.orderId}-${r.itemIdx}`]:v})); }

  function getRate(r,name){
    const k=`rt-${r.orderId}-${r.itemIdx}`;
    if(rateEdits[k]!==undefined)return rateEdits[k];
    if(r.override_rate!=null)return String(r.override_rate);
    const custRate=inventory?.[name]?.customerRates?.[r.customer];
    if(custRate!=null)return String(custRate);
    return "";
  }
  function setRate(r,v){ setRateEdits(p=>({...p,[`rt-${r.orderId}-${r.itemIdx}`]:v})); }

  function defaultRate(r,name){ return inventory?.[name]?.rate||DEFAULT_RATES[name]||0; }

  async function saveActual(r){
    const k=`a-${r.orderId}-${r.itemIdx}`;
    const val=parseFloat(actualWeights[k]);
    if(!val&&val!==0)return;
    setSaving(p=>({...p,[k]:true}));
    const updatedItems=r.order.items.map((it,i)=>i===r.itemIdx?{...it,actual_qty:val}:it);
    await supabase.from("orders").update({items:updatedItems}).eq("id",r.orderId);
    onUpdateActualQty&&onUpdateActualQty(r.orderId,updatedItems);
    setSaving(p=>({...p,[k]:false}));
  }

  async function saveRate(r,name){
    const k=`rt-${r.orderId}-${r.itemIdx}`;
    const val=parseFloat(rateEdits[k]);
    if(!val&&val!==0)return;
    setSaving(p=>({...p,[k]:true}));

    // 1. Save as override_rate on this order's item
    const updatedItems=r.order.items.map((it,i)=>i===r.itemIdx?{...it,override_rate:val}:it);
    await supabase.from("orders").update({items:updatedItems}).eq("id",r.orderId);
    onUpdateActualQty&&onUpdateActualQty(r.orderId,updatedItems);

    // 2. Remember as this customer's rate for this item in inventory
    if(inventory?.[name]){
      const current=inventory[name];
      const updatedRates={...(current.customerRates||{}),[r.customer]:val};
      await supabase.from("inventory").upsert([{name,qty:current.qty,unit:current.unit,rate:current.rate,customer_rates:updatedRates}]);
    }

    setSaving(p=>({...p,[k]:false}));
  }

  function printList(){
    const w=window.open("","_blank");
    w.document.write(`<html><head><meta charset="UTF-8"><title>Packing List</title>
    <style>body{font-family:Arial,sans-serif;padding:24px;font-size:13px;max-width:500px;margin:0 auto;}
    h2{margin-bottom:2px;} .sub{color:#666;font-size:12px;margin-bottom:16px;}
    .item{margin-bottom:16px;} .item-name{font-weight:700;font-size:15px;border-bottom:2px solid #000;padding-bottom:4px;margin-bottom:6px;}
    .row{display:flex;justify-content:space-between;padding:4px 0;border-bottom:1px solid #eee;}
    @media print{button{display:none;}}</style></head><body>
    <h2>Exotic Greens — Packing List</h2>
    <div class="sub">${onlyDate?`Delivery date: ${onlyDate}`:"All pending orders"} · Generated ${new Date().toLocaleString()}${selectedItems.length>0?` · Filtered: ${selectedItems.length} items`:""}</div>
    ${visibleItems.map(name=>{
      const rows=byItem[name];
      const totalQty=rows.reduce((s,r)=>s+r.qty,0);
      return `<div class="item">
        <div class="item-name">${name} — Total: ${fmtQty(totalQty)}${rows[0]?.unit||""}</div>
        ${rows.map(r=>`<div class="row"><span>${r.customer} (${r.orderId})</span><span>${fmtQty(r.qty)}${r.unit}</span></div>`).join("")}
      </div>`;
    }).join("")}
    <br/><button onclick="window.print()">Print</button>
    </body></html>`);
    w.document.close();
    setTimeout(()=>w.print(),400);
  }

  function downloadExcel(){
    const rows=[];
    itemNames.forEach(name=>{
      byItem[name].forEach(r=>{
        rows.push({ Item:name, Customer:r.customer, "Order ID":r.orderId, Ordered:fmtQty(r.qty), "Actual Weight":r.actual_qty!=null?fmtQty(r.actual_qty):"", Unit:r.unit });
      });
      const totalQty=byItem[name].reduce((s,r)=>s+r.qty,0);
      rows.push({ Item:`${name} — TOTAL`, Customer:"", "Order ID":"", Ordered:fmtQty(totalQty), "Actual Weight":"", Unit:byItem[name][0]?.unit||"" });
      rows.push({ Item:"", Customer:"", "Order ID":"", Ordered:"", "Actual Weight":"", Unit:"" });
    });
    const ws=XLSX.utils.json_to_sheet(rows);
    ws["!cols"]=[{wch:22},{wch:20},{wch:12},{wch:10},{wch:12},{wch:8}];
    const wb=XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb,ws,"Packing List");
    XLSX.writeFile(wb,`packing-list-${onlyDate||today()}.xlsx`);
  }

  return <div>
    <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:16,flexWrap:"wrap",gap:10}}>
      <div style={{fontSize:12,color:T.inkMuted,fontFamily:FM}}>{visibleItems.length}/{itemNames.length} items · {relevant.length} pending orders</div>
      <div style={{display:"flex",gap:8}}>
        <button onClick={()=>setShowItemFilter(v=>!v)} style={{...BTN(),border:`1px solid ${T.line}`,background:selectedItems.length>0?T.gold:"transparent",color:selectedItems.length>0?T.paperWhite:T.ink}}>
          {selectedItems.length>0?`${selectedItems.length} items selected`:"Filter items"}
        </button>
        <button onClick={printList} style={{...BTN(),background:T.moss,color:T.paperWhite}}>Print / save as PDF</button>
        <button onClick={downloadExcel} style={{...BTN(),border:`1px solid ${T.line}`,background:"transparent",color:T.ink}}>Download Excel</button>
      </div>
    </div>
    {visibleItems.length===0&&itemNames.length>0
      ?<div style={{textAlign:"center",padding:30,color:T.inkMuted,fontStyle:"italic",fontFamily:FD}}>No items match filter — clear filter to see all</div>
      :itemNames.length===0
      ?<div style={{textAlign:"center",padding:50,color:T.inkMuted,fontFamily:FD,fontStyle:"italic",fontSize:15}}>No pending orders.</div>
      :<>
        {showItemFilter&&<div style={{background:T.paperWhite,border:`1px solid ${T.line}`,borderRadius:3,padding:14,marginBottom:14}}>
          <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:10}}>
            <span style={{fontSize:12,fontWeight:600,color:T.ink,fontFamily:FD}}>Select items to show/print</span>
            <div style={{display:"flex",gap:8}}>
              <button onClick={()=>setSelectedItems([...itemNames])} style={{fontSize:11,color:T.moss,background:"none",border:"none",cursor:"pointer",fontWeight:600}}>All</button>
              <button onClick={()=>setSelectedItems([])} style={{fontSize:11,color:T.clay,background:"none",border:"none",cursor:"pointer",fontWeight:600}}>None</button>
            </div>
          </div>
          <div style={{display:"flex",flexWrap:"wrap",gap:6}}>
            {itemNames.map(name=>(
              <button key={name} onClick={()=>toggleItem(name)} style={{padding:"5px 10px",borderRadius:20,border:`1px solid ${selectedItems.includes(name)||selectedItems.length===0?T.moss:T.line}`,background:selectedItems.includes(name)?T.moss:selectedItems.length===0?"#E8F0E3":T.paperWhite,color:selectedItems.includes(name)||selectedItems.length===0?T.moss:T.inkMuted,fontSize:12,cursor:"pointer",fontWeight:selectedItems.includes(name)?700:400}}>
                {name}
              </button>
            ))}
          </div>
        </div>}
        <div style={{display:"grid",gap:14}}>
        {visibleItems.map(name=>{
          const rows=byItem[name];
          const totalQty=rows.reduce((s,r)=>s+r.qty,0);
          return <div key={name} style={{background:T.paperWhite,border:`1px solid ${T.line}`,borderRadius:3,overflow:"hidden"}}>
            <div style={{background:T.paper,padding:"11px 16px",display:"flex",justifyContent:"space-between",alignItems:"center",borderBottom:`1px solid ${T.line}`}}>
              <span style={{fontFamily:FD,fontWeight:600,fontSize:16,color:T.ink}}>{name}</span>
              <span style={{fontFamily:FM,fontWeight:600,fontSize:14,color:T.moss}}>{fmtQty(totalQty)}{rows[0]?.unit} ordered</span>
            </div>
            <div style={{display:"flex",gap:8,padding:"6px 16px",background:"#F7F6F2",borderBottom:`1px solid ${T.line}`,fontSize:10,color:T.inkMuted,fontFamily:FM,textTransform:"uppercase",letterSpacing:"0.04em",flexWrap:"wrap"}}>
              <span style={{flex:2}}>Customer</span>
              <span style={{width:70}}>Ordered</span>
              <span style={{width:96}}>Actual wt.</span>
              <span style={{width:32}}/>
              <span style={{width:96}}>Rate (₹)</span>
              <span style={{width:32}}/>
            </div>
            <div>
              {rows.map((r,i)=>{
                const ak=`a-${r.orderId}-${r.itemIdx}`;
                const rk=`rt-${r.orderId}-${r.itemIdx}`;
                const actual=getActual(r);
                const rate=getRate(r,name);
                const defRate=defaultRate(r,name);
                const actualSaved=r.actual_qty!=null&&actual===String(r.actual_qty);
                const rateSaved=saving[rk]===false; // briefly true after save
                const hasCustomRate=inventory?.[name]?.customerRates?.[r.customer]!=null;
                return <div key={i} style={{display:"flex",gap:8,alignItems:"center",padding:"10px 16px",borderBottom:i<rows.length-1?`1px solid ${T.line}`:"none",flexWrap:"wrap"}}>
                  <span style={{flex:2,fontSize:13,color:T.ink,minWidth:100}}>
                    {r.customer}
                    {hasCustomRate&&<span style={{marginLeft:6,fontSize:9,color:T.gold,fontFamily:FM,textTransform:"uppercase",letterSpacing:"0.04em"}}>rate saved</span>}
                    <br/><span style={{color:T.inkMuted,fontFamily:FM,fontSize:11}}>({r.orderId})</span>
                  </span>
                  <span style={{width:70,fontFamily:FM,fontSize:12,color:T.inkMuted}}>{fmtQty(r.qty)}{r.unit}</span>
                  {/* Actual weight */}
                  <input type="number" value={actual} onChange={e=>setActual(r,e.target.value)} onKeyDown={e=>e.key==="Enter"&&saveActual(r)}
                    placeholder={`wt.`}
                    style={{...II,width:88,padding:"5px 8px",fontFamily:FM,fontSize:12,border:`1px solid ${actual&&!actualSaved?T.gold:T.line}`,background:actualSaved?"#E8F0E3":"transparent"}}/>
                  <button onClick={()=>saveActual(r)} disabled={!actual||saving[ak]}
                    style={{width:32,height:32,borderRadius:3,border:"none",background:actualSaved?"#5C8A3D":T.moss,color:T.paperWhite,cursor:"pointer",fontSize:15,flexShrink:0}}>
                    {saving[ak]?"…":"✓"}
                  </button>
                  {/* Rate */}
                  <input type="number" value={rate} onChange={e=>setRate(r,e.target.value)} onKeyDown={e=>e.key==="Enter"&&saveRate(r,name)}
                    placeholder={String(defRate)}
                    style={{...II,width:88,padding:"5px 8px",fontFamily:FM,fontSize:12,border:`1px solid ${rate&&rate!==String(defRate)?T.gold:T.line}`,background:hasCustomRate?"#FBF6E9":"transparent"}}/>
                  <button onClick={()=>saveRate(r,name)} disabled={!rate||saving[rk]}
                    style={{width:32,height:32,borderRadius:3,border:"none",background:T.gold,color:T.paperWhite,cursor:"pointer",fontSize:15,flexShrink:0}}>
                    {saving[rk]?"…":"✓"}
                  </button>
                </div>;
              })}
            </div>
          </div>;
        })}
        </div>
      </>
    }
  </div>;
}

// ─── DASHBOARD ────────────────────────────────────────────────────────────────
function Dashboard({orders,inventory,onUpdateStatus,onView,onEdit,onDelete,onPrint,onNew,userRole,onUpdateActualQty,onMarkPaid}){
  const [search,setSearch]=useState("");
  const [filterStatus,setFilterStatus]=useState("All");
  const [filterDate,setFilterDate]=useState("");
  const [sortBy,setSortBy]=useState("delivery_date");
  const [view,setView]=useState("cards");
  const [listDate,setListDate]=useState("");
  const [orderSection,setOrderSection]=useState("regular"); // regular | cash

  // Search re-renders this whole (potentially large) list on every keystroke —
  // deferring it keeps typing responsive on slower phones instead of blocking
  // on the filter+sort of the full order history each key press.
  const deferredSearch=useDeferredValue(search);

  const filtered=useMemo(()=>orders
    .filter(o=>{
      const q=deferredSearch.toLowerCase();
      const matchSearch=!q||o.id?.toLowerCase().includes(q)||o.customer?.toLowerCase().includes(q);
      const matchStatus=filterStatus==="All"||o.status===filterStatus;
      const matchDate=!filterDate||o.delivery_date===filterDate;
      return matchSearch&&matchStatus&&matchDate;
    })
    .sort((a,b)=>{
      switch(sortBy){
        case "delivery_date": return (a.delivery_date||"9999").localeCompare(b.delivery_date||"9999");
        case "delivery_date_desc": return (b.delivery_date||"").localeCompare(a.delivery_date||"");
        case "customer": return (a.customer||"").localeCompare(b.customer||"");
        case "created_at_desc": return (b.created_at||"").localeCompare(a.created_at||"");
        default: return 0;
      }
    }),[orders,deferredSearch,filterStatus,filterDate,sortBy]);

  const stats=useMemo(()=>[
    ["Total",orders.length,T.moss],
    ["Pending",orders.filter(o=>o.status==="Pending").length,T.gold],
    ["Delivered",orders.filter(o=>o.status==="Delivered").length,"#5C8A3D"],
  ],[orders]);

  return <div>
    <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:16,flexWrap:"wrap",gap:10}}>
      <div style={{fontFamily:FD,fontWeight:700,fontSize:22,color:T.ink}}>Orders</div>
      {userRole==="admin"&&<button onClick={onNew} style={{...BTN(),background:T.moss,color:T.paperWhite}}>+ New order</button>}
    </div>

    {/* View toggle */}
    <div style={{display:"flex",gap:1,marginBottom:18,background:T.line,borderRadius:3,overflow:"hidden",width:"fit-content"}}>
      {[["cards","Order cards"],["packing","By item"],["customer","By customer"]].map(([id,label])=>(
        <button key={id} onClick={()=>setView(id)} style={{padding:"8px 16px",border:"none",background:view===id?T.moss:T.paperWhite,color:view===id?T.paperWhite:T.inkMuted,cursor:"pointer",fontSize:12,fontWeight:600,fontFamily:FB}}>
          {label}
        </button>
      ))}
    </div>

    <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(140px,1fr))",gap:1,marginBottom:24,background:T.line,borderRadius:3,overflow:"hidden"}}>
      {stats.map(([label,val,color])=>(
        <div key={label} style={{background:T.paperWhite,padding:"14px 16px"}}>
          <div style={{fontSize:10,color:T.inkMuted,marginBottom:5,textTransform:"uppercase",letterSpacing:"0.05em",fontFamily:FM}}>{label}</div>
          <div style={{fontSize:26,fontWeight:600,color,fontFamily:FD}}>{val}</div>
        </div>
      ))}
    </div>

    {view==="packing"||view==="customer"
      ?<>
        <div style={{marginBottom:16,display:"flex",gap:10,alignItems:"flex-end",flexWrap:"wrap"}}>
          <div>
            <label style={IL}>Filter by delivery date (optional)</label>
            <input type="date" value={listDate} onChange={e=>setListDate(e.target.value)} style={{...II,width:"auto"}}/>
          </div>
          {listDate&&<button onClick={()=>setListDate("")} style={{...BTN(),border:`1px solid ${T.line}`,background:"transparent",color:T.inkMuted,padding:"9px 14px"}}>Clear</button>}
        </div>
        {view==="packing"
          ?<PackingListView orders={orders} onlyDate={listDate||null} onUpdateActualQty={onUpdateActualQty} inventory={inventory}/>
          :<CustomerPackingView orders={orders} onlyDate={listDate||null} inventory={inventory} onUpdateActualQty={onUpdateActualQty}/>
        }
      </>
      :<>
        <div style={{display:"flex",gap:10,marginBottom:18,flexWrap:"wrap"}}>
          <input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Search by order ID or customer…"
            style={{...II,flex:1,minWidth:160}}/>
          <input type="date" value={filterDate} onChange={e=>setFilterDate(e.target.value)}
            style={{...II,width:"auto"}} title="Filter by delivery date"/>
          {filterDate&&<button onClick={()=>setFilterDate("")} style={{...BTN(),border:`1px solid ${T.line}`,background:"transparent",color:T.inkMuted,padding:"9px 12px"}}>✕</button>}
          <select value={filterStatus} onChange={e=>setFilterStatus(e.target.value)} style={{...II,width:"auto"}}>
            <option value="All">All status</option>
            {STATUS_FLOW.map(s=><option key={s}>{s}</option>)}
          </select>
          <select value={sortBy} onChange={e=>setSortBy(e.target.value)} style={{...II,width:"auto"}}>
            <option value="delivery_date">Sort: delivery date ↑</option>
            <option value="delivery_date_desc">Sort: delivery date ↓</option>
            <option value="customer">Sort: customer A–Z</option>
            <option value="created_at_desc">Sort: newest first</option>
          </select>
        </div>
        {filtered.length===0
          ?<div style={{textAlign:"center",padding:50,color:T.inkMuted,fontFamily:FD,fontStyle:"italic",fontSize:15}}>No orders found.</div>
          :<>
            {/* Section toggle */}
            <div style={{display:"flex",gap:1,marginBottom:14,background:T.line,borderRadius:3,overflow:"hidden",width:"fit-content"}}>
              <button onClick={()=>setOrderSection("regular")} style={{padding:"8px 18px",border:"none",background:orderSection==="regular"?T.moss:T.paperWhite,color:orderSection==="regular"?T.paperWhite:T.inkMuted,cursor:"pointer",fontSize:12,fontWeight:600,fontFamily:FB}}>
                Orders ({filtered.filter(o=>!o.is_cash).length})
              </button>
              <button onClick={()=>setOrderSection("cash")} style={{padding:"8px 18px",border:"none",background:orderSection==="cash"?T.gold:T.paperWhite,color:orderSection==="cash"?T.paperWhite:T.inkMuted,cursor:"pointer",fontSize:12,fontWeight:600,fontFamily:FB}}>
                💵 Cash / Walk-in ({filtered.filter(o=>o.is_cash).length})
              </button>
            </div>
            <div style={{display:"grid",gap:10}}>
              {filtered.filter(o=>orderSection==="cash"?o.is_cash:!o.is_cash).map(o=><OrderCard key={o.id} order={o} inventory={inventory} onView={onView} onEdit={onEdit} onDelete={onDelete} onUpdateStatus={onUpdateStatus} onPrint={onPrint} userRole={userRole} onMarkPaid={onMarkPaid}/>)}
              {filtered.filter(o=>orderSection==="cash"?o.is_cash:!o.is_cash).length===0&&
                <div style={{textAlign:"center",padding:30,color:T.inkMuted,fontStyle:"italic",fontFamily:FD}}>
                  No {orderSection==="cash"?"cash/walk-in":"regular"} orders.
                </div>
              }
            </div>
          </>
        }
      </>
    }
  </div>;
}

// ─── ORDER INTAKE (Billing Station) ──────────────────────────────────────────
function OrderIntake({onOrderCreated,inventory,savedCustomers,onSaveCustomer}){
  const [mode,setMode]=useState("manual"); // manual | ai | queue
  const blankItem={name:DEFAULT_ITEMS[0],qty:"",unit:DEFAULT_UNITS[DEFAULT_ITEMS[0]]||"kg"};
  const blankOrder={customer:"",business:"",phone:"",order_date:today(),delivery_date:"",delivery_location:"",notes:"",status:"Pending",is_cash:false,items:[{...blankItem}]};

  // ── Single order state (manual + ai modes) ──
  const [order,setOrder]=useState({...blankOrder});
  const [message,setMessage]=useState("");
  const [loading,setLoading]=useState(false);
  const [error,setError]=useState("");
  const [imagePreview,setImagePreview]=useState(null);
  const [extracted,setExtracted]=useState(false);
  const [saveCustomer,setSaveCustomer]=useState(false);
  const [confirming,setConfirming]=useState(false);
  const fileRef=useRef();

  // ── Queue mode state ──
  const [queue,setQueue]=useState([""]); // array of message strings
  const [queueProcessing,setQueueProcessing]=useState(false);
  const [queueResults,setQueueResults]=useState([]); // array of {order, status, error}
  const [queueError,setQueueError]=useState("");
  const [creatingAll,setCreatingAll]=useState(false);

  function addQueueSlot(){ setQueue(q=>[...q,""]); }
  function removeQueueSlot(i){ setQueue(q=>q.filter((_,j)=>j!==i)); }
  function setQueueMsg(i,v){ setQueue(q=>q.map((m,j)=>j===i?v:m)); }

  async function processQueue(){
    const filled=queue.filter(m=>m.trim());
    if(!filled.length)return;
    setQueueProcessing(true);setQueueError("");setQueueResults([]);
    // Fire all in parallel
    const results=await Promise.allSettled(filled.map(msg=>parseText(msg)));
    const processed=results.map((r,i)=>{
      if(r.status==="fulfilled"){
        const rawItems=(r.value.items||[]).length?r.value.items:[{...blankItem}];
        return{
          order:{...blankOrder,customer:(r.value.customer||"").replace(/^#+/,""),business:r.value.business||"",
            phone:r.value.phone||"",delivery_date:r.value.deliveryDate||"",
            delivery_location:r.value.deliveryLocation||"",notes:r.value.notes||"",
            items:validateItemsAgainstCatalog(rawItems,inventory)},
          status:"ok",error:null,rawMsg:filled[i]
        };
      } else {
        return{order:{...blankOrder,items:[{...blankItem}]},status:"error",error:r.reason?.message||"Failed",rawMsg:filled[i]};
      }
    });
    setQueueResults(processed);
    setQueueProcessing(false);
  }

  function updateQueueOrder(i,updatedOrder){ setQueueResults(prev=>prev.map((r,j)=>j===i?{...r,order:updatedOrder}:r)); }
  function removeQueueResult(i){ setQueueResults(prev=>prev.filter((_,j)=>j!==i)); }

  async function createAllQueued(){
    const valid=queueResults.filter(r=>r.order.customer.trim()&&r.order.items.some(it=>it.qty));
    if(!valid.length)return;
    setCreatingAll(true);
    const failed=[];
    for(const r of valid){
      const payload={id:genId(),...r.order,items:r.order.items.filter(it=>it.qty).map(it=>({...it,qty:parseFloat(it.qty)||0}))};
      const{error:err,payload:saved}=await insertOrderWithRetry(payload);
      if(!err) onOrderCreated(saved);
      else failed.push({...r,order:saved,status:"save_failed",error:err.message});
    }
    if(failed.length){
      setQueueResults(failed);
      setQueueError(`${failed.length} order${failed.length>1?"s":""} failed to save — review below and try again.`);
    } else {
      setQueueResults([]);setQueue([""]);
    }
    setCreatingAll(false);
  }

  const EXAMPLES=[
    "Send 10 kg broccoli, 5 kg zucchini and 20 lettuce tomorrow morning.",
    "Need 15 bunches parsley, 8 kg cherry tomatoes, and 10 kg yellow bell peppers. Customer: Fresh Mart, delivery to Andheri West.",
    "Order from Chef Ramesh, Hotel Oberoi: 3kg asparagus, 5kg zucchini, 4kg bok choy, 2kg kale for Friday. No bruising please.",
  ];

  function buildOrder(parsed){
    const rawItems=(parsed.items||[]).length?parsed.items:[{...blankItem}];
    return {
      customer:(parsed.customer||"").replace(/^#+/,""),business:parsed.business||"",
      phone:parsed.phone||"",order_date:today(),
      delivery_date:parsed.deliveryDate||"",
      delivery_location:parsed.deliveryLocation||"",
      notes:parsed.notes||"",status:"Pending",
      items:validateItemsAgainstCatalog(rawItems,inventory),
    };
  }

  async function handleExtract(){
    if(!message.trim())return;
    setLoading(true);setError("");
    try{
      const r=await parseText(message);
      setOrder(buildOrder(r));
      setExtracted(true);
    }catch(e){
      setError(`AI extraction failed (${e.message||"unknown error"}) — opened a blank order below so you can fill it in manually.`);
      setOrder({...blankOrder,items:[{...blankItem}],raw_message:message});
      setExtracted(true);
    }
    setLoading(false);
  }

  function handleImageSelect(e){
    const file=e.target.files[0];
    if(!file)return;
    setLoading(true);setError("");
    // A raw phone camera photo can be 8-12MB — shrinking it here keeps the
    // upload fast on mobile data and stays under the API's body size limit,
    // while 1600px is still plenty to read handwriting/screenshot text.
    resizeImageToDataURL(file,1600,0.85).then(async(b64)=>{
      setImagePreview(b64);
      try{
        const r=await parseImage(b64);
        setOrder(buildOrder(r));
        setExtracted(true);
      }catch(err){
        setError(`AI extraction failed (${err.message||"unknown error"}) — opened a blank order below so you can fill it in manually.`);
        setOrder({...blankOrder,items:[{...blankItem}]});
        setExtracted(true);
      }
      setLoading(false);
    }).catch(()=>{
      setError("Couldn't read that image — please try a different photo.");
      setLoading(false);
    });
  }



  function customerRate(customer,itemName){
    const r=inventory[itemName]?.customerRates?.[customer];
    return r!=null?String(r):"";
  }

  function setField(k,v){setOrder(o=>({...o,[k]:v}));}
  function setItem(i,k,v){
    const items=[...order.items];
    items[i]={...items[i],[k]:v};
    if(k==="name"){
      items[i]._unmatched=false;
      items[i].unit=inventory[v]?.unit||DEFAULT_UNITS[v]||"kg";
      const cr=customerRate(order.customer,v);
      if(cr)items[i].override_rate=cr;
    }
    setField("items",items);
  }
  function addItem(){
    const newItem={...blankItem};
    const cr=customerRate(order.customer,newItem.name);
    if(cr)newItem.override_rate=cr;
    setField("items",[...order.items,newItem]);
  }
  function removeItem(i){setField("items",order.items.filter((_,j)=>j!==i));}

  function applyRatesToItems(items,customer){
    return items.map(it=>{
      const cr=customerRate(customer,it.name);
      return cr?{...it,override_rate:cr}:it;
    });
  }

  function pickSavedCustomer(name){
    const c=savedCustomers.find(c=>c.name===name);
    if(!c)return;
    setOrder(o=>({...o,customer:c.name,business:c.business||"",phone:c.phone||"",delivery_location:c.delivery_location||o.delivery_location,items:applyRatesToItems(o.items,c.name)}));
  }

  function handleCustomerTyped(val){
    const clean=val.replace(/^#+/,"");
    setOrder(o=>({...o,customer:clean,items:applyRatesToItems(o.items,clean)}));
  }

  function resetAll(){
    setOrder({...blankOrder,items:[{...blankItem}]});
    setMessage("");setImagePreview(null);setExtracted(false);setError("");setSaveCustomer(false);
  }

  async function confirmOrder(){
    if(confirming)return;
    if(!order.customer.trim()){setError("Customer name is required.");return;}
    const stillUnmatched=order.items.some(it=>it._unmatched&&it.qty);
    if(stillUnmatched){setError("Please fix the orange-flagged item(s) below before saving — pick the correct item from the dropdown.");return;}
    const payload={id:genId(),...order,items:order.items.filter(it=>it.qty).map(it=>{const{_unmatched,...clean}=it;return{...clean,qty:parseFloat(it.qty)||0};}),raw_message:message||null};
    if(!payload.items.length){setError("Add at least one item with a quantity.");return;}
    setConfirming(true);
    const{error:err,payload:saved}=await insertOrderWithRetry(payload);
    if(err){setError("Save failed: "+err.message);setConfirming(false);return;}
    if(saveCustomer){
      onSaveCustomer({name:order.customer,business:order.business,phone:order.phone,delivery_location:order.delivery_location});
    }
    onOrderCreated(saved);
    resetAll();
    setConfirming(false);
  }

  const allItems=Object.keys(inventory).length?Object.keys(inventory):DEFAULT_ITEMS;

  return <div style={{fontFamily:FB}}>
    {/* Mode toggle */}
    <div style={{display:"flex",gap:1,marginBottom:18,background:T.line,borderRadius:3,overflow:"hidden",width:"fit-content"}}>
      {[["manual","Manual"],["ai","From message/photo"],["queue","Queue (bulk)"]].map(([id,label])=>(
        <button key={id} onClick={()=>setMode(id)} style={{padding:"9px 18px",border:"none",background:mode===id?T.moss:T.paperWhite,color:mode===id?T.paperWhite:T.inkMuted,cursor:"pointer",fontSize:13,fontWeight:600,fontFamily:FB}}>
          {label}
        </button>
      ))}
    </div>

    {/* ── QUEUE MODE ── */}
    {mode==="queue"&&<div>
      <div style={{fontFamily:FD,fontWeight:700,fontSize:17,color:T.ink,marginBottom:4}}>Bulk order queue</div>
      <div style={{fontSize:12,color:T.inkMuted,marginBottom:16}}>Paste one order message per box, add as many as you need, then hit Process all. Review each extracted order and create them all at once.</div>

      {/* Message boxes */}
      <div style={{display:"grid",gap:10,marginBottom:14}}>
        {queue.map((msg,i)=>(
          <div key={i} style={{display:"flex",gap:8,alignItems:"flex-start"}}>
            <div style={{background:T.moss,color:T.paperWhite,borderRadius:2,padding:"4px 8px",fontSize:11,fontFamily:FM,fontWeight:700,marginTop:10,minWidth:24,textAlign:"center"}}>{i+1}</div>
            <div style={{flex:1,display:"flex",flexDirection:"column",gap:6}}>
              {savedCustomers?.length>0&&<select defaultValue="" onChange={e=>{if(e.target.value){const c=savedCustomers.find(c=>c.name===e.target.value);if(c)setQueueMsg(i,`Customer: ${c.name}\n${msg}`);}}} style={{...II,fontSize:12,padding:"5px 8px"}}>
                <option value="">— quick-select customer —</option>
                {savedCustomers.map(c=><option key={c.name} value={c.name}>{c.name}</option>)}
              </select>}
              <textarea
                value={msg}
                onChange={e=>setQueueMsg(i,e.target.value)}
                placeholder={`Paste order message ${i+1}…`}
                rows={3}
                style={{...II,resize:"vertical",lineHeight:1.6,fontSize:13}}
              />
            </div>
            {queue.length>1&&<button onClick={()=>removeQueueSlot(i)} style={{background:"none",border:"none",cursor:"pointer",color:T.clay,fontSize:18,marginTop:8,padding:8}}>✕</button>}
          </div>
        ))}
      </div>

      <div style={{display:"flex",gap:10,marginBottom:20}}>
        <button onClick={addQueueSlot} style={{...BTN(),border:`1px solid ${T.line}`,background:"transparent",color:T.ink,flex:1}}>+ Add another order</button>
        <button
          onClick={processQueue}
          disabled={queueProcessing||!queue.some(m=>m.trim())}
          style={{...BTN(),background:T.moss,color:T.paperWhite,flex:2,fontWeight:700}}
        >
          {queueProcessing?`Processing ${queue.filter(m=>m.trim()).length} orders…`:`Process all (${queue.filter(m=>m.trim()).length})`}
        </button>
      </div>

      {/* Review cards */}
      {queueError&&<div style={{background:"#FCF2EC",color:T.clay,padding:"10px 14px",borderRadius:3,fontSize:13,marginBottom:14,borderLeft:`3px solid ${T.clay}`}}>{queueError}</div>}
      {queueResults.length>0&&<>
        <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:14}}>
          <div style={{fontFamily:FD,fontWeight:700,fontSize:16,color:T.ink}}>{queueResults.length} orders extracted — review below</div>
          <button
            onClick={createAllQueued}
            disabled={creatingAll}
            style={{...BTN(),background:T.moss,color:T.paperWhite,fontWeight:700,padding:"10px 24px"}}
          >
            {creatingAll?"Creating…":`Create all ${queueResults.length} orders`}
          </button>
        </div>

        <div style={{display:"grid",gap:14}}>
          {queueResults.map((r,i)=>{
            const o=r.order;
            const hasUnmatched=(o.items||[]).some(it=>it._unmatched);
            const isErrorCard=r.status==="error"||r.status==="save_failed";
            return <div key={i} style={{background:T.paperWhite,border:`2px solid ${isErrorCard?T.clay:hasUnmatched?T.gold:T.moss}`,borderRadius:4,overflow:"hidden"}}>
              {/* Card header */}
              <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",padding:"10px 14px",background:isErrorCard?"#FCF2EC":hasUnmatched?"#FBF6E9":"#EBF2EC",borderBottom:`1px solid ${T.line}`}}>
                <div style={{display:"flex",alignItems:"center",gap:10}}>
                  <span style={{fontFamily:FM,fontWeight:700,fontSize:12,color:isErrorCard?T.clay:hasUnmatched?T.gold:T.moss}}>
                    {r.status==="error"?"⚠ Failed":r.status==="save_failed"?"⚠ Save failed":hasUnmatched?"⚠ Check items":"✓ Ready"}
                  </span>
                  <span style={{fontFamily:FD,fontWeight:700,fontSize:15,color:T.ink}}>{o.customer||"(no customer detected)"}</span>
                </div>
                <button onClick={()=>removeQueueResult(i)} style={{background:"none",border:"none",cursor:"pointer",color:T.inkMuted,fontSize:14}}>Remove</button>
              </div>

              {r.status==="error"&&<div style={{padding:"10px 14px",background:"#FCF2EC",fontSize:12,color:T.clay,borderBottom:`1px solid ${T.line}`}}>
                AI failed: {r.error}. Edit the raw message and reprocess, or fill in below manually.
              </div>}
              {r.status==="save_failed"&&<div style={{padding:"10px 14px",background:"#FCF2EC",fontSize:12,color:T.clay,borderBottom:`1px solid ${T.line}`}}>
                Couldn't save this order: {r.error}. Click "Create all" again to retry.
              </div>}

              {/* Editable fields */}
              <div style={{padding:14}}>
                <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(180px,1fr))",gap:10,marginBottom:12}}>
                  {[["Customer","customer"],["Delivery date","delivery_date"],["Location","delivery_location"]].map(([label,key])=>(
                    <div key={key}>
                      <label style={IL}>{label}</label>
                      <input type={key==="delivery_date"?"date":"text"} value={o[key]||""}
                        onChange={e=>updateQueueOrder(i,{...o,[key]:e.target.value})}
                        style={II}/>
                    </div>
                  ))}
                </div>

                {hasUnmatched&&<div style={{background:"#FBF6E9",color:"#5C4A1F",padding:"7px 11px",borderRadius:2,fontSize:12,marginBottom:10,borderLeft:`3px solid ${T.gold}`}}>
                  ⚠ Some items below couldn't be matched — fix the orange rows
                </div>}

                <div style={{border:`1px solid ${T.line}`,borderRadius:3,marginBottom:10}}>
                  {(o.items||[]).map((it,j)=>{
                    const isUnmatched=it._unmatched||!allItems.includes(it.name);
                    return <div key={j} style={{display:"flex",gap:8,padding:"7px 10px",borderBottom:j<o.items.length-1?`1px solid ${T.line}`:"none",alignItems:"center",background:isUnmatched?"#FCF2EC":"transparent",flexWrap:"wrap"}}>
                      {isUnmatched&&<span style={{color:T.clay,fontSize:12}}>⚠</span>}
                      <select value={it.name} onChange={e=>{const items=[...o.items];items[j]={...items[j],name:e.target.value,_unmatched:false};updateQueueOrder(i,{...o,items});}}
                        style={{...II,flex:"2 0 130px",padding:"5px 7px",fontSize:12}}>
                        {allItems.map(n=><option key={n}>{n}</option>)}
                      </select>
                      <input type="number" value={it.qty} onChange={e=>{const items=[...o.items];items[j]={...items[j],qty:e.target.value};updateQueueOrder(i,{...o,items});}}
                        placeholder="qty" style={{...II,flex:"1 0 60px",padding:"5px 7px",fontSize:12,fontFamily:FM}}/>
                      <select value={it.unit} onChange={e=>{const items=[...o.items];items[j]={...items[j],unit:e.target.value};updateQueueOrder(i,{...o,items});}}
                        style={{...II,flex:"1 0 70px",padding:"5px 7px",fontSize:12}}>
                        {["kg","grams","pcs","pkt","bunches","boxes","crates"].map(u=><option key={u}>{u}</option>)}
                      </select>
                      <button onClick={()=>{const items=o.items.filter((_,k)=>k!==j);updateQueueOrder(i,{...o,items});}}
                        style={{background:"none",border:"none",cursor:"pointer",color:T.clay,fontSize:15,padding:8}}>✕</button>
                    </div>;
                  })}
                  <button onClick={()=>updateQueueOrder(i,{...o,items:[...(o.items||[]),{...blankItem}]})}
                    style={{width:"100%",padding:"8px",background:"none",border:"none",borderTop:`1px solid ${T.line}`,cursor:"pointer",fontSize:12,color:T.moss,fontWeight:600}}>
                    + Add item
                  </button>
                </div>

                {/* Raw message reference */}
                <div style={{fontSize:11,color:T.inkMuted,fontFamily:FM,fontStyle:"italic",padding:"6px 0",borderTop:`1px solid ${T.line}`}}>
                  Original: {r.rawMsg?.slice(0,120)}{r.rawMsg?.length>120?"…":""}
                </div>
              </div>
            </div>;
          })}
        </div>

        <div style={{marginTop:16,paddingTop:16,borderTop:`1px solid ${T.line}`,display:"flex",justifyContent:"flex-end"}}>
          <button onClick={createAllQueued} disabled={creatingAll}
            style={{...BTN(),background:T.moss,color:T.paperWhite,fontWeight:700,padding:"12px 32px",fontSize:15}}>
            {creatingAll?"Creating…":`Create all ${queueResults.length} orders`}
          </button>
        </div>
      </>}
    </div>}

    {mode==="ai"&&<div style={{background:T.paperWhite,border:`1px solid ${T.line}`,borderRadius:4,padding:18,marginBottom:20}}>
      <div style={{fontFamily:FD,fontWeight:600,fontSize:15,color:T.ink,marginBottom:3}}>Extract order automatically</div>
      <div style={{fontSize:12,color:T.inkMuted,fontFamily:FM,marginBottom:14}}>Paste an order message or upload a photo — details will fill the form below</div>

      <textarea value={message} onChange={e=>setMessage(e.target.value)} placeholder="e.g. Send 10 kg broccoli, 5 kg zucchini tomorrow morning" rows={4}
        style={{...II,resize:"vertical",lineHeight:1.6,marginBottom:12}}/>

      {imagePreview&&<div style={{marginBottom:12,border:`1px solid ${T.line}`,borderRadius:3,padding:8,position:"relative",maxWidth:280}}>
        <img src={imagePreview} alt="order" style={{width:"100%",borderRadius:2,maxHeight:160,objectFit:"contain"}}/>
        <button onClick={()=>setImagePreview(null)} style={{position:"absolute",top:14,right:14,background:T.ink,color:T.paperWhite,border:"none",borderRadius:"50%",width:22,height:22,cursor:"pointer",fontSize:12}}>✕</button>
      </div>}

      <div style={{display:"flex",gap:10,flexWrap:"wrap",marginBottom:12}}>
        <button onClick={()=>fileRef.current?.click()} style={{...BTN(),flex:"1 0 140px",padding:"10px 0",background:"transparent",border:`1px solid ${T.line}`,color:T.ink}}>
          Upload photo
        </button>
        <input ref={fileRef} type="file" accept="image/*" onChange={handleImageSelect} style={{display:"none"}}/>
        <button onClick={handleExtract} disabled={loading||!message.trim()} style={{...BTN(),flex:"1 0 140px",padding:"10px 0",background:T.moss,color:T.paperWhite}}>
          {loading?"Reading…":"Extract order"}
        </button>
      </div>

      {error&&<div style={{background:"#F3E3DC",color:T.clay,padding:"10px 14px",borderRadius:2,marginBottom:12,fontSize:13,borderLeft:`3px solid ${T.clay}`}}>{error}</div>}

      <div style={{paddingTop:12,borderTop:`1px solid ${T.line}`}}>
        <div style={{fontSize:11,color:T.inkMuted,marginBottom:8,fontFamily:FM,textTransform:"uppercase",letterSpacing:"0.04em"}}>Sample messages</div>
        {EXAMPLES.map((ex,i)=>(
          <button key={i} onClick={()=>setMessage(ex)} style={{display:"block",width:"100%",textAlign:"left",background:T.paper,border:`1px solid ${T.line}`,borderRadius:2,padding:"8px 11px",fontSize:12,color:T.inkMuted,cursor:"pointer",fontFamily:FB,lineHeight:1.4,marginBottom:6}}>
            {ex}
          </button>
        ))}
      </div>
    </div>}

    {/* Order form — hidden in queue mode */}
    {mode!=="queue"&&<div style={{background:T.paperWhite,border:`1px solid ${T.line}`,borderRadius:4}}>
      <div style={{padding:"16px 20px",borderBottom:`1px solid ${T.line}`}}>
        <div style={{fontFamily:FD,fontWeight:600,fontSize:16,color:T.ink}}>{extracted?"Review & confirm":"New order"}</div>
        <div style={{fontSize:11,color:T.inkMuted,fontFamily:FM,marginTop:2}}>Fill in details and add items, like ringing up a sale</div>
      </div>

      <div style={{padding:20}}>
        {error&&mode==="manual"&&<div style={{background:"#F3E3DC",color:T.clay,padding:"10px 14px",borderRadius:2,marginBottom:14,fontSize:13,borderLeft:`3px solid ${T.clay}`}}>{error}</div>}

        {savedCustomers?.length>0&&<div style={{marginBottom:14}}>
          <label style={IL}>Quick-select regular customer</label>
          <SearchSelect
            options={savedCustomers.map(c=>({value:c.name,label:c.name}))}
            value=""
            onChange={v=>pickSavedCustomer(v)}
            placeholder="— search saved customers —"
          />
        </div>}

        <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(220px,1fr))",gap:10,marginBottom:10}}>
          {[["Customer *","customer"],["Phone","phone"],["Delivery Date","delivery_date"],["Location","delivery_location"],["Notes","notes"]].map(([label,key])=>(
            <div key={key}>
              <label style={IL}>{label}</label>
              <input value={order[key]||""} onChange={e=>key==="customer"?handleCustomerTyped(e.target.value):setField(key,e.target.value)} type={key==="delivery_date"?"date":"text"} style={II}/>
            </div>
          ))}
        </div>

        <div style={{display:"flex",gap:16,marginBottom:18,flexWrap:"wrap"}}>
          <label style={{display:"flex",alignItems:"center",gap:7,fontSize:12,color:T.inkMuted,cursor:"pointer"}}>
            <input type="checkbox" checked={saveCustomer} onChange={e=>setSaveCustomer(e.target.checked)}/>
            Save "{order.customer||"this customer"}" as a regular customer
          </label>
          <label style={{display:"flex",alignItems:"center",gap:7,fontSize:12,cursor:"pointer",color:order.is_cash?T.moss:T.inkMuted,fontWeight:order.is_cash?700:400}}>
            <input type="checkbox" checked={!!order.is_cash} onChange={e=>setField("is_cash",e.target.checked)}/>
            💵 Cash payment (local/walk-in — auto-clears balance)
          </label>
        </div>

        <div style={{fontFamily:FD,fontWeight:600,fontSize:14,marginBottom:8,color:T.ink}}>Items</div>
        {order.items.some(it=>it._unmatched)&&<div style={{background:"#F3E3DC",color:T.clay,padding:"9px 13px",borderRadius:2,marginBottom:10,fontSize:12,borderLeft:`3px solid ${T.clay}`}}>
          ⚠️ Some items below couldn't be matched to your catalog — check the orange-highlighted rows and pick the correct item from the dropdown.
        </div>}
        <div style={{border:`1px solid ${T.line}`,borderRadius:3,marginBottom:16}}>
          {order.items.map((it,i)=>{
            const isUnmatched=it._unmatched||!allItems.includes(it.name);
            return <div key={i} style={{display:"flex",gap:8,alignItems:"center",padding:"9px 12px",borderBottom:i<order.items.length-1?`1px solid ${T.line}`:"none",flexWrap:"wrap",background:isUnmatched?"#FCF2EC":"transparent"}}>
              {isUnmatched&&<span title="Could not match to catalog" style={{color:T.clay,fontSize:14}}>⚠️</span>}
              <SearchSelect
                options={allItems}
                value={isUnmatched?"":it.name}
                onChange={v=>setItem(i,"name",v)}
                placeholder={isUnmatched?`${it.name||"?"} — pick correct item`:"Select item…"}
                style={{flex:"2 0 140px",borderColor:isUnmatched?T.clay:T.line}}
              />
              <input type="number" value={it.qty} onChange={e=>setItem(i,"qty",e.target.value)} placeholder="qty" style={{...II,flex:"1 0 70px",padding:"7px 8px",fontFamily:FM}}/>
              <select value={it.unit} onChange={e=>setItem(i,"unit",e.target.value)} style={{...II,flex:"1 0 90px",padding:"7px 8px"}}>
                {["kg","grams","pcs","pkt","bunches","boxes","crates"].map(u=><option key={u}>{u}</option>)}
              </select>
              <button onClick={()=>removeItem(i)} style={{background:"none",border:"none",cursor:"pointer",color:T.clay,fontSize:18,padding:8}}>✕</button>
            </div>;
          })}
          <button onClick={addItem} style={{width:"100%",padding:"11px",background:"none",border:"none",borderTop:`1px solid ${T.line}`,cursor:"pointer",fontSize:13,color:T.moss,fontFamily:FB,fontWeight:500}}>
            + Add item
          </button>
        </div>

        <div style={{display:"flex",gap:10}}>
          <button onClick={resetAll} style={{...BTN(),border:`1px solid ${T.line}`,background:"transparent",color:T.inkMuted}}>Clear</button>
          <button onClick={confirmOrder} disabled={confirming} style={{...BTN(),flex:1,background:T.moss,color:T.paperWhite,padding:"12px 0",opacity:confirming?0.6:1}}>{confirming?"Creating…":"Create order ticket"}</button>
        </div>
      </div>
    </div>}
  </div>;
}

// ─── INVENTORY ────────────────────────────────────────────────────────────────
function InventoryPanel({inventory,onUpdate,customers,user}){
  const [items,setItems]=useState(inventory);
  const [editName,setEditName]=useState(null);
  const [editForm,setEditForm]=useState({});
  const [rateEditName,setRateEditName]=useState(null);
  const [newCustomerRate,setNewCustomerRate]=useState({customer:"",rate:""});
  const [newItem,setNewItem]=useState({name:"",qty:"",unit:"kg",rate:""});
  const [saving,setSaving]=useState(false);
  const [showAdd,setShowAdd]=useState(false);

  useEffect(()=>setItems(inventory),[inventory]);

  async function saveEdit(name){
    setSaving(true);
    const before=items[name];
    const updated={...items,[name]:{...items[name],...editForm,qty:parseFloat(editForm.qty)||0,rate:parseFloat(editForm.rate)||0}};
    const{error}=await supabase.from("inventory").upsert([{name,qty:updated[name].qty,unit:updated[name].unit,rate:updated[name].rate,customer_rates:updated[name].customerRates||{}}]);
    if(!error){
      onUpdate(updated);setItems(updated);
      logActivity(user,"Inventory updated",`${name}: qty ${fmtQty(before?.qty)}→${fmtQty(updated[name].qty)}, rate ${fmtMoney(before?.rate)}→${fmtMoney(updated[name].rate)}`);
    }
    setEditName(null);setSaving(false);
  }

  async function saveNew(){
    if(!newItem.name.trim())return;
    setSaving(true);
    const entry={name:newItem.name,qty:parseFloat(newItem.qty)||0,unit:newItem.unit,rate:parseFloat(newItem.rate)||0,customerRates:{}};
    const{error}=await supabase.from("inventory").upsert([{name:entry.name,qty:entry.qty,unit:entry.unit,rate:entry.rate,customer_rates:{}}]);
    if(!error){
      const updated={...items,[newItem.name]:entry};
      onUpdate(updated);setItems(updated);
      setNewItem({name:"",qty:"",unit:"kg",rate:""});setShowAdd(false);
    }
    setSaving(false);
  }

  async function deleteItem(name){
    if(!window.confirm(`Delete "${name}" from inventory? This cannot be undone.`))return;
    setSaving(true);
    await supabase.from("inventory").delete().eq("name",name);
    const updated={...items};
    delete updated[name];
    onUpdate(updated);setItems(updated);
    setSaving(false);
    logActivity(user,"Inventory item deleted",name);
  }

  async function addCustomerRate(name){
    if(!newCustomerRate.customer||!newCustomerRate.rate)return;
    setSaving(true);
    const current=items[name].customerRates||{};
    const updatedRates={...current,[newCustomerRate.customer]:parseFloat(newCustomerRate.rate)};
    const updated={...items,[name]:{...items[name],customerRates:updatedRates}};
    await supabase.from("inventory").upsert([{name,qty:updated[name].qty,unit:updated[name].unit,rate:updated[name].rate,customer_rates:updatedRates}]);
    onUpdate(updated);setItems(updated);
    setNewCustomerRate({customer:"",rate:""});
    setSaving(false);
  }

  async function removeCustomerRate(name,customer){
    setSaving(true);
    const current={...(items[name].customerRates||{})};
    delete current[customer];
    const updated={...items,[name]:{...items[name],customerRates:current}};
    await supabase.from("inventory").upsert([{name,qty:updated[name].qty,unit:updated[name].unit,rate:updated[name].rate,customer_rates:current}]);
    onUpdate(updated);setItems(updated);
    setSaving(false);
  }

  const LOW=20;

  return <div>
    <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:20,flexWrap:"wrap",gap:10}}>
      <div>
        <div style={{fontFamily:FD,fontWeight:600,fontSize:20,color:T.ink}}>Inventory</div>
        <div style={{fontSize:13,color:T.inkMuted,marginTop:3}}>Click Edit for stock/rate, or Rates for per-customer pricing</div>
      </div>
      <button onClick={()=>setShowAdd(true)} style={{...BTN(),background:T.moss,color:T.paperWhite}}>+ Add item</button>
    </div>

    {showAdd&&<div style={{background:T.paperWhite,border:`1px solid ${T.line}`,borderRadius:3,padding:16,marginBottom:16}}>
      <div style={{fontFamily:FD,fontWeight:600,fontSize:15,marginBottom:12,color:T.ink}}>New inventory item</div>
      <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(120px,1fr))",gap:10,marginBottom:12}}>
        {[["Item name","name","text"],["Quantity","qty","number"],["Unit","unit","text"],["Rate (₹)","rate","number"]].map(([l,k,t])=>(
          <div key={k}>
            <label style={IL}>{l}</label>
            {k==="unit"
              ?<select value={newItem.unit} onChange={e=>setNewItem(n=>({...n,unit:e.target.value}))} style={II}>
                {["kg","grams","pcs","pkt","bunches","boxes","crates"].map(u=><option key={u}>{u}</option>)}
              </select>
              :<input type={t} value={newItem[k]} onChange={e=>setNewItem(n=>({...n,[k]:e.target.value}))} style={II}/>
            }
          </div>
        ))}
      </div>
      <div style={{display:"flex",gap:10}}>
        <button onClick={()=>setShowAdd(false)} style={{...BTN(),border:`1px solid ${T.line}`,background:"transparent",color:T.ink}}>Cancel</button>
        <button onClick={saveNew} disabled={saving} style={{...BTN(),background:T.moss,color:T.paperWhite}}>Add item</button>
      </div>
    </div>}

    <div style={{display:"grid",gap:8}}>
      {Object.entries(items).map(([name,{qty,unit,rate,customerRates}])=>{
        const isLow=qty<LOW;
        const isEdit=editName===name;
        const isRateEdit=rateEditName===name;
        const custRates=customerRates||{};
        return <div key={name} style={{background:isLow?"#F8EFE9":T.paperWhite,border:`1px solid ${isLow?T.clay:T.line}`,borderRadius:3,padding:"13px 16px"}}>
          {isEdit
            ?<div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(110px,1fr))",gap:10,alignItems:"flex-end"}}>
              <div><label style={IL}>Name</label><input defaultValue={name} disabled style={{...II,opacity:.6}}/></div>
              <div><label style={IL}>Quantity</label><input type="number" defaultValue={qty} onChange={e=>setEditForm(f=>({...f,qty:e.target.value}))} style={II}/></div>
              <div><label style={IL}>Unit</label>
                <select defaultValue={unit} onChange={e=>setEditForm(f=>({...f,unit:e.target.value}))} style={II}>
                  {["kg","grams","pcs","pkt","bunches","boxes","crates"].map(u=><option key={u}>{u}</option>)}
                </select>
              </div>
              <div><label style={IL}>Rate (₹)</label><input type="number" defaultValue={rate||DEFAULT_RATES[name]||0} onChange={e=>setEditForm(f=>({...f,rate:e.target.value}))} style={II}/></div>
              <div style={{display:"flex",gap:6,paddingBottom:1}}>
                <button onClick={()=>saveEdit(name)} disabled={saving} style={{...BTN(),background:T.moss,color:T.paperWhite,padding:"9px 14px"}}>Save</button>
                <button onClick={()=>setEditName(null)} style={{...BTN(),border:`1px solid ${T.line}`,background:"transparent",color:T.ink,padding:"9px 14px"}}>✕</button>
              </div>
            </div>
            :isRateEdit
            ?<div>
              <div style={{display:"flex",justifyContent:"space-between",marginBottom:12}}>
                <div style={{fontWeight:600,fontSize:14,color:T.ink}}>{name} — customer-specific rates</div>
                <button onClick={()=>setRateEditName(null)} style={{background:"none",border:"none",cursor:"pointer",color:T.inkMuted,fontSize:16,padding:8}}>✕</button>
              </div>
              <div style={{fontSize:12,color:T.inkMuted,marginBottom:10}}>Default rate: {fmtMoney(rate||DEFAULT_RATES[name]||0)}/{unit}. Override below for specific customers.</div>
              {Object.entries(custRates).length>0&&<div style={{marginBottom:12}}>
                {Object.entries(custRates).map(([cust,r])=>(
                  <div key={cust} style={{display:"flex",justifyContent:"space-between",alignItems:"center",padding:"7px 10px",background:T.paper,borderRadius:2,marginBottom:5}}>
                    <span style={{fontSize:13,color:T.ink}}>{cust}</span>
                    <div style={{display:"flex",gap:10,alignItems:"center"}}>
                      <span style={{fontFamily:FM,fontSize:13,color:T.moss}}>{fmtMoney(r)}/{unit}</span>
                      <button onClick={()=>removeCustomerRate(name,cust)} style={{background:"none",border:"none",cursor:"pointer",color:T.clay,fontSize:14,padding:8}}>✕</button>
                    </div>
                  </div>
                ))}
              </div>}
              <div style={{display:"flex",gap:8,flexWrap:"wrap"}}>
                <select value={newCustomerRate.customer} onChange={e=>setNewCustomerRate(f=>({...f,customer:e.target.value}))} style={{...II,flex:"2 0 160px"}}>
                  <option value="">— select customer —</option>
                  {(customers||[]).filter(c=>!custRates[c]).map(c=><option key={c}>{c}</option>)}
                </select>
                <input type="number" placeholder={`rate per ${unit}`} value={newCustomerRate.rate} onChange={e=>setNewCustomerRate(f=>({...f,rate:e.target.value}))} style={{...II,flex:"1 0 100px",fontFamily:FM}}/>
                <button onClick={()=>addCustomerRate(name)} disabled={saving||!newCustomerRate.customer||!newCustomerRate.rate} style={{...BTN(),background:T.moss,color:T.paperWhite,padding:"9px 14px"}}>Add</button>
              </div>
            </div>
            :<div style={{display:"flex",justifyContent:"space-between",alignItems:"center",flexWrap:"wrap",gap:10}}>
              <div style={{flex:"1 0 160px"}}>
                <div style={{display:"flex",alignItems:"center",gap:10,marginBottom:6,flexWrap:"wrap"}}>
                  <span style={{fontWeight:700,fontSize:15,color:T.ink}}>{name}</span>
                  {isLow&&<span style={{fontSize:10,color:T.clay,fontFamily:FM,textTransform:"uppercase",letterSpacing:"0.04em"}}>Low stock</span>}
                  {Object.keys(custRates).length>0&&<span style={{fontSize:10,color:T.gold,fontFamily:FM,textTransform:"uppercase",letterSpacing:"0.04em"}}>{Object.keys(custRates).length} custom rate{Object.keys(custRates).length>1?"s":""}</span>}
                </div>
                <div style={{background:T.line,borderRadius:2,height:5,overflow:"hidden",width:"100%",maxWidth:300}}>
                  <div style={{width:`${Math.min(100,Math.round(qty/200*100))}%`,height:"100%",background:isLow?T.clay:qty>60?T.moss:T.gold,borderRadius:2}}/>
                </div>
              </div>
              <div style={{display:"flex",gap:14,fontSize:12,color:T.inkMuted,fontFamily:FM,textAlign:"right"}}>
                <span>{fmtQty(qty)} {unit}</span>
                <span>{fmtMoney(rate||DEFAULT_RATES[name]||0)}/{unit}</span>
              </div>
              <div style={{display:"flex",gap:6}}>
                <button onClick={()=>{setEditName(name);setEditForm({qty,unit,rate:rate||DEFAULT_RATES[name]||0});}} style={{...BTN(),padding:"7px 12px",background:"transparent",border:`1px solid ${T.line}`,color:T.ink,fontSize:12}}>Edit</button>
                <button onClick={()=>setRateEditName(name)} style={{...BTN(),padding:"7px 12px",background:"transparent",border:`1px solid ${T.line}`,color:T.ink,fontSize:12}}>Rates</button>
                <button onClick={()=>deleteItem(name)} style={{...BTN(),padding:"7px 12px",background:"transparent",border:`1px solid ${T.clay}`,color:T.clay,fontSize:12}}>Delete</button>
              </div>
            </div>
          }
        </div>;
      })}
    </div>
  </div>;
}

// ─── ANALYTICS ────────────────────────────────────────────────────────────────
function Analytics({orders,inventory}){
  const [selectedCustomer,setSelectedCustomer]=useState("");
  const [selectedMonth,setSelectedMonth]=useState(today().slice(0,7));
  const [selectedDay,setSelectedDay]=useState(today());
  const [purchases,setPurchases]=useState([]);
  const [rangeMode,setRangeMode]=useState("month"); // month | range
  const [rangeFrom,setRangeFrom]=useState(today().slice(0,8)+"01");
  const [rangeTo,setRangeTo]=useState(today());

  // Drives every "monthly" computation below — either the whole selected
  // month, or an arbitrary from/to range (ISO date strings compare correctly
  // as plain strings, so no date-object math needed).
  function inSelectedPeriod(dateStr){
    if(!dateStr)return false;
    return rangeMode==="range"?(dateStr>=rangeFrom&&dateStr<=rangeTo):dateStr.startsWith(selectedMonth);
  }
  const periodLabel=rangeMode==="range"?`${rangeFrom} to ${rangeTo}`:selectedMonth;

  function fetchPurchases(){
    return supabase.from("purchases").select("*").then(({data,error})=>setPurchases((error||!data)?[]:data));
  }

  useEffect(()=>{
    fetchPurchases();
  },[]);

  // Realtime — so a purchase entered elsewhere is reflected in this month's cost without a refresh
  useEffect(()=>{
    let timer;
    const ch=supabase.channel("analytics-purchases-rt")
      .on("postgres_changes",{event:"*",schema:"public",table:"purchases"},()=>{clearTimeout(timer);timer=setTimeout(fetchPurchases,400);})
      .subscribe();
    return()=>{clearTimeout(timer);supabase.removeChannel(ch);};
  },[]);

  // All of the below scans the full order/purchase history on every render —
  // memoized so switching tabs, opening a modal, etc. elsewhere in the app
  // doesn't force a slow recompute here too (a real source of lag once order
  // history grows into the hundreds/thousands, especially on slower phones).
  const customers=useMemo(()=>[...new Set(orders.map(o=>o.customer).filter(Boolean))].sort(),[orders]);

  const monthOrders=useMemo(()=>orders.filter(o=>inSelectedPeriod(o.delivery_date||o.order_date||"")),[orders,rangeMode,selectedMonth,rangeFrom,rangeTo]);

  // Purchase cost this period
  const monthPurchases=useMemo(()=>purchases.filter(p=>inSelectedPeriod(p.date||"")),[purchases,rangeMode,selectedMonth,rangeFrom,rangeTo]);
  const monthPurchaseCost=useMemo(()=>monthPurchases.reduce((s,p)=>s+(p.qty||0)*(p.rate||0),0),[monthPurchases]);

  const customerOrders=useMemo(()=>selectedCustomer
    ?orders.filter(o=>o.customer===selectedCustomer&&inSelectedPeriod(o.order_date||""))
    :[],[orders,selectedCustomer,rangeMode,selectedMonth,rangeFrom,rangeTo]);

  const monthTotal=useMemo(()=>monthOrders.reduce((s,o)=>s+orderTotal(o,inventory),0),[monthOrders,inventory]);

  // Top customers this month
  const topCustomers=useMemo(()=>{
    const customerTotals={};
    monthOrders.forEach(o=>{
      if(!o.customer)return;
      customerTotals[o.customer]=(customerTotals[o.customer]||0)+orderTotal(o,inventory);
    });
    return Object.entries(customerTotals).sort((a,b)=>b[1]-a[1]).slice(0,5);
  },[monthOrders,inventory]);

  // Item breakdown (normalized to each item's base unit so kg/grams don't mix)
  const topItems=useMemo(()=>{
  const itemTotals={};
  monthOrders.forEach(o=>(o.items||[]).forEach(it=>{
    const baseUnit=inventory[it.name]?.unit||"kg";
    const qty=it.actual_qty??it.qty;
    itemTotals[it.name]=(itemTotals[it.name]||0)+toBaseQty(qty,it.unit,baseUnit);
  }));
  return Object.entries(itemTotals).sort((a,b)=>b[1]-a[1]).slice(0,8);
  },[monthOrders,inventory]);

  function printStatement(){
    const co=customerOrders;
    const total=co.reduce((s,o)=>s+orderTotal(o,inventory),0);
    const w=window.open("","_blank");
    w.document.write(`<html><head><meta charset="UTF-8"><title>Statement ${periodLabel} — ${selectedCustomer}</title>
    <style>${PRINT_STYLES}</style></head><body>
      <div class="sheet">
        <div class="letterhead">
          <div>
            <img class="logo" src="${COMPANY.logo}"/>
            <div class="company-name">Exotic Greens</div>
            <div class="company-sub">Fresh Exotic Vegetables</div>
            <div class="company-sub">${COMPANY.phone1} · ${COMPANY.phone2}</div>
          </div>
          <div class="doc-meta">
            <div class="doc-title">Statement</div>
            <div class="label">Period</div>
            <div class="val">${periodLabel}</div>
          </div>
        </div>

        <div class="billto">
          <div class="label">Customer</div>
          <div class="name">${selectedCustomer}</div>
        </div>

        <table>
          <thead><tr><th>Date</th><th>Bill No.</th><th>Items</th><th class="num">Amount</th></tr></thead>
          <tbody>
            ${co.map(o=>`<tr>
              <td>${o.order_date||"–"}</td>
              <td class="mono">${o.id}</td>
              <td style="font-size:12px;color:#6B6F62;">${(o.items||[]).map(it=>`${it.name} ${fmtQty(it.actual_qty??it.qty)}${it.unit}`).join(", ")}</td>
              <td class="num">${fmtMoney(orderTotal(o,inventory))}</td>
            </tr>`).join("")}
          </tbody>
        </table>

        <div class="totals">
          <div class="totals-box">
            <div class="grand"><span class="gl">Total</span><span class="gv">${fmtMoney(total)}</span></div>
          </div>
        </div>

        <div class="footer">
          <div>
            <div class="thanks">Thank you for your business.</div>
            <div class="thanks-sub">Exotic Greens — Fresh Exotic Vegetables</div>
          </div>
        </div>
      </div>
      <div class="printbar"><button onclick="window.print()">Print statement</button></div>
    </body></html>`);
    w.document.close();
    setTimeout(()=>w.print(),400);
  }

  return <div>
    <div style={{fontFamily:FD,fontWeight:700,fontSize:22,color:T.ink,marginBottom:20}}>Sales Analytics</div>

    {/* ── DAILY REPORT ── */}
    {(()=>{
      const dayOrders=orders.filter(o=>(o.delivery_date||o.order_date||"")===selectedDay&&o.status!=="");
      const dayRevenue=dayOrders.reduce((s,o)=>s+orderTotal(o,inventory),0);
      const dayCustomers=[...new Set(dayOrders.map(o=>o.customer).filter(Boolean))];
      const deliveredDay=dayOrders.filter(o=>o.status==="Delivered");
      const custBreakdown={};
      dayOrders.forEach(o=>{ if(o.customer)custBreakdown[o.customer]=(custBreakdown[o.customer]||0)+orderTotal(o,inventory); });
      const custList=Object.entries(custBreakdown).sort((a,b)=>b[1]-a[1]);
      const maxCust=custList.length?custList[0][1]:1;
      const itemBreakdown={};
      dayOrders.forEach(o=>(o.items||[]).forEach(it=>{
        const baseUnit=inventory[it.name]?.unit||"kg";
        itemBreakdown[it.name]=(itemBreakdown[it.name]||0)+toBaseQty(it.actual_qty??it.qty,it.unit,baseUnit);
      }));
      const itemList=Object.entries(itemBreakdown).sort((a,b)=>b[1]-a[1]).slice(0,8);
      const maxItem=itemList.length?itemList[0][1]:1;
      return <div style={{marginBottom:28}}>
        <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",flexWrap:"wrap",gap:12,marginBottom:16}}>
          <div style={{fontFamily:FD,fontWeight:700,fontSize:18,color:T.ink}}>Daily Report</div>
          <div style={{display:"flex",alignItems:"center",gap:10}}>
            <button onClick={()=>setSelectedDay(p=>{const d=new Date(p);d.setDate(d.getDate()-1);return d.toISOString().split("T")[0];})} style={{...BTN(),padding:"7px 12px",border:`1px solid ${T.line}`,background:"transparent",color:T.ink,fontSize:16}}>‹</button>
            <input type="date" value={selectedDay} onChange={e=>setSelectedDay(e.target.value)} style={{...II,width:"auto",fontWeight:700,fontSize:14}}/>
            <button onClick={()=>setSelectedDay(p=>{const d=new Date(p);d.setDate(d.getDate()+1);return d.toISOString().split("T")[0];})} style={{...BTN(),padding:"7px 12px",border:`1px solid ${T.line}`,background:"transparent",color:T.ink,fontSize:16}}>›</button>
            {selectedDay!==today()&&<button onClick={()=>setSelectedDay(today())} style={{...BTN(),padding:"6px 12px",border:`1px solid ${T.line}`,background:"transparent",color:T.inkMuted,fontSize:12}}>Today</button>}
          </div>
        </div>
        <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(150px,1fr))",gap:1,marginBottom:18,background:T.line,borderRadius:3,overflow:"hidden"}}>
          {[["Revenue",fmtMoney(dayRevenue),T.moss],["Orders",String(dayOrders.length),T.gold],["Delivered",String(deliveredDay.length),"#5C8A3D"],["Customers",String(dayCustomers.length),"#4A7BA6"]].map(([l,v,c])=>(
            <div key={l} style={{background:T.paperWhite,padding:"16px 18px"}}>
              <div style={{fontSize:10,color:T.inkMuted,fontFamily:FM,textTransform:"uppercase",letterSpacing:"0.05em",marginBottom:5,fontWeight:600}}>{l}</div>
              <div style={{fontSize:26,fontWeight:700,color:c,fontFamily:FD}}>{v}</div>
            </div>
          ))}
        </div>
        <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(280px,1fr))",gap:16}}>
          <div style={{background:T.paperWhite,border:`1px solid ${T.line}`,borderRadius:3,padding:18}}>
            <div style={{fontFamily:FD,fontWeight:700,fontSize:15,color:T.ink,marginBottom:14}}>Revenue by customer</div>
            {custList.length===0?<div style={{color:T.inkMuted,fontSize:13,fontStyle:"italic"}}>No orders for this date</div>:
              custList.map(([name,rev])=>(
                <div key={name} style={{marginBottom:10}}>
                  <div style={{display:"flex",justifyContent:"space-between",marginBottom:4}}>
                    <span style={{fontSize:13,fontWeight:600,color:T.ink}}>{name}</span>
                    <span style={{fontFamily:FM,fontSize:13,color:T.moss,fontWeight:700}}>{fmtMoney(rev)}</span>
                  </div>
                  <div style={{background:T.line,borderRadius:2,height:8,overflow:"hidden"}}>
                    <div style={{width:`${Math.round(rev/maxCust*100)}%`,height:"100%",background:T.moss,borderRadius:2}}/>
                  </div>
                </div>
              ))
            }
          </div>
          <div style={{background:T.paperWhite,border:`1px solid ${T.line}`,borderRadius:3,padding:18}}>
            <div style={{fontFamily:FD,fontWeight:700,fontSize:15,color:T.ink,marginBottom:14}}>Items dispatched</div>
            {itemList.length===0?<div style={{color:T.inkMuted,fontSize:13,fontStyle:"italic"}}>No items for this date</div>:
              itemList.map(([name,qty])=>(
                <div key={name} style={{marginBottom:10}}>
                  <div style={{display:"flex",justifyContent:"space-between",marginBottom:4}}>
                    <span style={{fontSize:13,fontWeight:600,color:T.ink}}>{name}</span>
                    <span style={{fontFamily:FM,fontSize:12,color:T.inkMuted,fontWeight:600}}>{fmtQty(qty)} {inventory[name]?.unit||"kg"}</span>
                  </div>
                  <div style={{background:T.line,borderRadius:2,height:8,overflow:"hidden"}}>
                    <div style={{width:`${Math.round(qty/maxItem*100)}%`,height:"100%",background:T.gold,borderRadius:2}}/>
                  </div>
                </div>
              ))
            }
          </div>
        </div>
      </div>;
    })()}

    <div style={{height:1,background:T.line,marginBottom:24}}/>

    {/* ── MONTHLY / RANGE REPORT ── */}
    <div style={{fontFamily:FD,fontWeight:700,fontSize:18,color:T.ink,marginBottom:14}}>Breakdown</div>
    <div style={{display:"flex",gap:12,marginBottom:20,alignItems:"flex-end",flexWrap:"wrap"}}>
      <div style={{display:"flex",gap:1,background:T.line,borderRadius:3,overflow:"hidden",width:"fit-content"}}>
        {[["month","By month"],["range","Custom range"]].map(([id,label])=>(
          <button key={id} onClick={()=>setRangeMode(id)} style={{padding:"9px 14px",border:"none",background:rangeMode===id?T.moss:T.paperWhite,color:rangeMode===id?T.paperWhite:T.inkMuted,cursor:"pointer",fontSize:12,fontWeight:600,fontFamily:FB}}>{label}</button>
        ))}
      </div>
      {rangeMode==="month"
        ?<div>
          <label style={IL}>Month</label>
          <input type="month" value={selectedMonth} onChange={e=>setSelectedMonth(e.target.value)} style={{...II,width:"auto"}}/>
        </div>
        :<>
          <div>
            <label style={IL}>From</label>
            <input type="date" value={rangeFrom} onChange={e=>setRangeFrom(e.target.value)} style={{...II,width:"auto"}}/>
          </div>
          <div>
            <label style={IL}>To</label>
            <input type="date" value={rangeTo} onChange={e=>setRangeTo(e.target.value)} style={{...II,width:"auto"}}/>
          </div>
        </>
      }
    </div>

    {/* Monthly summary cards */}
    {(()=>{
      const profit=monthTotal-monthPurchaseCost;
      const profitColor=profit>=0?"#2D6A4F":"#8A3A2D";
      const statCards=[
        ["Total revenue",fmtMoney(monthTotal),T.moss],
        ["Purchase cost",fmtMoney(monthPurchaseCost),T.clay],
        ["Gross profit",fmtMoney(profit),profitColor],
        ["Orders",String(monthOrders.length),T.gold],
        ["Customers",String([...new Set(monthOrders.map(o=>o.customer).filter(Boolean))].length),"#4A7BA6"],
      ];
      return <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(140px,1fr))",gap:1,marginBottom:20,background:T.line,borderRadius:3,overflow:"hidden"}}>
        {statCards.map(([l,v,c])=>(
          <div key={l} style={{background:T.paperWhite,padding:"16px 20px"}}>
            <div style={{fontSize:10,color:T.inkMuted,fontFamily:FM,textTransform:"uppercase",letterSpacing:"0.05em",marginBottom:6,fontWeight:600}}>{l}</div>
            <div style={{fontSize:28,fontWeight:700,color:c,fontFamily:FD}}>{v}</div>
          </div>
        ))}
      </div>;
    })()}

    <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(260px,1fr))",gap:20,marginBottom:24}}>
      {/* Top customers */}
      <div style={{background:T.paperWhite,border:`1px solid ${T.line}`,borderRadius:3,padding:18}}>
        <div style={{fontFamily:FD,fontWeight:700,fontSize:15,marginBottom:14,color:T.ink}}>Top customers</div>
        {topCustomers.length===0
          ?<div style={{color:T.inkMuted,fontSize:13}}>No data</div>
          :topCustomers.map(([name,total])=>{
            const maxVal=topCustomers[0][1];
            return <div key={name} style={{marginBottom:10}}>
              <div style={{display:"flex",justifyContent:"space-between",marginBottom:4}}>
                <span style={{fontSize:13,fontWeight:600,color:T.ink}}>{name}</span>
                <span style={{fontFamily:FM,color:T.moss,fontWeight:700}}>{fmtMoney(total)}</span>
              </div>
              <div style={{background:T.line,borderRadius:2,height:6}}>
                <div style={{width:`${Math.round(total/maxVal*100)}%`,height:"100%",background:T.moss,borderRadius:2}}/>
              </div>
            </div>;
          })
        }
      </div>
      {/* Top items */}
      <div style={{background:T.paperWhite,border:`1px solid ${T.line}`,borderRadius:3,padding:18}}>
        <div style={{fontFamily:FD,fontWeight:700,fontSize:15,marginBottom:14,color:T.ink}}>Top items sold</div>
        {topItems.length===0
          ?<div style={{color:T.inkMuted,fontSize:13}}>No data</div>
          :topItems.map(([name,qty])=>{
            const maxVal=topItems[0][1];
            return <div key={name} style={{marginBottom:10}}>
              <div style={{display:"flex",justifyContent:"space-between",marginBottom:4}}>
                <span style={{fontSize:13,fontWeight:600,color:T.ink}}>{name}</span>
                <span style={{fontFamily:FM,color:T.inkMuted,fontWeight:600}}>{fmtQty(qty)} {inventory[name]?.unit||"kg"}</span>
              </div>
              <div style={{background:T.line,borderRadius:2,height:6}}>
                <div style={{width:`${Math.round(qty/maxVal*100)}%`,height:"100%",background:T.gold,borderRadius:2}}/>
              </div>
            </div>;
          })
        }
      </div>
    </div>

    {/* Customer statement */}
    <div style={{background:T.paperWhite,border:`1px solid ${T.line}`,borderRadius:3,padding:20}}>
      <div style={{fontFamily:FD,fontWeight:700,fontSize:15,marginBottom:14,color:T.ink}}>Customer monthly statement</div>
      <div style={{display:"flex",gap:12,alignItems:"flex-end",marginBottom:16}}>
        <div style={{flex:1}}>
          <label style={IL}>Select customer</label>
          <select value={selectedCustomer} onChange={e=>setSelectedCustomer(e.target.value)} style={II}>
            <option value="">— choose customer —</option>
            {customers.map(c=><option key={c}>{c}</option>)}
          </select>
        </div>
        {selectedCustomer&&<button onClick={printStatement} style={{...BTN(),background:T.moss,color:T.paperWhite}}>Print statement</button>}
      </div>
      {selectedCustomer&&customerOrders.length===0&&<div style={{color:T.inkMuted,fontSize:13}}>No orders for {selectedCustomer} in {periodLabel}.</div>}
      {customerOrders.length>0&&<div style={{overflowX:"auto"}}><table style={{width:"100%",borderCollapse:"collapse",fontSize:13,minWidth:480}}>
        <thead><tr style={{background:T.paper}}>
          {["Date","Bill No","Items","Amount"].map(h=><th key={h} style={{padding:"8px 10px",textAlign:h==="Amount"?"right":"left",fontFamily:FM,fontSize:10,textTransform:"uppercase",letterSpacing:"0.03em",color:T.inkMuted,fontWeight:700}}>{h}</th>)}
        </tr></thead>
        <tbody>
          {customerOrders.map(o=>(
            <tr key={o.id} style={{borderBottom:`1px solid ${T.line}`}}>
              <td style={{padding:"9px 10px",fontFamily:FM,fontSize:12,fontWeight:600}}>{o.order_date||"–"}</td>
              <td style={{padding:"9px 10px",fontFamily:FM,color:T.gold,fontSize:12,fontWeight:600}}>{o.id}</td>
              <td style={{padding:"9px 10px",color:T.inkMuted,fontSize:12}}>{(o.items||[]).map(it=>`${it.name} ${fmtQty(it.actual_qty??it.qty)}${it.unit}`).join(", ")}</td>
              <td style={{padding:"9px 10px",textAlign:"right",fontFamily:FM,color:T.ink,fontWeight:700}}>{fmtMoney(orderTotal(o,inventory))}</td>
            </tr>
          ))}
        </tbody>
        <tfoot>
          <tr style={{background:T.paper}}>
            <td colSpan={3} style={{padding:"10px",fontWeight:700,fontFamily:FD,fontSize:14}}>Total</td>
            <td style={{padding:"10px",textAlign:"right",fontWeight:700,fontFamily:FM,color:T.moss,fontSize:16}}>{fmtMoney(customerOrders.reduce((s,o)=>s+orderTotal(o,inventory),0))}</td>
          </tr>
        </tfoot>
      </table></div>}
    </div>
  </div>;
}

// ─── PURCHASES ────────────────────────────────────────────────────────────────
function Purchases({inventory,onInventoryUpdate,onPurchaseSaved,savedVendors,onSaveVendor}){
  const [purchases,setPurchases]=useState([]);
  const [loading,setLoading]=useState(true);
  const [showAdd,setShowAdd]=useState(false);
  const [saving,setSaving]=useState(false);
  const [purchaseMonth,setPurchaseMonth]=useState(today().slice(0,7));
  const [editingGroup,setEditingGroup]=useState(null);
  const [editForm,setEditForm]=useState({vendor:"",date:"",notes:"",items:[]});
  const blankItem={item:DEFAULT_ITEMS[0],qty:"",unit:"kg",rate:""};
  const [form,setForm]=useState({vendor:"",date:today(),notes:"",items:[{...blankItem}]});
  const [saveVendor,setSaveVendor]=useState(false);

  function fetchPurchases(){
    return supabase.from("purchases").select("*").order("date",{ascending:false}).order("created_at",{ascending:false})
      .then(({data})=>setPurchases(data||[]));
  }

  useEffect(()=>{
    fetchPurchases().finally(()=>setLoading(false));
  },[]);

  // Realtime — so a purchase entered on one device shows up for everyone else without a refresh
  useEffect(()=>{
    let timer;
    const ch=supabase.channel("purchases-rt")
      .on("postgres_changes",{event:"*",schema:"public",table:"purchases"},()=>{clearTimeout(timer);timer=setTimeout(fetchPurchases,400);})
      .subscribe();
    return()=>{clearTimeout(timer);supabase.removeChannel(ch);};
  },[]);

  function setF(k,v){setForm(f=>({...f,[k]:v}));}
  function setItem(i,k,v){const items=[...form.items];items[i]={...items[i],[k]:v};setF("items",items);}
  function addItem(){setF("items",[...form.items,{...blankItem}]);}
  function removeItem(i){if(form.items.length===1)return;setF("items",form.items.filter((_,j)=>j!==i));}

  function pickVendor(name){
    const v=(savedVendors||[]).find(v=>v.name===name);
    setF("vendor",name);
  }

  async function savePurchase(){
    if(!form.vendor.trim()){alert("Vendor name is required.");return;}
    const validItems=form.items.filter(it=>it.qty&&it.item);
    if(!validItems.length){alert("Add at least one item with a quantity.");return;}
    setSaving(true);

    const groupId=crypto.randomUUID();
    const rows=validItems.map(it=>({
      vendor:form.vendor,date:form.date,notes:form.notes,
      item:it.item,qty:parseFloat(it.qty)||0,
      unit:it.unit,rate:parseFloat(it.rate)||0,
      group_id:groupId,
    }));

    const{error,data}=await supabase.from("purchases").insert(rows).select();
    if(!error){
      setPurchases(p=>[...data,...p]);

      // Update inventory for each item
      let updatedInventory={...inventory};
      for(const row of rows){
        const current=updatedInventory[row.item];
        const newQty=(current?.qty||0)+row.qty;
        updatedInventory={...updatedInventory,[row.item]:{
          qty:newQty,unit:current?.unit||row.unit,
          rate:current?.rate||row.rate,customerRates:current?.customerRates||{},
        }};
        await supabase.from("inventory").upsert([{name:row.item,qty:newQty,unit:updatedInventory[row.item].unit,rate:updatedInventory[row.item].rate}]);
      }
      onInventoryUpdate(updatedInventory);

      // Save vendor permanently if checkbox ticked
      if(saveVendor&&onSaveVendor)onSaveVendor({name:form.vendor});

      // Single ledger entry for the whole purchase group
      const total=rows.reduce((s,r)=>s+(r.qty||0)*(r.rate||0),0);
      const itemSummary=rows.map(r=>`${r.item} ${fmtQty(r.qty)}${r.unit}`).join(", ");
      onPurchaseSaved&&onPurchaseSaved({vendor:form.vendor,date:form.date,total,itemSummary,id:groupId});

      setShowAdd(false);
      setForm({vendor:"",date:today(),notes:"",items:[{...blankItem}]});
      setSaveVendor(false);
    }
    setSaving(false);
  }


  async function deletePurchase(id){
    if(!window.confirm("Delete this purchase entry?"))return;
    await supabase.from("purchases").delete().eq("id",id);
    setPurchases(p=>p.filter(x=>x.id!==id));
  }

  // Group purchases by group_id for display (or individual id if no group_id)
  const groups={};
  purchases.forEach(p=>{
    const key=p.group_id||p.id;
    if(!groups[key])groups[key]={id:key,vendor:p.vendor,date:p.date,notes:p.notes,items:[],created_at:p.created_at};
    groups[key].items.push(p);
  });
  const groupList=Object.values(groups).sort((a,b)=>(b.date||"").localeCompare(a.date||"")||(b.created_at||"").localeCompare(a.created_at||""))
    .filter(g=>!purchaseMonth||(g.date||"").startsWith(purchaseMonth));

  function openEditGroup(g){
    setEditingGroup(g);
    setEditForm({
      vendor:g.vendor,date:g.date,notes:g.notes||"",
      items:g.items.map(p=>({id:p.id,item:p.item,qty:String(p.qty),unit:p.unit,rate:String(p.rate)})),
    });
  }

  async function saveEditGroup(){
    if(!editForm.vendor||!editingGroup)return;
    setSaving(true);
    const existingItems=editForm.items.filter(it=>it.id);
    const newItems=editForm.items.filter(it=>!it.id);
    // Update existing rows
    const updates=existingItems.map(it=>
      supabase.from("purchases").update({
        vendor:editForm.vendor,date:editForm.date,notes:editForm.notes,
        item:it.item,qty:parseFloat(it.qty)||0,unit:it.unit,rate:parseFloat(it.rate)||0,
      }).eq("id",it.id)
    );
    // Insert new rows with same group_id
    const inserts=newItems.filter(it=>it.item&&it.qty).map(it=>({
      vendor:editForm.vendor,date:editForm.date,notes:editForm.notes,
      item:it.item,qty:parseFloat(it.qty)||0,unit:it.unit,rate:parseFloat(it.rate)||0,
      group_id:editingGroup.id,
    }));
    await Promise.all([...updates, inserts.length?supabase.from("purchases").insert(inserts):Promise.resolve()]);
    const{data}=await supabase.from("purchases").select("*").order("date",{ascending:false}).order("created_at",{ascending:false});
    setPurchases(data||[]);
    setEditingGroup(null);
    setSaving(false);
  }

  async function deleteGroup(groupId,items){
    if(!window.confirm(`Delete this entire purchase entry (${items.length} item${items.length>1?"s":""})?`))return;
    const ids=items.map(i=>i.id);
    await Promise.all(ids.map(id=>supabase.from("purchases").delete().eq("id",id)));
    setPurchases(p=>p.filter(x=>!ids.includes(x.id)));
  }

  const totalThisMonth=purchases.filter(p=>(p.date||"").startsWith(today().slice(0,7))).reduce((s,p)=>s+(p.qty||0)*(p.rate||0),0);
  const allVendorNames=[...new Set([...(savedVendors||[]).map(v=>v.name),...purchases.map(p=>p.vendor).filter(Boolean)])].sort();

  return <div>
    <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:20,flexWrap:"wrap",gap:10}}>
      <div>
        <div style={{fontFamily:FD,fontWeight:600,fontSize:20,color:T.ink}}>Purchases</div>
        <div style={{fontSize:13,color:T.inkMuted,marginTop:3}}>This month: {fmtMoney(totalThisMonth)}</div>
      </div>
      <div style={{display:"flex",gap:10,alignItems:"center",flexWrap:"wrap"}}>
        <input type="month" value={purchaseMonth} onChange={e=>setPurchaseMonth(e.target.value)} style={{...II,width:"auto"}}/>
        <button onClick={()=>setShowAdd(v=>!v)} style={{...BTN(),background:T.moss,color:T.paperWhite}}>+ Add purchase</button>
      </div>
    </div>

    {showAdd&&<div style={{background:T.paperWhite,border:`1px solid ${T.line}`,borderRadius:3,padding:18,marginBottom:18}}>
      <div style={{fontFamily:FD,fontWeight:600,fontSize:15,marginBottom:14,color:T.ink}}>New purchase</div>

      {/* Vendor + date + notes */}
      {savedVendors?.length>0&&<div style={{marginBottom:12}}>
        <label style={IL}>Quick-select vendor</label>
        <SearchSelect options={savedVendors.map(v=>({value:v.name,label:v.name}))} value={form.vendor} onChange={v=>pickVendor(v)} placeholder="— search saved vendors —"/>
      </div>}

      <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(180px,1fr))",gap:10,marginBottom:12}}>
        <div>
          <label style={IL}>Vendor *</label>
          <input value={form.vendor} onChange={e=>setF("vendor",e.target.value)} list="vendor-opts" placeholder="Supplier name" style={II}/>
          <datalist id="vendor-opts">{allVendorNames.map(n=><option key={n} value={n}/>)}</datalist>
        </div>
        <div>
          <label style={IL}>Date</label>
          <input type="date" value={form.date} onChange={e=>setF("date",e.target.value)} style={II}/>
        </div>
        <div style={{gridColumn:"1/-1"}}>
          <label style={IL}>Notes (optional)</label>
          <input value={form.notes} onChange={e=>setF("notes",e.target.value)} placeholder="e.g. morning delivery" style={II}/>
        </div>
      </div>

      <label style={{display:"flex",alignItems:"center",gap:7,fontSize:12,color:T.inkMuted,cursor:"pointer",marginBottom:16}}>
        <input type="checkbox" checked={saveVendor} onChange={e=>setSaveVendor(e.target.checked)}/>
        Save "{form.vendor||"this vendor"}" as a permanent vendor for quick selection next time
      </label>

      {/* Multi-item rows */}
      <div style={{fontFamily:FD,fontWeight:600,fontSize:14,color:T.ink,marginBottom:8}}>Items</div>
      <div style={{border:`1px solid ${T.line}`,borderRadius:3,marginBottom:12}}>
        <div style={{display:"flex",gap:8,padding:"7px 12px",background:T.paper,borderBottom:`1px solid ${T.line}`,fontSize:10,color:T.inkMuted,fontFamily:FM,textTransform:"uppercase",letterSpacing:"0.04em"}}>
          <span style={{flex:"2 0 140px"}}>Item</span>
          <span style={{flex:"1 0 70px"}}>Qty</span>
          <span style={{flex:"1 0 80px"}}>Unit</span>
          <span style={{flex:"1 0 80px"}}>Rate (₹)</span>
          <span style={{flex:"1 0 80px",textAlign:"right"}}>Total</span>
          <span style={{width:24}}/>
        </div>
        {form.items.map((it,i)=>(
          <div key={i} style={{display:"flex",gap:8,alignItems:"center",padding:"9px 12px",borderBottom:i<form.items.length-1?`1px solid ${T.line}`:"none",flexWrap:"wrap"}}>
            <SearchSelect
              options={Object.keys(inventory).length?Object.keys(inventory):DEFAULT_ITEMS}
              value={it.item}
              onChange={v=>setItem(i,"item",v)}
              style={{flex:"2 0 140px"}}
            />
            <input type="number" value={it.qty} onChange={e=>setItem(i,"qty",e.target.value)} placeholder="0" style={{...II,flex:"1 0 70px",padding:"7px 8px",fontFamily:FM}}/>
            <select value={it.unit} onChange={e=>setItem(i,"unit",e.target.value)} style={{...II,flex:"1 0 80px",padding:"7px 8px"}}>
              {["kg","grams","pcs","pkt","bunches","boxes","crates"].map(u=><option key={u}>{u}</option>)}
            </select>
            <input type="number" value={it.rate} onChange={e=>setItem(i,"rate",e.target.value)} placeholder="0" style={{...II,flex:"1 0 80px",padding:"7px 8px",fontFamily:FM}}/>
            <span style={{flex:"1 0 80px",textAlign:"right",fontFamily:FM,fontSize:12,color:T.moss,fontWeight:600}}>
              {fmtMoney((parseFloat(it.qty)||0)*(parseFloat(it.rate)||0))}
            </span>
            <button onClick={()=>removeItem(i)} style={{background:"none",border:"none",cursor:"pointer",color:T.clay,fontSize:16,padding:8,flexShrink:0}}>✕</button>
          </div>
        ))}
        <button onClick={addItem} style={{width:"100%",padding:"10px",background:"none",border:"none",borderTop:`1px solid ${T.line}`,cursor:"pointer",fontSize:13,color:T.moss,fontFamily:FB,fontWeight:500}}>
          + Add item
        </button>
      </div>

      <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:14}}>
        <div style={{fontFamily:FM,fontSize:15,color:T.moss,fontWeight:700}}>
          Grand total: {fmtMoney(form.items.reduce((s,it)=>s+(parseFloat(it.qty)||0)*(parseFloat(it.rate)||0),0))}
        </div>
      </div>

      <div style={{display:"flex",gap:10}}>
        <button onClick={()=>{setShowAdd(false);setForm({vendor:"",date:today(),notes:"",items:[{...blankItem}]});}} style={{...BTN(),border:`1px solid ${T.line}`,background:"transparent",color:T.ink}}>Cancel</button>
        <button onClick={savePurchase} disabled={saving||!form.vendor} style={{...BTN(),flex:1,background:T.moss,color:T.paperWhite,padding:"11px 0"}}>
          {saving?"Saving…":"Save purchase"}
        </button>
      </div>
    </div>}

    {/* Vendor summary chips */}
    {allVendorNames.length>0&&<div style={{display:"flex",gap:8,flexWrap:"wrap",marginBottom:20}}>
      {allVendorNames.map(v=>{
        const vtotal=purchases.filter(p=>p.vendor===v).reduce((s,p)=>s+(p.qty||0)*(p.rate||0),0);
        return <div key={v} style={{background:T.paperWhite,border:`1px solid ${T.line}`,borderRadius:3,padding:"8px 14px"}}>
          <div style={{fontSize:12,fontWeight:600,color:T.ink}}>{v}</div>
          <div style={{fontSize:12,color:T.moss,fontFamily:FM,marginTop:2}}>{fmtMoney(vtotal)}</div>
        </div>;
      })}
    </div>}

    {/* Grouped purchase list */}
    {loading?<div style={{padding:30,textAlign:"center",color:T.inkMuted}}>Loading…</div>:
    <div style={{display:"grid",gap:10}}>
      {groupList.length===0
        ?<div style={{textAlign:"center",padding:40,color:T.inkMuted,fontStyle:"italic",fontFamily:FD}}>No purchases yet</div>
        :groupList.map(g=>{
          const gTotal=g.items.reduce((s,p)=>s+(p.qty||0)*(p.rate||0),0);
          return <div key={g.id} style={{background:T.paperWhite,border:`1px solid ${T.line}`,borderRadius:3}}>
            <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",padding:"11px 14px",borderBottom:`1px solid ${T.line}`,flexWrap:"wrap",gap:8}}>
              <div>
                <span style={{fontWeight:600,fontSize:14,color:T.ink}}>{g.vendor}</span>
                <span style={{fontSize:11,color:T.inkMuted,fontFamily:FM,marginLeft:10}}>{g.date}</span>
                {g.notes&&<span style={{fontSize:11,color:T.inkMuted,marginLeft:8,fontStyle:"italic"}}>{g.notes}</span>}
              </div>
              <div style={{display:"flex",alignItems:"center",gap:10}}>
                <span style={{fontFamily:FM,fontWeight:700,color:T.moss,fontSize:14}}>{fmtMoney(gTotal)}</span>
                <button onClick={()=>openEditGroup(g)} style={{...BTN(),padding:"5px 10px",background:"transparent",border:`1px solid ${T.line}`,color:T.ink,fontSize:11}}>Edit</button>
                <button onClick={()=>deleteGroup(g.id,g.items)} style={{...BTN(),padding:"5px 10px",background:"transparent",border:`1px solid ${T.clay}`,color:T.clay,fontSize:11}}>Delete</button>
              </div>
            </div>
            <div>
              {g.items.map((p,i)=>(
                <div key={p.id} style={{display:"flex",justifyContent:"space-between",alignItems:"center",padding:"8px 14px",borderBottom:i<g.items.length-1?`1px solid ${T.line}`:"none",flexWrap:"wrap",gap:8}}>
                  <span style={{fontSize:13,color:T.ink}}>{p.item}</span>
                  <div style={{display:"flex",gap:16,alignItems:"center",flexWrap:"wrap"}}>
                    <span style={{fontFamily:FM,fontSize:12,color:T.inkMuted}}>{fmtQty(p.qty)} {p.unit} @ {fmtMoney(p.rate)}</span>
                    <span style={{fontFamily:FM,fontSize:12,color:T.ink,fontWeight:600}}>{fmtMoney((p.qty||0)*(p.rate||0))}</span>
                    <button onClick={()=>deletePurchase(p.id)} style={{background:"none",border:"none",cursor:"pointer",color:T.clay,fontSize:12}}>Delete</button>
                  </div>
                </div>
              ))}
            </div>
          </div>;
        })
      }
    </div>}

    {/* Edit purchase modal */}
    {editingGroup&&<Modal onClose={()=>setEditingGroup(null)} width={600}>
      <ModalHeader title="Edit purchase" sub={editingGroup.vendor} onClose={()=>setEditingGroup(null)}/>
      <div style={{padding:20}}>
        <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:10,marginBottom:14}}>
          <div><label style={IL}>Vendor</label><input value={editForm.vendor} onChange={e=>setEditForm(f=>({...f,vendor:e.target.value}))} style={II}/></div>
          <div><label style={IL}>Date</label><input type="date" value={editForm.date} onChange={e=>setEditForm(f=>({...f,date:e.target.value}))} style={II}/></div>
          <div style={{gridColumn:"1/-1"}}><label style={IL}>Notes</label><input value={editForm.notes} onChange={e=>setEditForm(f=>({...f,notes:e.target.value}))} style={II}/></div>
        </div>
        <div style={{border:`1px solid ${T.line}`,borderRadius:3,marginBottom:14,overflowX:"auto"}}>
          <div style={{minWidth:420}}>
          {editForm.items.map((it,i)=>(
            <div key={i} style={{display:"grid",gridTemplateColumns:"2fr 80px 80px 80px 32px",gap:8,padding:"10px 12px",borderBottom:i<editForm.items.length-1?`1px solid ${T.line}`:"none",alignItems:"center"}}>
              <SearchSelect
                options={Object.keys(inventory).length?Object.keys(inventory):DEFAULT_ITEMS}
                value={it.item}
                onChange={v=>{const items=[...editForm.items];items[i]={...items[i],item:v};setEditForm(f=>({...f,items}));}}
              />
              <div><label style={{...IL,marginBottom:2}}>Qty</label><input type="number" value={it.qty} onChange={e=>{const items=[...editForm.items];items[i]={...items[i],qty:e.target.value};setEditForm(f=>({...f,items}));}} style={{...II,padding:"5px 8px",fontSize:12}}/></div>
              <div><label style={{...IL,marginBottom:2}}>Unit</label><select value={it.unit} onChange={e=>{const items=[...editForm.items];items[i]={...items[i],unit:e.target.value};setEditForm(f=>({...f,items}));}} style={{...II,padding:"5px 8px",fontSize:12}}>{["kg","grams","pcs","pkt","bunches","boxes","crates"].map(u=><option key={u}>{u}</option>)}</select></div>
              <div><label style={{...IL,marginBottom:2}}>Rate ₹</label><input type="number" value={it.rate} onChange={e=>{const items=[...editForm.items];items[i]={...items[i],rate:e.target.value};setEditForm(f=>({...f,items}));}} style={{...II,padding:"5px 8px",fontSize:12,fontFamily:FM}}/></div>
              {!it.id&&<button onClick={()=>setEditForm(f=>({...f,items:f.items.filter((_,j)=>j!==i)}))} style={{background:"none",border:"none",cursor:"pointer",color:T.clay,fontSize:16,paddingTop:18}}>✕</button>}
              {it.id&&<span/>}
            </div>
          ))}
          </div>
          <button onClick={()=>setEditForm(f=>({...f,items:[...f.items,{item:DEFAULT_ITEMS[0],qty:"",unit:"kg",rate:"",_new:true}]}))}
            style={{width:"100%",padding:"9px",background:"none",border:"none",borderTop:`1px solid ${T.line}`,cursor:"pointer",fontSize:13,color:T.moss,fontWeight:600}}>
            + Add item
          </button>
        </div>
        <div style={{display:"flex",gap:10}}>
          <button onClick={()=>setEditingGroup(null)} style={{...BTN(),border:`1px solid ${T.line}`,background:"transparent",color:T.ink}}>Cancel</button>
          <button onClick={saveEditGroup} disabled={saving} style={{...BTN(),flex:1,background:T.moss,color:T.paperWhite}}>{saving?"Saving…":"Save changes"}</button>
        </div>
      </div>
    </Modal>}
  </div>;
}

// ─── ADMIN ────────────────────────────────────────────────────────────────────
// ─── ACCOUNTS / LEDGER (Khatabook-style) ──────────────────────────────────────
function PartyCard({p,onSelect,onSaveAsRegular}){
  return <div style={{background:T.paperWhite,border:`1px solid ${T.line}`,borderRadius:3,padding:"13px 16px",display:"flex",justifyContent:"space-between",alignItems:"center",gap:8}}>
    <div onClick={()=>onSelect(p.name)} style={{flex:1,cursor:"pointer"}}>
      <div style={{fontWeight:600,fontSize:14,color:T.ink}}>{p.name}</div>
      <div style={{fontSize:10,color:T.inkMuted,fontFamily:FM,textTransform:"uppercase",letterSpacing:"0.04em",marginTop:2}}>{p.entries.length} entries</div>
    </div>
    <div style={{display:"flex",alignItems:"center",gap:10}}>
      {onSaveAsRegular&&<button onClick={e=>{e.stopPropagation();onSaveAsRegular(p.name);}} style={{...BTN(),padding:"5px 10px",fontSize:11,background:"transparent",border:`1px solid ${T.moss}`,color:T.moss}}>+ Save as regular</button>}
      <div onClick={()=>onSelect(p.name)} style={{textAlign:"right",cursor:"pointer"}}>
        <div style={{fontFamily:FM,fontWeight:700,fontSize:15,color:p.balance>0?T.moss:p.balance<0?T.clay:T.inkMuted}}>{fmtMoney(Math.abs(p.balance))}</div>
        <div style={{fontSize:10,color:T.inkMuted}}>{p.balance>0?"owes you":p.balance<0?"you owe":"settled"}</div>
      </div>
    </div>
  </div>;
}

function AccountsPanel({ledgerEntries,onAddEntry,onDeleteEntry,onEditEntry,savedCustomers,purchaseVendors,orders,onDeleteOrder,inventory,onSaveCustomer,user}){
  const [view,setView]=useState("parties"); // parties | summary
  const [selectedParty,setSelectedParty]=useState(null);
  const [showAddEntry,setShowAddEntry]=useState(false);
  const [entryForm,setEntryForm]=useState({party_name:"",party_type:"customer",entry_type:"gave",amount:"",date:today(),notes:""});
  const [saving,setSaving]=useState(false);
  const [stFrom,setStFrom]=useState("");
  const [stTo,setStTo]=useState("");
  const [detailedSt,setDetailedSt]=useState(false);
  const [editEntry,setEditEntry]=useState(null);
  const [editForm,setEditForm]=useState({amount:"",date:"",notes:"",entry_type:"gave"});
  const [editSaving,setEditSaving]=useState(false);
  const [expandedEntryId,setExpandedEntryId]=useState(null);
  const [partySearch,setPartySearch]=useState("");
  // Opening balance form state — lifted here to avoid hooks-in-conditional violation
  const [showObForm,setShowObForm]=useState(false);
  const [obAmount,setObAmount]=useState("");
  const [obType,setObType]=useState("gave");
  const [obSaving,setObSaving]=useState(false);

  // Handle browser back from party detail → party list
  useEffect(()=>{
    const onPop=e=>{
      if(selectedParty)setSelectedParty(null);
    };
    window.addEventListener("popstate",onPop);
    return()=>window.removeEventListener("popstate",onPop);
  },[selectedParty]);

  // Reset opening balance form whenever party changes so stale values don't leak
  useEffect(()=>{
    setShowObForm(false);
    setObAmount("");
    setObType("gave");
  },[selectedParty]);

  // Scans the full ledger on every render — memoized since this panel commonly
  // holds months of entries and re-renders on every keystroke of the party search.
  const partyMap=useMemo(()=>{
    const map={};
    ledgerEntries.forEach(e=>{
      if(!map[e.party_name])map[e.party_name]={name:e.party_name,type:e.party_type,gave:0,got:0,entries:[]};
      map[e.party_name].entries.push(e);
      if(e.entry_type==="gave")map[e.party_name].gave+=e.amount;
      else map[e.party_name].got+=e.amount;
    });
    return map;
  },[ledgerEntries]);
  const parties=useMemo(()=>Object.values(partyMap).map(p=>({...p,balance:p.gave-p.got})).sort((a,b)=>Math.abs(b.balance)-Math.abs(a.balance)),[partyMap]);

  const totalReceivable=useMemo(()=>parties.filter(p=>p.balance>0).reduce((s,p)=>s+p.balance,0),[parties]);
  const totalPayable=useMemo(()=>parties.filter(p=>p.balance<0).reduce((s,p)=>s+Math.abs(p.balance),0),[parties]);

  const knownPartyNames=useMemo(()=>[...new Set([...savedCustomers.map(c=>c.name),...(purchaseVendors||[]),...parties.map(p=>p.name)])].sort(),[savedCustomers,purchaseVendors,parties]);

  function openEntryForm(partyName,partyType,entryType){
    setEntryForm({party_name:partyName||"",party_type:partyType||"customer",entry_type:entryType||"gave",amount:"",date:today(),notes:""});
    setShowAddEntry(true);
  }

  async function submitEntry(){
    if(!entryForm.party_name.trim()||!entryForm.amount)return;
    setSaving(true);
    await onAddEntry({...entryForm,amount:parseFloat(entryForm.amount)||0});
    setSaving(false);
    setShowAddEntry(false);
  }

  function openEdit(e){
    setEditEntry(e);
    setEditForm({amount:e.amount,date:e.date,notes:e.notes||"",entry_type:e.entry_type});
  }

  async function saveEdit(){
    if(!editForm.amount)return;
    setEditSaving(true);
    await supabase.from("ledger_entries").update({
      amount:parseFloat(editForm.amount)||0,
      date:editForm.date,
      notes:editForm.notes,
      entry_type:editForm.entry_type,
    }).eq("id",editEntry.id);
    onEditEntry&&await onEditEntry();
    logActivity(user,"Ledger entry edited",`${editEntry.party_name} — ${fmtMoney(editEntry.amount)}→${fmtMoney(parseFloat(editForm.amount)||0)}`);
    setEditEntry(null);
    setEditSaving(false);
  }

  if(selectedParty){
    const p=partyMap[selectedParty];
    if(!p)return null;

    // Separate the opening balance entry from regular entries
    const openingEntry=p.entries.find(e=>e.notes==="Opening Balance");
    const regularEntries=p.entries.filter(e=>e.notes!=="Opening Balance");
    const openingAmt=openingEntry?(openingEntry.entry_type==="gave"?openingEntry.amount:-openingEntry.amount):0;

    const allSorted=[...regularEntries].sort((a,b)=>(a.date||"").localeCompare(b.date||"")||(a.created_at||"").localeCompare(b.created_at||""));
    const sortedEntries=[...regularEntries].sort((a,b)=>(b.date||"").localeCompare(a.date||"")||(b.created_at||"").localeCompare(a.created_at||""));

    // Balance = opening + all regular entries
    const totalBalance=openingAmt+regularEntries.reduce((s,e)=>s+(e.entry_type==="gave"?e.amount:-e.amount),0);

    const inRange=allSorted.filter(e=>(!stFrom||e.date>=stFrom)&&(!stTo||e.date<=stTo));
    const periodOpeningBalance=openingAmt+allSorted.filter(e=>stFrom&&e.date<stFrom).reduce((s,e)=>s+(e.entry_type==="gave"?e.amount:-e.amount),0);

    async function saveOpeningBalance(){
      if(!obAmount)return;
      setObSaving(true);
      const payload={party_name:p.name,party_type:p.type,entry_type:obType,amount:parseFloat(obAmount)||0,date:"2000-01-01",notes:"Opening Balance"};
      if(openingEntry){
        await supabase.from("ledger_entries").update(payload).eq("id",openingEntry.id);
      } else {
        await supabase.from("ledger_entries").insert([payload]);
      }
      onEditEntry&&await onEditEntry();
      setShowObForm(false);
      setObSaving(false);
    }

    async function deleteOpeningBalance(){
      if(!openingEntry)return;
      if(!window.confirm("Clear the opening balance? This will affect the account total."))return;
      await onDeleteEntry(openingEntry.id);
    }

    function printStatement(){
      let running=periodOpeningBalance;
      const rows=inRange.map(e=>{
        running+=e.entry_type==="gave"?e.amount:-e.amount;
        return{...e,running};
      });
      const closing=rows.length?rows[rows.length-1].running:periodOpeningBalance;
      const w=window.open("","_blank");
      w.document.write(`<html><head><meta charset="UTF-8"><title>Statement — ${p.name}</title>
      <style>${PRINT_STYLES}</style></head><body>
        <div class="sheet">
          <div class="letterhead">
            <div>
              <img class="logo" src="${COMPANY.logo}"/>
              <div class="company-name">Exotic Greens</div>
              <div class="company-sub">Fresh Exotic Vegetables</div>
              <div class="company-sub">${COMPANY.phone1} · ${COMPANY.phone2}</div>
            </div>
            <div class="doc-meta">
              <div class="doc-title">Statement</div>
              <div class="label">Period</div>
              <div class="val" style="font-size:12px;">${stFrom||"Start"} → ${stTo||"Today"}</div>
            </div>
          </div>

          <div class="billto">
            <div class="label">${p.type}</div>
            <div class="name">${p.name}</div>
          </div>

          <table>
            <thead><tr><th>Date</th><th>Description</th><th class="num">Debit</th><th class="num">Credit</th><th class="num">Balance</th></tr></thead>
            <tbody>
              ${stFrom?`<tr><td colspan="4" style="font-weight:600;">Opening balance</td><td class="num" style="font-weight:600;">${fmtMoney(Math.abs(periodOpeningBalance))} ${periodOpeningBalance>=0?"Dr":"Cr"}</td></tr>`:""}
              ${rows.map(e=>`<tr>
                <td class="mono" style="font-size:12px;">${e.date}</td>
                <td>${e.notes||(e.entry_type==="gave"?"Debit":"Credit")}</td>
                <td class="num">${e.entry_type==="gave"?fmtMoney(e.amount):""}</td>
                <td class="num">${e.entry_type==="got"?fmtMoney(e.amount):""}</td>
                <td class="num">${fmtMoney(Math.abs(e.running))} ${e.running>=0?"Dr":"Cr"}</td>
              </tr>`).join("")}
            </tbody>
          </table>

          <div class="totals">
            <div class="totals-box">
              <div class="grand">
                <span class="gl">Closing balance</span>
                <span class="gv">${fmtMoney(Math.abs(closing))}</span>
              </div>
              <div style="text-align:right;font-size:11px;color:#6B6F62;margin-top:4px;">${closing>=0?"they owe you":closing<0?"you owe them":"settled up"}</div>
            </div>
          </div>

          <div class="footer">
            <div>
              <div class="thanks">Thank you for your business.</div>
              <div class="thanks-sub">Exotic Greens — Fresh Exotic Vegetables</div>
            </div>
          </div>
        </div>
        <div class="printbar"><button onclick="window.print()">Print statement</button></div>
      </body></html>`);
      w.document.close();
      setTimeout(()=>w.print(),400);
    }

    function printDetailedStatement(){
      let running=periodOpeningBalance;
      const rows=inRange.map(e=>{
        running+=e.entry_type==="gave"?e.amount:-e.amount;
        return{...e,running};
      });
      const closing=rows.length?rows[rows.length-1].running:periodOpeningBalance;
      const w=window.open("","_blank");
      w.document.write(`<html><head><meta charset="UTF-8"><title>Detailed Statement — ${p.name}</title>
      <style>${PRINT_STYLES}
        .detail-row{background:#F8F6F0;border-left:3px solid #E1DACA;padding:6px 10px;margin-top:2px;font-size:11px;}
        .detail-item{display:flex;justify-content:space-between;padding:2px 0;color:#6B6F62;}
        .detail-item strong{color:#23261F;}
      </style></head><body>
        <div class="sheet">
          <div class="letterhead">
            <div>
              <img class="logo" src="${COMPANY.logo}"/>
              <div class="company-name">Exotic Greens</div>
              <div class="company-sub">Fresh Exotic Vegetables</div>
              <div class="company-sub">${COMPANY.phone1} · ${COMPANY.phone2}</div>
            </div>
            <div class="doc-meta">
              <div class="doc-title">Detailed Statement</div>
              <div class="label">Period</div>
              <div class="val" style="font-size:12px;">${stFrom||"Start"} → ${stTo||"Today"}</div>
            </div>
          </div>
          <div class="billto">
            <div class="label">${p.type}</div>
            <div class="name">${p.name}</div>
          </div>
          <table>
            <thead><tr><th>Date</th><th>Description</th><th class="num">Debit</th><th class="num">Credit</th><th class="num">Balance</th></tr></thead>
            <tbody>
              ${stFrom?`<tr><td colspan="4" style="font-weight:600;">Opening balance</td><td class="num" style="font-weight:600;">${fmtMoney(Math.abs(periodOpeningBalance))} ${periodOpeningBalance>=0?"Dr":"Cr"}</td></tr>`:""}
              ${rows.map(e=>{
                const linkedOrder=orders.find(o=>o.id===e.linked_order_id);
                const itemRows=linkedOrder&&e.entry_type==="gave"
                  ?mergeItemsForDisplay(linkedOrder.items||[]).map(it=>{
                      const qty=it.actual_qty??it.qty;
                      const rate=getEffectiveRate(it,inventory,p.name);
                      const amt=calcAmountDisplay(it,inventory,p.name);
                      return `<tr style="background:#F8F6F0;">
                        <td style="padding-left:20px;font-size:11px;color:#6B6F62;border-bottom:1px solid #E1DACA;">${it.name}</td>
                        <td style="font-size:11px;color:#6B6F62;border-bottom:1px solid #E1DACA;">${it.display_qty||fmtQty(qty)} ${it.unit} @ ${fmtMoney(rate)}/${inventory[it.name]?.unit||"kg"}</td>
                        <td class="num" style="font-size:11px;color:#6B6F62;border-bottom:1px solid #E1DACA;">${fmtMoney(amt)}</td>
                        <td style="border-bottom:1px solid #E1DACA;"></td>
                        <td style="border-bottom:1px solid #E1DACA;"></td>
                      </tr>`;
                    }).join("")
                  :"";
                return `<tr>
                  <td class="mono" style="font-size:12px;">${e.date}</td>
                  <td>${e.notes||(e.entry_type==="gave"?"Debit":"Credit")}</td>
                  <td class="num">${e.entry_type==="gave"?fmtMoney(e.amount):""}</td>
                  <td class="num">${e.entry_type==="got"?fmtMoney(e.amount):""}</td>
                  <td class="num">${fmtMoney(Math.abs(e.running))} ${e.running>=0?"Dr":"Cr"}</td>
                </tr>${itemRows}`;
              }).join("")}
            </tbody>
          </table>
          <div class="totals">
            <div class="totals-box">
              <div class="grand">
                <span class="gl">Closing balance</span>
                <span class="gv">${fmtMoney(Math.abs(closing))}</span>
              </div>
              <div style="text-align:right;font-size:11px;color:#6B6F62;margin-top:4px;">${closing>=0?"they owe you":closing<0?"you owe them":"settled up"}</div>
            </div>
          </div>
          <div class="footer">
            <div><div class="thanks">Thank you for your business.</div><div class="thanks-sub">Exotic Greens — Fresh Exotic Vegetables</div></div>
          </div>
        </div>
        <div class="printbar"><button onclick="window.print()">Print statement</button></div>
      </body></html>`);
      w.document.close();
      setTimeout(()=>w.print(),400);
    }

    function downloadStatementExcel(){
      let running=periodOpeningBalance;
      const rows=[];
      if(stFrom)rows.push({Date:"",Description:"Opening balance","Debit":"","Credit":"",Balance:fmtMoney(Math.abs(periodOpeningBalance))+(periodOpeningBalance>=0?" Dr":" Cr")});
      inRange.forEach(e=>{
        running+=e.entry_type==="gave"?e.amount:-e.amount;
        rows.push({
          Date:e.date,
          Description:e.notes||(e.entry_type==="gave"?"Debit":"Credit"),
          "Debit":e.entry_type==="gave"?e.amount:"",
          "Credit":e.entry_type==="got"?e.amount:"",
          Balance:fmtMoney(Math.abs(running))+(running>=0?" Dr":" Cr"),
        });
      });
      const ws=XLSX.utils.json_to_sheet(rows);
      ws["!cols"]=[{wch:12},{wch:28},{wch:12},{wch:12},{wch:16}];
      const wb=XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(wb,ws,"Statement");
      XLSX.writeFile(wb,`statement-${p.name.replace(/\s+/g,"-")}-${today()}.xlsx`);
    }

    return <div>
      <button onClick={()=>{window.history.back();}} style={{...BTN(),border:`1px solid ${T.line}`,background:"transparent",color:T.inkMuted,marginBottom:16,padding:"7px 14px",fontSize:12}}>← All parties</button>
      <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start",marginBottom:20,flexWrap:"wrap",gap:12}}>
        <div>
          <div style={{fontFamily:FD,fontWeight:700,fontSize:24,color:T.ink}}>{p.name}</div>
          <div style={{fontSize:11,color:T.inkMuted,fontFamily:FM,textTransform:"uppercase",letterSpacing:"0.04em",marginTop:3}}>{p.type}</div>
        </div>
        <div style={{textAlign:"right"}}>
          <div style={{fontSize:28,fontWeight:700,fontFamily:FM,color:totalBalance>0?T.moss:totalBalance<0?T.clay:T.inkMuted}}>{fmtMoney(Math.abs(totalBalance))}</div>
          <div style={{fontSize:11,color:T.inkMuted}}>{totalBalance>0?"they owe you":totalBalance<0?"you owe them":"settled up"}</div>
        </div>
      </div>
      <div style={{display:"flex",gap:8,marginBottom:16,flexWrap:"wrap"}}>
        <button onClick={()=>openEntryForm(p.name,p.type,"got")} style={{...BTN(),flex:2,background:T.moss,color:T.paperWhite,fontSize:13,fontWeight:700}}>
          💵 Record Payment received
        </button>
        <button onClick={()=>openEntryForm(p.name,p.type,"gave")} style={{...BTN(),flex:1,border:`1px solid ${T.line}`,background:"transparent",color:T.ink,fontSize:12}}>
          + Add sale / charge
        </button>
        <button onClick={()=>openEntryForm(p.name,p.type,"got")} style={{...BTN(),flex:1,border:`1px solid ${T.line}`,background:"transparent",color:T.ink,fontSize:12}}>
          + Other credit
        </button>
      </div>

      {/* Opening balance card */}
      <div style={{background:openingEntry?"#FBF6E9":T.paperWhite,border:`1px solid ${openingEntry?T.gold:T.line}`,borderRadius:3,padding:"14px 16px",marginBottom:16}}>
        <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",flexWrap:"wrap",gap:10}}>
          <div>
            <div style={{fontSize:12,fontWeight:700,color:T.ink}}>Opening Balance</div>
            {openingEntry
              ?<div style={{fontSize:13,color:openingAmt>=0?T.moss:T.clay,fontFamily:FM,fontWeight:700,marginTop:2}}>{fmtMoney(Math.abs(openingAmt))} {openingAmt>=0?"(they owed you)":"(you owed them)"}</div>
              :<div style={{fontSize:12,color:T.inkMuted,marginTop:2}}>Not set — balance from before you started using the app</div>
            }
          </div>
          <div style={{display:"flex",gap:8}}>
            <button onClick={()=>{setObAmount(openingEntry?String(openingEntry.amount):"");setObType(openingEntry?openingEntry.entry_type:"gave");setShowObForm(v=>!v);}} style={{...BTN(),padding:"7px 14px",border:`1px solid ${T.line}`,background:"transparent",color:T.ink,fontSize:12}}>
              {openingEntry?"Edit":"Set opening balance"}
            </button>
            {openingEntry&&<button onClick={deleteOpeningBalance} style={{...BTN(),padding:"7px 14px",border:`1px solid ${T.clay}`,background:"transparent",color:T.clay,fontSize:12}}>Clear</button>}
          </div>
        </div>
        {showObForm&&<div style={{marginTop:14,paddingTop:14,borderTop:`1px solid ${T.line}`}}>
          <div style={{display:"flex",gap:10,flexWrap:"wrap",alignItems:"flex-end"}}>
            <div style={{flex:1,minWidth:120}}>
              <label style={IL}>They owed / You owed</label>
              <select value={obType} onChange={e=>setObType(e.target.value)} style={II}>
                <option value="gave">They owed you (opening balance)</option>
                <option value="got">You owed them (opening balance)</option>
              </select>
            </div>
            <div style={{flex:1,minWidth:100}}>
              <label style={IL}>Amount (₹)</label>
              <input type="number" value={obAmount} onChange={e=>setObAmount(e.target.value)} placeholder="0" style={II} autoFocus/>
            </div>
            <div style={{display:"flex",gap:8}}>
              <button onClick={()=>setShowObForm(false)} style={{...BTN(),border:`1px solid ${T.line}`,background:"transparent",color:T.ink}}>Cancel</button>
              <button onClick={saveOpeningBalance} disabled={obSaving||!obAmount} style={{...BTN(),background:T.moss,color:T.paperWhite}}>
                {obSaving?"Saving…":"Save"}
              </button>
            </div>
          </div>
        </div>}
      </div>

      <div style={{background:T.paperWhite,border:`1px solid ${T.line}`,borderRadius:3,padding:16,marginBottom:18}}>
        <div style={{fontFamily:FD,fontWeight:600,fontSize:14,color:T.ink,marginBottom:10}}>Statement</div>
        <div style={{display:"flex",gap:10,flexWrap:"wrap",alignItems:"flex-end"}}>
          <div>
            <label style={IL}>From (optional)</label>
            <input type="date" value={stFrom} onChange={e=>setStFrom(e.target.value)} style={{...II,width:"auto"}}/>
          </div>
          <div>
            <label style={IL}>To (optional)</label>
            <input type="date" value={stTo} onChange={e=>setStTo(e.target.value)} style={{...II,width:"auto"}}/>
          </div>
          <label style={{display:"flex",alignItems:"center",gap:6,fontSize:12,color:T.ink,cursor:"pointer",paddingBottom:2}}>
            <input type="checkbox" checked={detailedSt} onChange={e=>setDetailedSt(e.target.checked)}/>
            Detailed (show items)
          </label>
          <button onClick={()=>detailedSt?printDetailedStatement():printStatement()} style={{...BTN(),background:T.moss,color:T.paperWhite}}>Print / PDF</button>
          <button onClick={downloadStatementExcel} style={{...BTN(),border:`1px solid ${T.line}`,background:"transparent",color:T.ink}}>Excel</button>
          {(stFrom||stTo)&&<button onClick={()=>{setStFrom("");setStTo("");}} style={{...BTN(),border:"none",background:"transparent",color:T.inkMuted,fontSize:12}}>Clear dates</button>}
        </div>
      </div>

      <div style={{background:T.paperWhite,border:`1px solid ${T.line}`,borderRadius:3}}>
        {sortedEntries.length===0
          ?<div style={{padding:30,textAlign:"center",color:T.inkMuted,fontStyle:"italic",fontFamily:FD}}>No entries yet</div>
          :sortedEntries.map(e=>{
            const isLinked=!!(e.linked_order_id||e.linked_purchase_id);
            const linkedOrder=e.linked_order_id?(orders||[]).find(o=>o.id===e.linked_order_id):null;
            const expanded=expandedEntryId===e.id;
            return <div key={e.id} style={{borderBottom:`1px solid ${T.line}`}}>
              <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",padding:"12px 16px",gap:10,flexWrap:"wrap"}}>
                <div style={{flex:1,minWidth:0,cursor:linkedOrder?"pointer":"default"}} onClick={()=>linkedOrder&&setExpandedEntryId(v=>v===e.id?null:e.id)}>
                  <div style={{fontSize:14,color:T.ink,fontWeight:600}}>{e.notes||(e.entry_type==="gave"?"Debit":"Credit")}
                    {linkedOrder&&<span style={{marginLeft:6,fontSize:11,color:T.moss}}>{expanded?"▾":"▸"} View order</span>}
                  </div>
                  <div style={{fontSize:11,color:T.inkMuted,fontFamily:FM,marginTop:2}}>{e.date}{isLinked&&<span style={{marginLeft:6,fontSize:9,color:T.gold,fontFamily:FM,textTransform:"uppercase",letterSpacing:"0.04em"}}>auto</span>}</div>
                </div>
                <div style={{display:"flex",alignItems:"center",gap:8}}>
                  <span style={{fontFamily:FM,fontWeight:700,fontSize:15,color:e.entry_type==="gave"?T.moss:T.clay}}>
                    {e.entry_type==="gave"?"+":"−"}{fmtMoney(linkedOrder&&e.entry_type==="gave"?orderTotal(linkedOrder,inventory||{}):e.amount)}
                    {linkedOrder&&e.entry_type==="gave"&&Math.abs(orderTotal(linkedOrder,inventory||{})-e.amount)>0.5&&
                      <span style={{fontSize:9,color:T.clay,marginLeft:4}} title={`Ledger stored: ${fmtMoney(e.amount)}`}>↻</span>
                    }
                  </span>
                  <button
                    title={e.marked_paid?"Mark as unpaid":"Mark as paid"}
                    onClick={async()=>{
                      await supabase.from("ledger_entries").update({marked_paid:!e.marked_paid}).eq("id",e.id);
                      onEditEntry();
                    }}
                    style={{background:e.marked_paid?"#2D6A4F":"none",border:`1px solid ${e.marked_paid?"#2D6A4F":T.line}`,cursor:"pointer",color:e.marked_paid?"#fff":T.inkMuted,fontSize:12,padding:"3px 8px",borderRadius:2,fontWeight:700}}>
                    {e.marked_paid?"✓ Paid":"✓"}
                  </button>
                  <button onClick={()=>openEdit(e)} style={{background:"none",border:`1px solid ${T.line}`,cursor:"pointer",color:T.ink,fontSize:11,padding:"3px 8px",borderRadius:2}}>Edit</button>
                  <button onClick={()=>{
                    const msg=isLinked
                      ?`Delete this auto-recorded entry for Order ${e.linked_order_id}? The order itself won't be deleted but this entry will be removed from the ledger.`
                      :"Delete this ledger entry? This will affect the account balance.";
                    if(window.confirm(msg))onDeleteEntry(e.id);
                  }} style={{background:"none",border:"none",cursor:"pointer",color:T.inkMuted,fontSize:13}}>✕</button>
                </div>
              </div>
              {expanded&&linkedOrder&&<div style={{background:T.paper,padding:"12px 16px",borderTop:`1px solid ${T.line}`}}>
                <div style={{fontSize:12,fontWeight:700,color:T.ink,marginBottom:8}}>Order {linkedOrder.id} · {linkedOrder.order_date} · {linkedOrder.status}</div>
                {(mergeItemsForDisplay(linkedOrder.items||[])).map((it,i)=>{
                  const effectiveRate=getEffectiveRate(it,inventory||{},linkedOrder.customer);
                  const amt=calcAmountDisplay(it,inventory||{},linkedOrder.customer);
                  return <div key={i} style={{display:"flex",justifyContent:"space-between",fontSize:12,padding:"4px 0",borderBottom:`1px solid ${T.line}`,color:T.ink,gap:8}}>
                    <span style={{flex:2}}>{it.name}</span>
                    <span style={{fontFamily:FM,color:T.inkMuted}}>{it.display_qty||fmtQty(it.actual_qty??it.qty)} {it.unit}</span>
                    <span style={{fontFamily:FM,color:T.inkMuted}}>@{fmtMoney(effectiveRate)}</span>
                    <span style={{fontFamily:FM,fontWeight:600}}>{fmtMoney(amt)}</span>
                  </div>;
                })}
                <div style={{display:"flex",justifyContent:"space-between",fontSize:12,fontWeight:700,padding:"6px 0 2px",color:T.ink,borderTop:`1px solid ${T.line}`,marginTop:4}}>
                  <span>Total (ledger recorded)</span>
                  <span style={{fontFamily:FM,color:e.amount!==orderTotal(linkedOrder,inventory||{})?T.clay:T.moss}}>{fmtMoney(e.amount)}</span>
                </div>
                {e.amount!==orderTotal(linkedOrder,inventory||{})&&<div style={{fontSize:10,color:T.clay,textAlign:"right"}}>⚠ Ledger amount differs from current calculation — rates may have changed since delivery</div>}
                {linkedOrder.notes&&<div style={{fontSize:11,color:T.inkMuted,marginTop:6,fontStyle:"italic"}}>Note: {linkedOrder.notes}</div>}
                <div style={{marginTop:10,display:"flex",justifyContent:"flex-end"}}>
                  <button onClick={async()=>{
                    if(!window.confirm(`Delete order ${linkedOrder.id} for ${linkedOrder.customer}? This will also remove this ledger entry.`))return;
                    onDeleteOrder&&await onDeleteOrder(linkedOrder.id);
                  }} style={{...BTN(),background:"transparent",border:`1px solid ${T.clay}`,color:T.clay,fontSize:12,padding:"6px 14px"}}>
                    Delete this order
                  </button>
                </div>
              </div>}
            </div>;
          })
        }
      </div>

      {/* Edit entry modal */}
      {editEntry&&<Modal onClose={()=>setEditEntry(null)} width={420}>
        <ModalHeader title="Edit entry" sub={editEntry.party_name} onClose={()=>setEditEntry(null)}/>
        <div style={{padding:20}}>
          {(editEntry.linked_order_id||editEntry.linked_purchase_id)&&
            <div style={{background:"#F3E6CC",color:"#5C4A1F",padding:"9px 12px",borderRadius:2,marginBottom:14,fontSize:12,borderLeft:`3px solid ${T.gold}`}}>
              This entry was auto-created from an {editEntry.linked_order_id?"order":"purchase"}. Editing it here won't change the original — it only adjusts the ledger balance.
            </div>
          }
          <div style={{marginBottom:12}}>
            <label style={IL}>Entry type</label>
            <select value={editForm.entry_type} onChange={e=>setEditForm(f=>({...f,entry_type:e.target.value}))} style={II}>
              <option value="gave">Sale / charge (they owe you more)</option>
              <option value="got">Payment / credit (reduces balance)</option>
            </select>
          </div>
          <div style={{marginBottom:12}}>
            <label style={IL}>Amount (₹)</label>
            <input type="number" value={editForm.amount} onChange={e=>setEditForm(f=>({...f,amount:e.target.value}))} style={II} autoFocus/>
          </div>
          <div style={{marginBottom:12}}>
            <label style={IL}>Date</label>
            <input type="date" value={editForm.date} onChange={e=>setEditForm(f=>({...f,date:e.target.value}))} style={II}/>
          </div>
          <div style={{marginBottom:16}}>
            <label style={IL}>Description</label>
            <input value={editForm.notes} onChange={e=>setEditForm(f=>({...f,notes:e.target.value}))} placeholder="e.g. Cash payment" style={II}/>
          </div>
          <div style={{display:"flex",gap:10}}>
            <button onClick={()=>setEditEntry(null)} style={{...BTN(),border:`1px solid ${T.line}`,background:"transparent",color:T.ink}}>Cancel</button>
            <button onClick={saveEdit} disabled={editSaving||!editForm.amount} style={{...BTN(),flex:1,background:T.moss,color:T.paperWhite,padding:"12px 0"}}>
              {editSaving?"Saving…":"Save changes"}
            </button>
          </div>
        </div>
      </Modal>}
      {showAddEntry&&<Modal onClose={()=>setShowAddEntry(false)} width={420}>
        <ModalHeader title={entryForm.entry_type==="gave"?"Add sale / charge":"Record payment received"} sub={entryForm.party_name} onClose={()=>setShowAddEntry(false)}/>
        <div style={{padding:20}}>
          <div style={{marginBottom:12}}>
            <label style={IL}>Amount (₹)</label>
            <input type="number" value={entryForm.amount} onChange={e=>setEntryForm(f=>({...f,amount:e.target.value}))} style={II} autoFocus/>
          </div>
          <div style={{marginBottom:12}}>
            <label style={IL}>Date</label>
            <input type="date" value={entryForm.date} onChange={e=>setEntryForm(f=>({...f,date:e.target.value}))} style={II}/>
          </div>
          <div style={{marginBottom:16}}>
            <label style={IL}>Note (optional)</label>
            <input value={entryForm.notes} onChange={e=>setEntryForm(f=>({...f,notes:e.target.value}))} placeholder="e.g. Cash payment" style={II}/>
          </div>
          <button onClick={submitEntry} disabled={saving||!entryForm.amount} style={{...BTN(),width:"100%",background:entryForm.entry_type==="gave"?T.moss:T.clay,color:T.paperWhite,padding:"12px 0"}}>
            {saving?"Saving…":"Save entry"}
          </button>
        </div>
      </Modal>}
    </div>;
  }

  if(view==="summary"){
    const todayStr=today();
    // Fix week: Monday-based week, not Sunday
    const startOfWeek=(()=>{
      const d=new Date();
      const day=d.getDay()||7; // Sun=7
      d.setDate(d.getDate()-(day-1));
      return d.toISOString().split("T")[0];
    })();
    const startOfMonth=todayStr.slice(0,7)+"-01";

    // Only customer entries for Sales/Revenue/Pending
    function salesMetrics(fromDate){
      const inRange=ledgerEntries.filter(e=>e.party_type==="customer"&&(e.date||"")>=fromDate&&(e.date||"")<=todayStr);
      const sales=inRange.filter(e=>e.entry_type==="gave").reduce((s,e)=>s+e.amount,0);
      const collected=inRange.filter(e=>e.entry_type==="got").reduce((s,e)=>s+e.amount,0);
      return{sales,collected,pending:sales-collected};
    }

    const dayM=salesMetrics(todayStr);
    const weekM=salesMetrics(startOfWeek);
    const monthM=salesMetrics(startOfMonth);

    // Total outstanding across all time
    const allCustomerParties=parties.filter(p=>p.type==="customer");
    const totalPending=allCustomerParties.filter(p=>p.balance>0).reduce((s,p)=>s+p.balance,0);
    const totalOverpaid=allCustomerParties.filter(p=>p.balance<0).reduce((s,p)=>s+Math.abs(p.balance),0);

    return <div>
      <div style={{display:"flex",gap:1,marginBottom:24,background:T.line,borderRadius:3,overflow:"hidden",width:"fit-content"}}>
        {[["sales","💰 Sales"],["purchases_tab","🛒 Purchases"],["summary","Summary"]].map(([id,label])=>(
          <button key={id} onClick={()=>setView(id)} style={{padding:"8px 16px",border:"none",background:view===id?T.moss:T.paperWhite,color:view===id?T.paperWhite:T.inkMuted,cursor:"pointer",fontSize:12,fontWeight:600,fontFamily:FB}}>{label}</button>
        ))}
      </div>

      {/* Total outstanding banner */}
      <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:1,marginBottom:24,background:T.line,borderRadius:3,overflow:"hidden"}}>
        <div style={{background:T.paperWhite,padding:"18px 22px"}}>
          <div style={{fontSize:10,color:T.inkMuted,fontFamily:FM,textTransform:"uppercase",letterSpacing:"0.05em",marginBottom:6,fontWeight:600}}>Total pending payments</div>
          <div style={{fontSize:30,fontWeight:700,color:T.moss,fontFamily:FD}}>{fmtMoney(totalPending)}</div>
          <div style={{fontSize:11,color:T.inkMuted,marginTop:4}}>customers owe you (all time)</div>
        </div>
        <div style={{background:T.paperWhite,padding:"18px 22px"}}>
          <div style={{fontSize:10,color:T.inkMuted,fontFamily:FM,textTransform:"uppercase",letterSpacing:"0.05em",marginBottom:6,fontWeight:600}}>Advance / overpaid</div>
          <div style={{fontSize:30,fontWeight:700,color:T.clay,fontFamily:FD}}>{fmtMoney(totalOverpaid)}</div>
          <div style={{fontSize:11,color:T.inkMuted,marginTop:4}}>you owe customers (credits)</div>
        </div>
      </div>

      {/* Period breakdown */}
      <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(220px,1fr))",gap:16}}>
        {[["Today",dayM,todayStr,todayStr],["This week",weekM,startOfWeek,todayStr],["This month",monthM,startOfMonth,todayStr]].map(([label,m,from,to])=>(
          <div key={label} style={{background:T.paperWhite,border:`1px solid ${T.line}`,borderRadius:3,padding:18}}>
            <div style={{fontFamily:FD,fontWeight:700,fontSize:15,color:T.ink,marginBottom:4}}>{label}</div>
            <div style={{fontSize:10,color:T.inkMuted,fontFamily:FM,marginBottom:14,letterSpacing:"0.03em"}}>{from===to?from:`${from} → ${to}`}</div>
            <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:10}}>
              <span style={{fontSize:12,color:T.inkMuted}}>Sales billed</span>
              <span style={{fontFamily:FM,color:T.ink,fontWeight:600,fontSize:14}}>{fmtMoney(m.sales)}</span>
            </div>
            <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:10}}>
              <span style={{fontSize:12,color:T.inkMuted}}>Collected</span>
              <span style={{fontFamily:FM,color:T.moss,fontWeight:600,fontSize:14}}>{fmtMoney(m.collected)}</span>
            </div>
            <div style={{borderTop:`1px solid ${T.line}`,paddingTop:10,display:"flex",justifyContent:"space-between",alignItems:"center"}}>
              <span style={{fontSize:11,color:T.inkMuted,fontFamily:FM,textTransform:"uppercase",letterSpacing:"0.04em",fontWeight:700}}>Pending</span>
              <span style={{fontFamily:FM,fontWeight:700,fontSize:16,color:m.pending>0?T.clay:T.moss}}>
                {m.pending>0?fmtMoney(m.pending):"✓ All collected"}
              </span>
            </div>
          </div>
        ))}
      </div>
    </div>;
  }

  return <div>
    <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:18,flexWrap:"wrap",gap:10}}>
      <div style={{display:"flex",gap:1,background:T.line,borderRadius:3,overflow:"hidden"}}>
        {[["sales","💰 Sales"],["purchases_tab","🛒 Purchases"],["summary","Summary"]].map(([id,label])=>(
          <button key={id} onClick={()=>setView(id)} style={{padding:"8px 16px",border:"none",background:view===id?T.moss:T.paperWhite,color:view===id?T.paperWhite:T.inkMuted,cursor:"pointer",fontSize:12,fontWeight:600,fontFamily:FB}}>{label}</button>
        ))}
      </div>
      <button onClick={()=>openEntryForm("","customer","gave")} style={{...BTN(),background:T.moss,color:T.paperWhite}}>+ Add entry</button>
    </div>

    {/* Summary cards */}
    <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(200px,1fr))",gap:1,marginBottom:24,background:T.line,borderRadius:3,overflow:"hidden"}}>
      <div style={{background:T.paperWhite,padding:"16px 20px"}}>
        <div style={{fontSize:10,color:T.inkMuted,fontFamily:FM,textTransform:"uppercase",letterSpacing:"0.05em",marginBottom:6}}>Customers owe you</div>
        <div style={{fontSize:26,fontWeight:600,color:T.moss,fontFamily:FD}}>{fmtMoney(totalReceivable)}</div>
      </div>
      <div style={{background:T.paperWhite,padding:"16px 20px"}}>
        <div style={{fontSize:10,color:T.inkMuted,fontFamily:FM,textTransform:"uppercase",letterSpacing:"0.05em",marginBottom:6}}>You owe suppliers</div>
        <div style={{fontSize:26,fontWeight:600,color:T.clay,fontFamily:FD}}>{fmtMoney(totalPayable)}</div>
      </div>
    </div>

    {/* Party list — filtered by Sales/Purchases tab */}
    {(view==="sales"||view==="purchases_tab")&&<>
      {parties.filter(p=>view==="sales"?p.type==="customer":p.type==="supplier").length===0
        ?<div style={{textAlign:"center",padding:40,color:T.inkMuted,fontFamily:FD,fontStyle:"italic",fontSize:14}}>
          No {view==="sales"?"customer":"supplier"} entries yet.
        </div>
        :<>
          <input placeholder={`🔍 Search ${view==="sales"?"customers":"suppliers"}…`} style={{...II,marginBottom:12}} value={partySearch||""} onChange={e=>setPartySearch(e.target.value)}/>
          {view==="purchases_tab"
            ?<div style={{display:"grid",gap:8}}>
              {parties.filter(p=>p.type==="supplier").filter(p=>!partySearch||(p.name||"").toLowerCase().includes((partySearch||"").toLowerCase())).map(p=>(
                <PartyCard key={p.name} p={p} onSelect={name=>{window.history.pushState({tab:"accounts",party:name},"",`#accounts-${name.replace(/\s+/g,"-")}`);setSelectedParty(name);}}/>
              ))}
            </div>
            :<>
              {/* Regular customers — in saved_customers */}
              {(()=>{
                const savedNames=new Set((savedCustomers||[]).map(c=>c.name));
                const regular=parties.filter(p=>p.type==="customer"&&savedNames.has(p.name)).filter(p=>!partySearch||(p.name||"").toLowerCase().includes((partySearch||"").toLowerCase()));
                const daily=parties.filter(p=>p.type==="customer"&&!savedNames.has(p.name)).filter(p=>!partySearch||(p.name||"").toLowerCase().includes((partySearch||"").toLowerCase()));
                return <>
                  {regular.length>0&&<>
                    <div style={{fontSize:11,fontFamily:FM,fontWeight:700,color:T.inkMuted,textTransform:"uppercase",letterSpacing:"0.06em",marginBottom:8}}>Regular customers ({regular.length})</div>
                    <div style={{display:"grid",gap:8,marginBottom:20}}>
                      {regular.map(p=><PartyCard key={p.name} p={p} onSelect={name=>{window.history.pushState({tab:"accounts",party:name},"",`#accounts-${name.replace(/\s+/g,"-")}`);setSelectedParty(name);}}/>)}
                    </div>
                  </>}
                  {daily.length>0&&<>
                    <div style={{fontSize:11,fontFamily:FM,fontWeight:700,color:T.gold,textTransform:"uppercase",letterSpacing:"0.06em",marginBottom:8}}>💵 Daily / Walk-in ({daily.length})</div>
                    <div style={{display:"grid",gap:8}}>
                      {daily.map(p=><PartyCard key={p.name} p={p}
                        onSelect={name=>{window.history.pushState({tab:"accounts",party:name},"",`#accounts-${name.replace(/\s+/g,"-")}`);setSelectedParty(name);}}
                        onSaveAsRegular={async name=>{
                          if(!window.confirm(`Save "${name}" as a regular customer?\n\nThis will also move all their previous cash/walk-in orders to the Regular section.`))return;
                          onSaveCustomer&&onSaveCustomer({name,business:"",phone:"",delivery_location:""});
                          await supabase.from("orders").update({is_cash:false}).eq("customer",name).eq("is_cash",true);
                          const{data:cashOrders}=await supabase.from("orders").select("id").eq("customer",name);
                          if(cashOrders?.length){
                            const ids=cashOrders.map(o=>o.id);
                            await supabase.from("ledger_entries").delete().in("linked_order_id",ids).eq("entry_type","got").ilike("notes","Cash payment%");
                          }
                        }}
                      />)}
                    </div>
                  </>}
                </>;
              })()}
            </>
          }
        </>
      }
    </>}

    {showAddEntry&&<Modal onClose={()=>setShowAddEntry(false)} width={420}>
      <ModalHeader title="Add ledger entry" onClose={()=>setShowAddEntry(false)}/>
      <div style={{padding:20}}>
        <div style={{marginBottom:12}}>
          <label style={IL}>Party name</label>
          <input list="party-options" value={entryForm.party_name} onChange={e=>setEntryForm(f=>({...f,party_name:e.target.value}))} placeholder="Type or select a name" style={II}/>
          <datalist id="party-options">{knownPartyNames.map(n=><option key={n} value={n}/>)}</datalist>
        </div>
        <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:10,marginBottom:12}}>
          <div>
            <label style={IL}>Type</label>
            <select value={entryForm.party_type} onChange={e=>setEntryForm(f=>({...f,party_type:e.target.value}))} style={II}>
              <option value="customer">Customer</option>
              <option value="supplier">Supplier</option>
              <option value="other">Other</option>
            </select>
          </div>
          <div>
            <label style={IL}>Entry</label>
            <select value={entryForm.entry_type} onChange={e=>setEntryForm(f=>({...f,entry_type:e.target.value}))} style={II}>
              <option value="gave">Sale / charge (they owe you more)</option>
              <option value="got">Payment / credit (reduces balance)</option>
            </select>
          </div>
        </div>
        <div style={{marginBottom:12}}>
          <label style={IL}>Amount (₹)</label>
          <input type="number" value={entryForm.amount} onChange={e=>setEntryForm(f=>({...f,amount:e.target.value}))} style={II}/>
        </div>
        <div style={{marginBottom:12}}>
          <label style={IL}>Date</label>
          <input type="date" value={entryForm.date} onChange={e=>setEntryForm(f=>({...f,date:e.target.value}))} style={II}/>
        </div>
        <div style={{marginBottom:16}}>
          <label style={IL}>Note (optional)</label>
          <input value={entryForm.notes} onChange={e=>setEntryForm(f=>({...f,notes:e.target.value}))} placeholder="e.g. Cash payment" style={II}/>
        </div>
        <button onClick={submitEntry} disabled={saving||!entryForm.party_name.trim()||!entryForm.amount} style={{...BTN(),width:"100%",background:T.moss,color:T.paperWhite,padding:"12px 0"}}>
          {saving?"Saving…":"Save entry"}
        </button>
      </div>
    </Modal>}
  </div>;
}

// ─── RENAME CUSTOMER ─────────────────────────────────────────────────────────
function RenameCustomer({savedCustomers,onRenamed}){
  const [oldName,setOldName]=useState("");
  const [newName,setNewName]=useState("");
  const [saving,setSaving]=useState(false);
  const [result,setResult]=useState(null);

  async function doRename(){
    if(!oldName.trim()||!newName.trim()||oldName===newName)return;
    if(!window.confirm(`Rename "${oldName}" to "${newName}" everywhere? This cannot be undone.`))return;
    setSaving(true);setResult(null);
    try{
      // Update all three tables in parallel
      const[r1,r2,r3]=await Promise.all([
        supabase.from("saved_customers").update({name:newName}).eq("name",oldName),
        supabase.from("orders").update({customer:newName}).eq("customer",oldName),
        supabase.from("ledger_entries").update({party_name:newName}).eq("party_name",oldName),
      ]);
      const errors=[r1.error,r2.error,r3.error].filter(Boolean);
      if(errors.length){
        setResult({ok:false,msg:"Partial failure: "+errors.map(e=>e.message).join(", ")});
      } else {
        setResult({ok:true,msg:`Done — renamed across saved customers, orders, and ledger.`});
        setOldName("");setNewName("");
        onRenamed&&onRenamed();
      }
    }catch(e){
      setResult({ok:false,msg:e.message});
    }
    setSaving(false);
  }

  const names=[...new Set((savedCustomers||[]).map(c=>c.name))].sort();

  return <div>
    <div style={{display:"grid",gridTemplateColumns:"1fr 1fr auto",gap:10,alignItems:"flex-end"}}>
      <div>
        <label style={IL}>Current name</label>
        <SearchSelect options={names} value={oldName} onChange={setOldName} placeholder="— select customer —"/>
      </div>
      <div>
        <label style={IL}>New name</label>
        <input value={newName} onChange={e=>setNewName(e.target.value)} placeholder="New name" style={II}/>
      </div>
      <button onClick={doRename} disabled={saving||!oldName||!newName||oldName===newName}
        style={{...BTN(),background:T.moss,color:T.paperWhite,whiteSpace:"nowrap"}}>
        {saving?"Renaming…":"Rename"}
      </button>
    </div>
    {result&&<div style={{marginTop:10,padding:"9px 12px",borderRadius:2,fontSize:12,
      background:result.ok?"#E3E9DE":"#F3E3DC",
      color:result.ok?T.moss:T.clay,
      borderLeft:`3px solid ${result.ok?T.moss:T.clay}`}}>
      {result.ok?"✅ ":""}{result.msg}
    </div>}
  </div>;
}

function AdminPanel({logo,onLogoChange,savedCustomers,onSaveCustomer,onDeleteCustomer,orders,inventory,ledgerEntries,onSyncLedger,onRenameCustomer,user}){
  const [email,setEmail]=useState("");
  const [password,setPassword]=useState("");
  const [name,setName]=useState("");
  const [role,setRole]=useState("staff");
  const [loading,setLoading]=useState(false);
  const [msg,setMsg]=useState("");
  const [newCust,setNewCust]=useState({name:"",business:"",phone:"",delivery_location:""});
  const fileRef=useRef();
  const [accounts,setAccounts]=useState([]);
  const [accountsLoading,setAccountsLoading]=useState(true);
  const [currentUserId,setCurrentUserId]=useState(null);
  const [syncing,setSyncing]=useState(false);
  const [syncResult,setSyncResult]=useState(null);
  const [activity,setActivity]=useState([]);
  const [activityLoading,setActivityLoading]=useState(true);

  useEffect(()=>{ fetchAccounts(); },[]);

  function fetchActivity(){
    return supabase.from("activity_log").select("*").order("created_at",{ascending:false}).limit(100)
      .then(({data,error})=>{ if(!error)setActivity(data||[]); setActivityLoading(false); });
  }
  useEffect(()=>{ fetchActivity(); },[]);

  // Realtime — new activity from other devices shows up here without a refresh
  useEffect(()=>{
    let timer;
    const ch=supabase.channel("activity-rt")
      .on("postgres_changes",{event:"*",schema:"public",table:"activity_log"},()=>{clearTimeout(timer);timer=setTimeout(fetchActivity,400);})
      .subscribe();
    return()=>{clearTimeout(timer);supabase.removeChannel(ch);};
  },[]);

  // Realtime — so a staff account added/removed on one device shows up for everyone else without a refresh
  useEffect(()=>{
    let timer;
    const ch=supabase.channel("profiles-rt")
      .on("postgres_changes",{event:"*",schema:"public",table:"profiles"},()=>{clearTimeout(timer);timer=setTimeout(fetchAccounts,400);})
      .subscribe();
    return()=>{clearTimeout(timer);supabase.removeChannel(ch);};
  },[]);

  async function fetchAccounts(){
    setAccountsLoading(true);
    const{data:sessionData}=await supabase.auth.getSession();
    setCurrentUserId(sessionData?.session?.user?.id||null);
    const{data,error}=await supabase.from("profiles").select("*").order("name");
    if(error){setMsg("Error: couldn't load accounts — "+error.message);setAccountsLoading(false);return;}
    setAccounts(data||[]);
    setAccountsLoading(false);
  }

  async function deleteAccount(userId,accountName){
    if(!window.confirm(`Remove ${accountName}'s account? They will no longer be able to sign in.`))return;
    const{data:sessionData}=await supabase.auth.getSession();
    const adminAccessToken=sessionData?.session?.access_token;
    try{
      const r=await fetch("/api/delete-staff",{
        method:"POST",
        headers:{"Content-Type":"application/json"},
        body:JSON.stringify({adminAccessToken,userId}),
      });
      const d=await r.json();
      if(!r.ok){alert("Error: "+(d.error||"could not delete account"));return;}
      setAccounts(prev=>prev.filter(a=>a.id!==userId));
      logActivity(user,"Staff account removed",accountName);
    }catch(e){
      alert("Error: "+e.message);
    }
  }

  async function createUser(){
    setLoading(true);setMsg("");
    const{data:sessionData}=await supabase.auth.getSession();
    const adminAccessToken=sessionData?.session?.access_token;
    if(!adminAccessToken){setMsg("Error: your session expired, please log out and back in.");setLoading(false);return;}
    try{
      const r=await fetch("/api/create-staff",{
        method:"POST",
        headers:{"Content-Type":"application/json"},
        body:JSON.stringify({adminAccessToken,name,email,password,role}),
      });
      const d=await r.json();
      if(!r.ok){setMsg("Error: "+(d.error||"could not create account"));setLoading(false);return;}
      setMsg(`✅ Account created for ${email}. They can now sign in.`);
      logActivity(user,"Staff account created",`${name} (${email}) — ${role}`);
      setEmail("");setPassword("");setName("");
      fetchAccounts();
    }catch(e){
      setMsg("Error: "+e.message);
    }
    setLoading(false);
  }

  function handleLogo(e){
    const file=e.target.files[0];
    if(!file)return;
    resizeImageToDataURL(file,400,0.85).then(async(base64)=>{
      COMPANY.logo=base64;
      onLogoChange(base64);
      await supabase.from("company_settings").upsert([{id:"main",logo_base64:base64}]);
    });
  }

  function addCustomer(){
    if(!newCust.name.trim())return;
    onSaveCustomer(newCust);
    setNewCust({name:"",business:"",phone:"",delivery_location:""});
  }

  return <div style={{maxWidth:560,display:"grid",gap:24}}>
    {/* Branding */}
    <div style={{background:T.paperWhite,border:`1px solid ${T.line}`,borderRadius:3,padding:20}}>
      <div style={{fontFamily:FD,fontWeight:600,fontSize:16,marginBottom:14,color:T.ink}}>Company branding</div>
      <div style={{display:"flex",alignItems:"center",gap:16,marginBottom:16,flexWrap:"wrap"}}>
        <div style={{width:72,height:72,borderRadius:3,border:`2px dashed ${T.line}`,display:"flex",alignItems:"center",justifyContent:"center",overflow:"hidden",background:T.paper}}>
          {logo?<img src={logo} alt="logo" style={{width:"100%",height:"100%",objectFit:"contain"}}/>
            :<span style={{fontFamily:FD,fontWeight:700,fontSize:22,color:T.moss}}>EG</span>}
        </div>
        <div>
          <button onClick={()=>fileRef.current?.click()} style={{...BTN(),background:T.moss,color:T.paperWhite,marginBottom:6}}>Upload logo</button>
          <input ref={fileRef} type="file" accept="image/*" onChange={handleLogo} style={{display:"none"}}/>
          <div style={{fontSize:12,color:T.inkMuted}}>This logo will appear on all printed bills</div>
        </div>
      </div>
      <div style={{fontSize:13,color:T.ink,fontFamily:FM}}>
        <div><b>Company:</b> Exotic Greens</div>
        <div><b>Phone:</b> {COMPANY.phone1} / {COMPANY.phone2}</div>
      </div>
    </div>

    {/* Saved customers */}
    <div style={{background:T.paperWhite,border:`1px solid ${T.line}`,borderRadius:3,padding:20}}>
      <div style={{fontFamily:FD,fontWeight:600,fontSize:16,marginBottom:4,color:T.ink}}>Regular customers</div>
      <div style={{fontSize:12,color:T.inkMuted,marginBottom:14}}>These appear in the quick-select dropdown when creating new orders</div>

      <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(140px,1fr))",gap:10,marginBottom:12}}>
        {[["Name","name"],["Business","business"],["Phone","phone"],["Usual location","delivery_location"]].map(([l,k])=>(
          <div key={k}>
            <label style={IL}>{l}</label>
            <input value={newCust[k]} onChange={e=>setNewCust(c=>({...c,[k]:e.target.value}))} style={II}/>
          </div>
        ))}
      </div>
      <button onClick={addCustomer} disabled={!newCust.name.trim()} style={{...BTN(),background:T.moss,color:T.paperWhite,marginBottom:16}}>+ Add customer</button>

      {savedCustomers?.length>0
        ?<div style={{display:"grid",gap:6}}>
          {savedCustomers.map(c=>(
            <div key={c.id} style={{display:"flex",justifyContent:"space-between",alignItems:"center",padding:"9px 12px",background:T.paper,borderRadius:2,flexWrap:"wrap",gap:8}}>
              <div>
                <span style={{fontWeight:600,fontSize:13,color:T.ink}}>{c.name}</span>
                {c.business&&<span style={{fontSize:12,color:T.inkMuted,marginLeft:8}}>{c.business}</span>}
                {c.phone&&<span style={{fontSize:12,color:T.inkMuted,marginLeft:8,fontFamily:FM}}>{c.phone}</span>}
              </div>
              <button onClick={()=>onDeleteCustomer(c.id,c.name)} style={{background:"none",border:"none",cursor:"pointer",color:T.clay,fontSize:12}}>Remove</button>
            </div>
          ))}
        </div>
        :<div style={{fontSize:13,color:T.inkMuted,fontStyle:"italic",fontFamily:FD}}>No saved customers yet</div>
      }
    </div>

    {/* Rename customer */}
    <div style={{background:T.paperWhite,border:`1px solid ${T.line}`,borderRadius:3,padding:20}}>
      <div style={{fontFamily:FD,fontWeight:600,fontSize:16,marginBottom:6,color:T.ink}}>Rename customer</div>
      <div style={{fontSize:12,color:T.inkMuted,marginBottom:14}}>
        Renames everywhere — saved list, all orders, all ledger entries. Cannot be undone.
      </div>
      <RenameCustomer savedCustomers={savedCustomers} onRenamed={onRenameCustomer}/>
    </div>

    {/* Ledger sync */}
    <div style={{background:T.paperWhite,border:`1px solid ${T.line}`,borderRadius:3,padding:20}}>
      <div style={{fontFamily:FD,fontWeight:600,fontSize:16,marginBottom:6,color:T.ink}}>Sync accounts ledger</div>
      <div style={{fontSize:12,color:T.inkMuted,marginBottom:14}}>
        Finds every delivered order that has no ledger entry and creates the missing ones.
        Safe to run multiple times — never duplicates. Run this if your accounts balance doesn't match your delivered orders.
      </div>
      {syncResult!=null&&<div style={{background:syncResult.fixed>0?"#E3E9DE":"#F0F0EA",color:syncResult.fixed>0?T.moss:T.inkMuted,padding:"10px 14px",borderRadius:2,marginBottom:14,fontSize:13,borderLeft:`3px solid ${syncResult.fixed>0?T.moss:T.line}`}}>
        {syncResult.fixed>0?`✅ Fixed ${syncResult.fixed} missing ${syncResult.fixed===1?"entry":"entries"} — accounts are now in sync.`:"✓ Nothing to fix — all delivered orders already have ledger entries."}
      </div>}
      <button onClick={async()=>{
        setSyncing(true);setSyncResult(null);
        const r=await onSyncLedger();
        setSyncResult(r||{fixed:0});
        setSyncing(false);
      }} disabled={syncing} style={{...BTN(),background:T.moss,color:T.paperWhite}}>
        {syncing?"Scanning…":"Run sync now"}
      </button>
    </div>

    {/* Create staff */}
    <div style={{background:T.paperWhite,border:`1px solid ${T.line}`,borderRadius:3,padding:20}}>
      <div style={{fontFamily:FD,fontWeight:600,fontSize:16,marginBottom:14,color:T.ink}}>Create staff account</div>
      {msg&&<div style={{background:msg.startsWith("✅")?"#E3E9DE":"#F3E3DC",color:msg.startsWith("✅")?T.moss:T.clay,padding:"10px 14px",borderRadius:2,marginBottom:14,fontSize:13,borderLeft:`3px solid ${msg.startsWith("✅")?T.moss:T.clay}`}}>{msg}</div>}
      <div style={{display:"grid",gap:12}}>
        {[["Full name","name","text"],["Email","email","email"],["Password","password","password"]].map(([l,k,t])=>(
          <div key={k}>
            <label style={IL}>{l}</label>
            <input type={t} value={k==="name"?name:k==="email"?email:password}
              onChange={e=>k==="name"?setName(e.target.value):k==="email"?setEmail(e.target.value):setPassword(e.target.value)} style={II}/>
          </div>
        ))}
        <div>
          <label style={IL}>Role</label>
          <select value={role} onChange={e=>setRole(e.target.value)} style={II}>
            <option value="staff">Packing staff</option>
            <option value="admin">Admin</option>
          </select>
        </div>
        <button onClick={createUser} disabled={loading||!email||!password||!name} style={{...BTN(),background:T.moss,color:T.paperWhite,padding:"12px 0"}}>
          {loading?"Creating…":"Create account"}
        </button>
      </div>
      <div style={{marginTop:14,padding:"10px 14px",background:T.paper,borderRadius:2,fontSize:12,color:T.inkMuted,borderLeft:`3px solid ${T.gold}`}}>
        Staff can sign in at this same URL. Admin sees all tabs; staff only sees the Dashboard.
      </div>
    </div>

    {/* Existing accounts */}
    <div style={{background:T.paperWhite,border:`1px solid ${T.line}`,borderRadius:3,padding:20}}>
      <div style={{fontFamily:FD,fontWeight:600,fontSize:16,marginBottom:14,color:T.ink}}>Existing accounts</div>
      {accountsLoading
        ?<div style={{fontSize:13,color:T.inkMuted}}>Loading…</div>
        :accounts.length===0
        ?<div style={{fontSize:13,color:T.inkMuted,fontStyle:"italic",fontFamily:FD}}>No accounts found</div>
        :<div style={{display:"grid",gap:6}}>
          {accounts.map(a=>(
            <div key={a.id} style={{display:"flex",justifyContent:"space-between",alignItems:"center",padding:"10px 12px",background:T.paper,borderRadius:2,flexWrap:"wrap",gap:8}}>
              <div>
                <div style={{display:"flex",alignItems:"center",gap:8}}>
                  <span style={{fontWeight:600,fontSize:13,color:T.ink}}>{a.name||"(no name)"}</span>
                  <span style={{fontSize:9,color:a.role==="admin"?T.moss:"#4A7BA6",fontFamily:FM,textTransform:"uppercase",letterSpacing:"0.04em",border:`1px solid ${a.role==="admin"?T.moss:"#4A7BA6"}`,borderRadius:2,padding:"1px 6px"}}>{a.role}</span>
                  {a.id===currentUserId&&<span style={{fontSize:9,color:T.inkMuted,fontFamily:FM}}>(you)</span>}
                </div>
                {a.email&&<div style={{fontSize:11,color:T.inkMuted,marginTop:2}}>{a.email}</div>}
              </div>
              {a.id!==currentUserId&&
                <button onClick={()=>deleteAccount(a.id,a.name||a.email)} style={{background:"none",border:"none",cursor:"pointer",color:T.clay,fontSize:12}}>Remove</button>
              }
            </div>
          ))}
        </div>
      }
    </div>

    {/* Recent activity */}
    <div style={{background:T.paperWhite,border:`1px solid ${T.line}`,borderRadius:3,padding:20}}>
      <div style={{fontFamily:FD,fontWeight:600,fontSize:16,marginBottom:4,color:T.ink}}>Recent activity</div>
      <div style={{fontSize:12,color:T.inkMuted,marginBottom:14}}>Who changed rates, deleted orders/entries, or added/removed staff — last 100 actions</div>
      {activityLoading
        ?<div style={{fontSize:13,color:T.inkMuted}}>Loading…</div>
        :activity.length===0
        ?<div style={{fontSize:13,color:T.inkMuted,fontStyle:"italic",fontFamily:FD}}>No activity recorded yet</div>
        :<div style={{display:"grid",gap:6,maxHeight:400,overflowY:"auto"}}>
          {activity.map(a=>(
            <div key={a.id} style={{padding:"9px 12px",background:T.paper,borderRadius:2}}>
              <div style={{display:"flex",justifyContent:"space-between",gap:8,flexWrap:"wrap"}}>
                <span style={{fontWeight:600,fontSize:13,color:T.ink}}>{a.action}</span>
                <span style={{fontSize:11,color:T.inkMuted,fontFamily:FM}}>{new Date(a.created_at).toLocaleString("en-IN")}</span>
              </div>
              {a.details&&<div style={{fontSize:12,color:T.inkMuted,marginTop:3}}>{a.details}</div>}
              <div style={{fontSize:11,color:T.inkMuted,marginTop:3,fontFamily:FM}}>{a.actor_name||a.actor_email||"Unknown"}</div>
            </div>
          ))}
        </div>
      }
    </div>
  </div>;
}

// ─── MAIN APP ─────────────────────────────────────────────────────────────────
export default function App(){
  const [user,setUser]=useState(null);
  const [loading,setLoading]=useState(true);
  const [orders,setOrders]=useState([]);
  const [inventory,setInventory]=useState({});
  const [tab,setTab]=useState("dashboard");
  const [viewOrder,setViewOrder]=useState(null);
  const [editOrder,setEditOrder]=useState(null);
  const [printOrder,setPrintOrder]=useState(null);
  const [toast,setToast]=useState(null);
  const [logo,setLogo]=useState(COMPANY.logo);
  const [savedCustomers,setSavedCustomers]=useState([]);
  const [ledgerEntries,setLedgerEntries]=useState([]);
  const [savedVendors,setSavedVendors]=useState([]);
  const [showOldBrowserBanner,setShowOldBrowserBanner]=useState(false);

  // ── Old browser detection ─────────────────────────────────────────────────
  // Flags outdated Chrome/Chromium builds (e.g. old Android tablets stuck on
  // Chrome <90) where CSS flex/grid `gap` and other modern features silently
  // fail instead of throwing errors — so layout looks broken with no clear cause.
  useEffect(()=>{
    const ua=navigator.userAgent;
    const chromeMatch=ua.match(/Chrome\/(\d+)/);
    const chromeVersion=chromeMatch?parseInt(chromeMatch[1],10):null;
    const dismissed=localStorage.getItem?.("eg_old_browser_dismissed")==="1";
    if(chromeVersion&&chromeVersion<90&&!dismissed){
      setShowOldBrowserBanner(true);
    }
  },[]);

  function dismissOldBrowserBanner(){
    setShowOldBrowserBanner(false);
    try{localStorage.setItem("eg_old_browser_dismissed","1");}catch(e){}
  }

  // ── Browser back/forward button support ──────────────────────────────────
  // Push state when tab changes so back button navigates between tabs
  // instead of falling off the SPA back to a blank page.
  function navigateTo(newTab){
    window.history.pushState({tab:newTab},"",`#${newTab}`);
    setTab(newTab);
  }

  useEffect(()=>{
    window.history.replaceState({tab:"dashboard"},"","#dashboard");
    const onPop=e=>{
      const state=e.state||{};
      // If the state has a party key, AccountsPanel's own listener handles it — don't interfere
      if(state.party)return;
      const t=state.tab||"dashboard";
      setTab(t);
      setViewOrder(null);
      setEditOrder(null);
    };
    window.addEventListener("popstate",onPop);
    return()=>window.removeEventListener("popstate",onPop);
  },[]);

  // ── Session restore ───────────────────────────────────────────────────────
  useEffect(()=>{
    supabase.auth.getSession().then(async({data:{session}})=>{
      if(session){
        const{data:profile}=await supabase.from("profiles").select("*").eq("id",session.user.id).single();
        setUser({...session.user,role:profile?.role||"staff",name:profile?.name||session.user.email});
        setTab(profile?.role==="admin"?"dashboard":"dashboard");
      }
      setLoading(false);
    });
    supabase.auth.onAuthStateChange(async(event,session)=>{
      if(!session){setUser(null);}
    });
  },[]);

  useEffect(()=>{
    // Kill the 300ms tap delay on iOS/Android
    const s=document.createElement("style");
    s.textContent="*{touch-action:manipulation;-webkit-tap-highlight-color:transparent;}";
    document.head.appendChild(s);
    return()=>document.head.removeChild(s);
  },[]);

  useEffect(()=>{
    if(!user)return;
    fetchOrders();
    fetchInventory();
    fetchSavedCustomers();
    fetchSavedVendors();
    fetchLogo();
    fetchLedger();
    // Realtime — debounced so rapid back-to-back changes don't trigger dozens of re-fetches.
    // NOTE: this only works if Realtime replication is switched on for each of
    // these tables in the Supabase dashboard (Database > Replication) — the
    // subscribe() status is logged below specifically to catch that silently
    // failing.
    let ordersTimer,ledgerTimer,inventoryTimer,customersTimer,vendorsTimer,logoTimer;
    const ch=supabase.channel("app-rt")
      .on("postgres_changes",{event:"*",schema:"public",table:"orders"},()=>{clearTimeout(ordersTimer);ordersTimer=setTimeout(fetchOrders,400);})
      .on("postgres_changes",{event:"*",schema:"public",table:"ledger_entries"},()=>{clearTimeout(ledgerTimer);ledgerTimer=setTimeout(fetchLedger,400);})
      .on("postgres_changes",{event:"*",schema:"public",table:"inventory"},()=>{clearTimeout(inventoryTimer);inventoryTimer=setTimeout(fetchInventory,400);})
      .on("postgres_changes",{event:"*",schema:"public",table:"saved_customers"},()=>{clearTimeout(customersTimer);customersTimer=setTimeout(fetchSavedCustomers,400);})
      .on("postgres_changes",{event:"*",schema:"public",table:"saved_vendors"},()=>{clearTimeout(vendorsTimer);vendorsTimer=setTimeout(fetchSavedVendors,400);})
      .on("postgres_changes",{event:"*",schema:"public",table:"company_settings"},()=>{clearTimeout(logoTimer);logoTimer=setTimeout(fetchLogo,400);})
      .subscribe((status,err)=>{
        if(status==="CHANNEL_ERROR"||status==="TIMED_OUT"){
          console.error("Realtime subscription failed ("+status+") — live updates for other users won't work until this is fixed. Check that Realtime replication is enabled for every table in the Supabase dashboard.",err);
        }
      });
    return()=>{
      clearTimeout(ordersTimer);clearTimeout(ledgerTimer);clearTimeout(inventoryTimer);
      clearTimeout(customersTimer);clearTimeout(vendorsTimer);clearTimeout(logoTimer);
      supabase.removeChannel(ch);
    };
  },[user]);

  async function fetchLogo(){
    const{data}=await supabase.from("company_settings").select("*").eq("id","main").single();
    if(data?.logo_base64){
      COMPANY.logo=data.logo_base64;
      setLogo(data.logo_base64);
    }
  }

  async function fetchLedger(){
    // PostgREST caps an unbounded select at 1000 rows — this table is already past
    // that, and sorted oldest-last, so old rows (e.g. every "Opening Balance" entry,
    // dated 2000-01-01) silently fall off the end. Page through until exhausted.
    const pageSize=1000;
    let all=[],from=0;
    while(true){
      const{data}=await supabase.from("ledger_entries").select("*")
        .order("date",{ascending:false}).order("created_at",{ascending:false})
        .range(from,from+pageSize-1);
      if(!data?.length)break;
      all=all.concat(data);
      if(data.length<pageSize)break;
      from+=pageSize;
    }
    setLedgerEntries(all);
  }

  // Auto-record: every order placed counts as a Debit (Udhar) entry for that customer
  // (they now owe the business this amount), unless it's worth zero.
  async function recordOrderLedgerEntry(order){
    if(!order?.customer)return;
    const total=orderTotal(order,inventory);
    if(!total)return;
    const entries=[{
      party_name:order.customer,party_type:"customer",entry_type:"gave",
      amount:total,date:order.order_date||today(),notes:`Order ${order.id}`,
      linked_order_id:order.id,
    }];
    // Cash/walk-in orders: immediately add matching credit (payment received)
    // so the balance stays zero — the sale is still recorded for analytics.
    if(order.is_cash){
      entries.push({
        party_name:order.customer,party_type:"customer",entry_type:"got",
        amount:total,date:order.order_date||today(),notes:`Cash payment — Order ${order.id}`,
        linked_order_id:order.id,
      });
    }
    await supabase.from("ledger_entries").insert(entries);
    fetchLedger();
  }

  // Auto-record: every purchase counts as a Credit (Jama) entry for that vendor
  // (the business now owes the vendor this amount), unless it's worth zero.
  async function recordPurchaseLedgerEntry(purchase){
    if(!purchase?.vendor)return;
    const total=purchase.total||(purchase.qty||0)*(purchase.rate||0);
    if(!total)return;
    const notes=purchase.itemSummary?`Purchase: ${purchase.itemSummary}`:`Purchase: ${purchase.item||""}`;
    await supabase.from("ledger_entries").insert([{
      party_name:purchase.vendor,party_type:"supplier",entry_type:"got",
      amount:total,date:purchase.date||today(),notes,
      linked_purchase_id:purchase.id,
    }]);
    fetchLedger();
  }

  async function addManualLedgerEntry(entry){
    await supabase.from("ledger_entries").insert([entry]);
    fetchLedger();
  }

  async function editLedgerEntry(){
    // The actual update is done inside AccountsPanel directly via supabase.
    // This callback just triggers a parent re-fetch so the UI reflects the change.
    fetchLedger();
  }

  async function syncLedgerEntries(){
    const deliveredOrders=orders.filter(o=>o.status==="Delivered");
    const linkedIds=new Set(ledgerEntries.map(e=>e.linked_order_id).filter(Boolean));
    const missing=deliveredOrders.filter(o=>!linkedIds.has(o.id));
    if(!missing.length)return{fixed:0};
    const rows=[];
    for(const order of missing){
      const total=orderTotal(order,inventory);
      if(!total||!order.customer)continue;
      rows.push({
        party_name:order.customer,party_type:"customer",entry_type:"gave",
        amount:total,date:order.order_date||today(),
        notes:`Order ${order.id}`,linked_order_id:order.id,
      });
      if(order.is_cash){
        rows.push({
          party_name:order.customer,party_type:"customer",entry_type:"got",
          amount:total,date:order.order_date||today(),
          notes:`Cash payment — Order ${order.id}`,linked_order_id:order.id,
        });
      }
    }
    if(rows.length)await supabase.from("ledger_entries").insert(rows);
    fetchLedger();
    return{fixed:missing.length};
  }

  async function deleteLedgerEntry(id){
    if(!window.confirm("Delete this ledger entry? This will affect the account balance."))return;
    const entry=ledgerEntries.find(e=>e.id===id);
    await supabase.from("ledger_entries").delete().eq("id",id);
    setLedgerEntries(prev=>prev.filter(e=>e.id!==id));
    logActivity(user,"Ledger entry deleted",entry?`${entry.party_name} — ${fmtMoney(entry.amount)} (${entry.entry_type})`:`id ${id}`);
  }

  async function fetchOrders(){
    const{data}=await supabase.from("orders").select("*").order("created_at",{ascending:false});
    setOrders(data||[]);
  }

  async function fetchSavedCustomers(){
    const{data}=await supabase.from("saved_customers").select("*").order("name");
    setSavedCustomers(data||[]);
  }

  async function fetchSavedVendors(){
    const{data}=await supabase.from("saved_vendors").select("*").order("name");
    setSavedVendors(data||[]);
  }

  async function addSavedVendor(vendor){
    if(!vendor.name?.trim())return;
    const exists=savedVendors.find(v=>v.name.toLowerCase()===vendor.name.toLowerCase());
    if(exists)return;
    const{data,error}=await supabase.from("saved_vendors").insert([{name:vendor.name}]).select();
    if(!error&&data)setSavedVendors(prev=>[...prev,data[0]].sort((a,b)=>a.name.localeCompare(b.name)));
  }

  async function deleteSavedVendor(id){
    if(!window.confirm("Remove this vendor from your saved list?"))return;
    await supabase.from("saved_vendors").delete().eq("id",id);
    setSavedVendors(prev=>prev.filter(v=>v.id!==id));
  }

  async function addSavedCustomer(customer){
    if(!customer.name?.trim())return;
    const exists=savedCustomers.find(c=>c.name.toLowerCase()===customer.name.toLowerCase());
    if(exists)return;
    const{data,error}=await supabase.from("saved_customers").insert([customer]).select();
    if(!error&&data)setSavedCustomers(prev=>[...prev,data[0]].sort((a,b)=>a.name.localeCompare(b.name)));
  }

  async function deleteSavedCustomer(id,name){
    if(!window.confirm(`Remove "${name||"this customer"}" from saved customers? Their orders and ledger history are not affected.`))return;
    await supabase.from("saved_customers").delete().eq("id",id);
    setSavedCustomers(prev=>prev.filter(c=>c.id!==id));
  }

  async function fetchInventory(){
    const{data}=await supabase.from("inventory").select("*");
    const map={};
    (data||[]).forEach(it=>{map[it.name]={qty:it.qty,unit:it.unit,rate:it.rate||DEFAULT_RATES[it.name]||0,customerRates:it.customer_rates||{}};});

    // Merge in any catalog items that don't exist in the database yet —
    // this keeps the live inventory in sync if the master item list is updated later,
    // without touching existing quantities/rates for items already there.
    const missing=DEFAULT_ITEMS.filter(n=>!map[n]);
    if(missing.length){
      const toAdd=missing.map(n=>({name:n,qty:100,unit:DEFAULT_UNITS[n]||"kg",rate:DEFAULT_RATES[n]||0,customer_rates:{}}));
      await supabase.from("inventory").upsert(toAdd);
      toAdd.forEach(it=>{map[it.name]={qty:it.qty,unit:it.unit,rate:it.rate,customerRates:{}};});
    }
    setInventory(map);
  }

  function showToast(msg,type="success"){
    setToast({msg,type});
    setTimeout(()=>setToast(null),3500);
  }

  async function handleUpdateStatus(id,newStatus){
    const order=orders.find(o=>o.id===id);
    const{error}=await supabase.from("orders").update({status:newStatus}).eq("id",id);
    if(error){showToast("Failed to update order status — try again","error");return false;}
    setOrders(prev=>prev.map(o=>o.id===id?{...o,status:newStatus}:o));

    // Adjust inventory: deduct when marked Delivered, restore if un-marked
    if(order&&order.status!==newStatus){
      const direction=newStatus==="Delivered"?-1:(order.status==="Delivered"?1:0);
      if(direction!==0){
        const updates={};
        (order.items||[]).forEach(it=>{
          const rawQty=it.actual_qty??it.qty;
          const current=inventory[it.name];
          if(current){
            // Convert to base unit before deducting — 500 grams = 0.5kg
            // Not clamped to 0: a delivery that oversubtracts stock must leave
            // qty negative (backorder) so un-marking Delivered restores the
            // exact amount instead of over-crediting inventory.
            const baseQty=toBaseQty(rawQty,it.unit,current.unit||"kg");
            const newQty=current.qty+direction*baseQty;
            updates[it.name]={...current,qty:newQty};
          }
        });
        if(Object.keys(updates).length){
          const merged={...inventory,...updates};
          setInventory(merged);
          await supabase.from("inventory").upsert(
            Object.entries(updates).map(([name,v])=>({name,qty:v.qty,unit:v.unit,rate:v.rate}))
          );
        }
      }

      // Ledger: record when delivered, remove if un-delivered
      if(newStatus==="Delivered"){
        recordOrderLedgerEntry({...order,status:newStatus});
      } else if(order.status==="Delivered"){
        // Remove the ledger entry that was created when it was delivered
        const{data}=await supabase.from("ledger_entries").select("id").eq("linked_order_id",id);
        if(data?.length){
          await supabase.from("ledger_entries").delete().eq("linked_order_id",id);
          fetchLedger();
        }
      }
    }
    showToast(newStatus==="Delivered"?"Order delivered — accounts updated":`Order marked "${newStatus}"`);
    return true;
  }

  // Statuses not in STATUS_FLOW (e.g. legacy "New Order" rows) fall back to
  // the first step instead of relying on indexOf(-1)+1 landing there by luck.
  function nextStatusFor(status){
    return STATUS_FLOW.includes(status)?STATUS_FLOW[STATUS_FLOW.indexOf(status)+1]:STATUS_FLOW[0];
  }

  async function handleMarkPaid(id,method){
    await supabase.from("orders").update({is_paid:true,payment_method:method}).eq("id",id);
    setOrders(prev=>prev.map(o=>o.id===id?{...o,is_paid:true,payment_method:method}:o));
    showToast(`Payment recorded — ${method==="cash"?"Cash":"Paytm"}`);
  }

  async function handleDelete(id){
    if(!window.confirm("Delete this order permanently?"))return;
    const order=orders.find(o=>o.id===id);
    await supabase.from("orders").delete().eq("id",id);
    // Also remove any ledger entries linked to this order
    await supabase.from("ledger_entries").delete().eq("linked_order_id",id);
    setOrders(prev=>prev.filter(o=>o.id!==id));
    fetchLedger();
    showToast("Order deleted");
    logActivity(user,"Order deleted",order?`${id} — ${order.customer||"unknown customer"}`:id);
  }

  // When an order has item-level rate overrides, save them as the customer's
  // remembered rates in inventory so they auto-apply next time for same customer.
  async function learnCustomerRates(order){
    if(!order?.customer)return;
    const customer=order.customer;
    const itemsToLearn=(order.items||[]).filter(it=>it.override_rate!=null&&it.override_rate!=="");
    if(!itemsToLearn.length)return;

    const updatedInventory={...inventory};
    const upsertRows=[];

    for(const it of itemsToLearn){
      const rate=parseFloat(it.override_rate);
      if((!rate&&rate!==0)||!it.name)continue;
      const current=updatedInventory[it.name];
      if(!current)continue;
      const updatedRates={...(current.customerRates||{}),[customer]:rate};
      updatedInventory[it.name]={...current,customerRates:updatedRates};
      upsertRows.push({name:it.name,qty:current.qty,unit:current.unit,rate:current.rate,customer_rates:updatedRates});
    }

    if(upsertRows.length){
      await supabase.from("inventory").upsert(upsertRows);
      setInventory(updatedInventory);
    }
  }

  async function handleOrderSaved(order){
    const wasNewOrder=!editOrder?.id;

    // If editing and customer name changed, update linked ledger entries too
    if(!wasNewOrder&&editOrder?.customer&&editOrder.customer!==order.customer){
      await supabase.from("ledger_entries")
        .update({party_name:order.customer})
        .eq("linked_order_id",order.id);
    }

    // If editing and is_cash changed, fix ledger entries for delivered orders
    if(!wasNewOrder&&order.status==="Delivered"&&editOrder?.is_cash!==order.is_cash){
      const wasCash=editOrder?.is_cash;
      const nowCash=order.is_cash;
      const total=orderTotal(order,inventory);

      if(wasCash&&!nowCash){
        // Was cash → now regular: remove the auto-credit "Cash payment" entry
        await supabase.from("ledger_entries")
          .delete()
          .eq("linked_order_id",order.id)
          .eq("entry_type","got");
        showToast("Switched to regular — balance now outstanding in accounts");
      } else if(!wasCash&&nowCash){
        // Before adding auto-credit, check if unlinked manual credits exist for this customer.
        // If they do, adding a full auto-credit would double-count any partial payments already recorded.
        const{data:existingCredits}=await supabase.from("ledger_entries")
          .select("id,amount,notes")
          .eq("party_name",order.customer)
          .eq("entry_type","got")
          .is("linked_order_id",null)
          .is("linked_purchase_id",null);

        const manualCreditTotal=(existingCredits||[]).reduce((s,e)=>s+e.amount,0);

        if(manualCreditTotal>0){
          const proceed=window.confirm(
            `⚠ Warning: ${order.customer} already has ₹${manualCreditTotal.toLocaleString("en-IN")} in manually recorded payments in accounts.\n\nSwitching to cash will add another ₹${total.toLocaleString("en-IN")} auto-credit — this may cause double-counting.\n\nProceed anyway?`
          );
          if(!proceed){
            // Abort — revert the is_cash field on the order since we're not fixing ledger
            await supabase.from("orders").update({is_cash:false}).eq("id",order.id);
            fetchOrders();
            setEditOrder(null);
            showToast("Cancelled — order kept as regular","error");
            fetchLedger();
            return;
          }
        }

        // Safe to insert auto-credit
        await supabase.from("ledger_entries").insert([{
          party_name:order.customer,party_type:"customer",entry_type:"got",
          amount:total,date:order.order_date||today(),
          notes:`Cash payment — Order ${order.id}`,linked_order_id:order.id,
        }]);
        showToast("Switched to cash — balance cleared in accounts");
      }
      fetchLedger();
    }

    fetchOrders();
    setEditOrder(null);
    if(wasNewOrder)showToast("Order created — "+order.id);
    else if(editOrder?.is_cash===order.is_cash)showToast("Order updated");
    learnCustomerRates(order);
    // No ledger entry here — only recorded on delivery
  }

  function handleOrderCreated(order){
    setOrders(prev=>[order,...prev]);
    showToast("Order created — "+order.id);
    navigateTo("dashboard");
    learnCustomerRates(order);
    // No ledger entry here — only recorded on delivery
  }

  async function handleLogout(){
    await supabase.auth.signOut();
    setUser(null);
  }

  // Auto-logout after a period of inactivity (security: don't leave a session
  // open indefinitely on a shared packing-floor device).
  const INACTIVITY_LIMIT_MS=30*60*1000; // 30 minutes
  useEffect(()=>{
    if(!user)return;
    let timer;
    const reset=()=>{
      clearTimeout(timer);
      timer=setTimeout(()=>{
        handleLogout();
        showToast("Logged out after 30 minutes of inactivity.","error");
      },INACTIVITY_LIMIT_MS);
    };
    const events=["mousedown","keydown","touchstart","scroll"];
    events.forEach(ev=>window.addEventListener(ev,reset));
    reset();
    return()=>{ clearTimeout(timer); events.forEach(ev=>window.removeEventListener(ev,reset)); };
  },[user]);

  if(loading)return <div style={{minHeight:"100vh",display:"flex",alignItems:"center",justifyContent:"center",background:T.moss,fontFamily:FD,color:T.paperWhite,fontSize:18}}><Fonts/>Loading…</div>;
  if(!user)return <LoginPage onLogin={setUser}/>;

  const isAdmin=user.role==="admin";
  const allCustomerNames=[...new Set([...savedCustomers.map(c=>c.name),...orders.map(o=>o.customer).filter(Boolean)])].sort();
  const TABS=isAdmin
    ?[{id:"new-order",label:"New Order"},{id:"dashboard",label:"Dashboard"},{id:"inventory",label:"Inventory"},{id:"purchases",label:"Purchases"},{id:"accounts",label:"Accounts"},{id:"analytics",label:"Analytics"},{id:"admin",label:"Admin"}]
    :[{id:"new-order",label:"New Order"},{id:"dashboard",label:"Dashboard"}];

  return <div style={{fontFamily:FB,minHeight:"100vh",background:T.paper}}>
    <Fonts/>
    {showOldBrowserBanner&&<div style={{background:"#8A5A1F",color:"#fff",padding:"10px 16px",display:"flex",alignItems:"center",justifyContent:"space-between",gap:10,flexWrap:"wrap",fontSize:13,fontFamily:FB,position:"sticky",top:0,zIndex:200}}>
      <span>⚠ Your browser is outdated — some spacing and layout may look off. For the best experience, please update Chrome or use a different device.</span>
      <button onClick={dismissOldBrowserBanner} style={{background:"rgba(255,255,255,0.15)",border:"1px solid rgba(255,255,255,0.4)",color:"#fff",borderRadius:3,padding:"5px 12px",cursor:"pointer",fontSize:12,fontFamily:FB,flexShrink:0}}>Dismiss</button>
    </div>}
    {/* Header */}
    <div style={{background:T.paperWhite,borderBottom:`1px solid ${T.line}`,padding:"10px 16px",display:"flex",alignItems:"center",justifyContent:"space-between",position:"sticky",top:0,zIndex:100,flexWrap:"wrap",gap:10}}>
      <div style={{display:"flex",alignItems:"center",gap:10}}>
        {logo
          ?<img src={logo} alt="logo" style={{height:32,objectFit:"contain"}}/>
          :<div style={{width:32,height:32,borderRadius:"50%",background:T.moss,display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0}}><span style={{color:T.gold,fontFamily:FD,fontWeight:700,fontSize:14}}>EG</span></div>
        }
        <div>
          <div style={{fontFamily:FD,fontWeight:600,fontSize:16,color:T.ink}}>Exotic Greens</div>
          <div style={{fontSize:9,color:T.inkMuted,fontFamily:FM,textTransform:"uppercase",letterSpacing:"0.04em"}}>Billing &amp; Order Management</div>
        </div>
      </div>
      <div style={{display:"flex",gap:2,flexWrap:"wrap",order:3,width:"100%"}}>
        {TABS.map(t=>(
          <button key={t.id} onClick={()=>navigateTo(t.id)} style={{padding:"7px 13px",borderRadius:3,border:"none",background:tab===t.id?T.moss:T.paper,color:tab===t.id?T.paperWhite:T.inkMuted,cursor:"pointer",fontWeight:tab===t.id?700:600,fontSize:13,fontFamily:FB}}>
            {t.label}
          </button>
        ))}
      </div>
      <div style={{display:"flex",alignItems:"center",gap:10}}>
        <div style={{textAlign:"right"}}>
          <div style={{fontWeight:600,fontSize:12,color:T.ink}}>{user.name}</div>
          <div style={{fontSize:9,color:isAdmin?T.moss:"#4A7BA6",fontFamily:FM,textTransform:"uppercase",letterSpacing:"0.04em"}}>{user.role}</div>
        </div>
        <button onClick={handleLogout} style={{...BTN(),padding:"6px 12px",border:`1px solid ${T.line}`,background:"transparent",color:T.inkMuted,fontSize:11}}>Logout</button>
      </div>
    </div>

    {/* Body */}
    <div style={{maxWidth:1000,margin:"0 auto",padding:"20px 14px"}}>
      {tab==="new-order"&&<OrderIntake onOrderCreated={handleOrderCreated} inventory={inventory} savedCustomers={savedCustomers} onSaveCustomer={addSavedCustomer}/> }
      {tab==="dashboard"&&<Dashboard orders={orders} inventory={inventory} onUpdateStatus={handleUpdateStatus} onView={setViewOrder} onEdit={o=>{setEditOrder(o);}} onDelete={handleDelete} onPrint={o=>setPrintOrder(o)} onNew={()=>setEditOrder({})} userRole={user.role} onUpdateActualQty={async(orderId,items)=>{
        setOrders(prev=>prev.map(o=>o.id===orderId?{...o,items}:o));
        // Sync ledger: recalculate total with new actual weights and update the linked entry
        const order=orders.find(o=>o.id===orderId);
        if(order?.status==="Delivered"){
          const updatedOrder={...order,items};
          const newTotal=orderTotal(updatedOrder,inventory);
          await supabase.from("ledger_entries")
            .update({amount:newTotal})
            .eq("linked_order_id",orderId)
            .eq("entry_type","gave");
          fetchLedger();
        }
      }} onMarkPaid={handleMarkPaid}/>}
      {tab==="inventory"&&isAdmin&&<InventoryPanel inventory={inventory} onUpdate={setInventory} customers={allCustomerNames} user={user}/>}
      {tab==="purchases"&&isAdmin&&<Purchases inventory={inventory} onInventoryUpdate={setInventory} onPurchaseSaved={recordPurchaseLedgerEntry} savedVendors={savedVendors} onSaveVendor={addSavedVendor}/>}
      {tab==="accounts"&&isAdmin&&<AccountsPanel ledgerEntries={ledgerEntries} onAddEntry={addManualLedgerEntry} onDeleteEntry={deleteLedgerEntry} onEditEntry={editLedgerEntry} savedCustomers={savedCustomers} purchaseVendors={savedVendors.map(v=>v.name)} orders={orders} onDeleteOrder={handleDelete} inventory={inventory} onSaveCustomer={addSavedCustomer} user={user}/>}
      {tab==="analytics"&&isAdmin&&<Analytics orders={orders} inventory={inventory}/>}
      {tab==="admin"&&isAdmin&&<AdminPanel logo={logo} onLogoChange={setLogo} savedCustomers={savedCustomers} onSaveCustomer={addSavedCustomer} onDeleteCustomer={deleteSavedCustomer} orders={orders} inventory={inventory} ledgerEntries={ledgerEntries} onSyncLedger={syncLedgerEntries} onRenameCustomer={()=>{fetchOrders();fetchLedger();fetchSavedCustomers();}} user={user}/>}
    </div>

    {/* Order detail modal */}
    {viewOrder&&<Modal onClose={()=>setViewOrder(null)} width={560}>
      <ModalHeader title={viewOrder.id} sub={viewOrder.customer} onClose={()=>setViewOrder(null)}/>
      <div style={{padding:22}}>
        <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(200px,1fr))",gap:10,marginBottom:18}}>
          {[["Customer",viewOrder.customer],["Business",viewOrder.business||"–"],["Phone",viewOrder.phone||"–"],["Order Date",viewOrder.order_date],["Delivery Date",viewOrder.delivery_date],["Location",viewOrder.delivery_location||"–"]].map(([k,v])=>(
            <div key={k} style={{background:T.paper,borderRadius:2,padding:"9px 12px"}}>
              <div style={{fontSize:10,color:T.inkMuted,textTransform:"uppercase",letterSpacing:"0.04em",fontFamily:FM}}>{k}</div>
              <div style={{fontSize:13,fontWeight:600,color:T.ink,marginTop:2}}>{v}</div>
            </div>
          ))}
        </div>
        {viewOrder.raw_message&&<div style={{background:"#EDE7DA",borderRadius:2,padding:"11px 14px",marginBottom:16,fontSize:13,color:T.ink,borderLeft:`3px solid ${T.sage}`}}>
          <div style={{fontSize:10,color:T.inkMuted,marginBottom:4,textTransform:"uppercase",letterSpacing:"0.04em",fontFamily:FM}}>Original message</div>
          "{viewOrder.raw_message}"
        </div>}
        <div style={{marginBottom:16}}>
          <div style={{fontWeight:600,fontSize:14,marginBottom:9,color:T.ink,fontFamily:FD}}>Items</div>
          {(viewOrder.items||[]).map((it,i)=>{
            const baseUnit=inventory[it.name]?.unit||"kg";
            const rate=getRate(it.name,inventory,viewOrder.customer);
            const qty=it.actual_qty??it.qty;
            return <div key={i} style={{display:"flex",justifyContent:"space-between",padding:"7px 0",borderBottom:`1px solid ${T.line}`,fontSize:13,gap:8,flexWrap:"wrap",alignItems:"center"}}>
              <span style={{color:T.inkMuted,fontFamily:FM,fontSize:11,minWidth:18}}>{i+1}.</span>
              <span style={{color:T.ink,flex:1}}>{it.name}</span>
              <span style={{color:T.inkMuted,fontFamily:FM}}>{fmtQty(qty)} {it.unit}</span>
              <span style={{color:T.inkMuted,fontFamily:FM}}>{fmtMoney(rate)}/{baseUnit}</span>
              <span style={{color:T.moss,fontFamily:FM,fontWeight:600}}>{fmtMoney(calcAmountDisplay(it,inventory,viewOrder.customer))}</span>
            </div>;
          })}
          <div style={{textAlign:"right",fontWeight:700,fontSize:16,marginTop:10,color:T.moss,fontFamily:FM}}>
            Total: {fmtMoney(orderTotal(viewOrder,inventory))}
          </div>
        </div>
        {viewOrder.notes&&<div style={{background:"#F3E6CC",borderRadius:2,padding:"9px 13px",fontSize:13,marginBottom:16,color:"#8A5A1F",borderLeft:`3px solid ${T.gold}`}}>{viewOrder.notes}</div>}
        <div style={{display:"flex",gap:8}}>
          {nextStatusFor(viewOrder.status)&&(
            <button onClick={async()=>{const ok=await handleUpdateStatus(viewOrder.id,nextStatusFor(viewOrder.status));if(ok)setViewOrder(null);}}
              style={{...BTN(),flex:1,background:T.moss,color:T.paperWhite}}>
              → {nextStatusFor(viewOrder.status)}
            </button>
          )}
          <button onClick={()=>{setViewOrder(null);setPrintOrder(viewOrder);}} style={{...BTN(),flex:1,border:`1px solid ${T.line}`,background:"transparent",color:T.ink}}>Print bill</button>
        </div>
      </div>
    </Modal>}

    {/* Edit/Create order modal */}
    {editOrder!==null&&<OrderForm initial={editOrder?.id?editOrder:null} inventory={inventory} onSave={handleOrderSaved} onClose={()=>setEditOrder(null)} savedCustomers={savedCustomers} onSaveCustomer={addSavedCustomer}/>}

    {/* Packing weight + print */}
    {printOrder&&<PackingWeightModal order={printOrder} inventory={inventory} ledgerEntries={ledgerEntries} onClose={()=>setPrintOrder(null)}/>}

    {toast&&<Toast msg={toast.msg} type={toast.type}/>}
  </div>;
}
